        except Exception:
            continue
        t = d.get("type")
        msg = d.get("message") or {}
        role = msg.get("role", t)
        c = msg.get("content")
        txts = []
        if isinstance(c, str):
            txts = [c]
        elif isinstance(c, list):
            for x in c:
                if isinstance(x, dict):
                    if x.get("type") == "text":
                        txts.append(x["text"])
