                        s = json.dumps(inp)[:300]
                        txts.append(f"[TOOL {x.get('name')}] {s}")
        for txt in txts:
            if "addplus" in txt.lower():
                # show snippet around match
                low = txt.lower()
                idx = 0
                shown = set()
                while True:
                    i = low.find("addplus", idx)
                    if i < 0: break
                    start = max(0, i-400); end = min(len(txt), i+500)
                    snip = txt[start:end]
                    key = snip[:60]
                    if key not in shown:
                        shown.add(key)
                        print(f"\n[{role}] ...{snip}...")
                    idx = i + 7
EOF

