/** @type {import('next').NextConfig} */
const nextConfig = {
  reactStrictMode: true,
  typescript: {
    ignoreBuildErrors: true,
  },
  eslint: {
    ignoreDuringBuilds: true,
  },
  images: {
    remotePatterns: [
      { protocol: 'https', hostname: 'res.cloudinary.com' },
      { protocol: 'https', hostname: 'placehold.co' },
      { protocol: 'https', hostname: 'images.unsplash.com' },
      { protocol: 'https', hostname: 'addplus-api.onrender.com' },
      { protocol: 'http', hostname: 'localhost' },
    ],
  },
  async redirects() {
    return [
      { source: '/vendor/dashboard', destination: '/dashboard', permanent: true },
      { source: '/vendor/dashboard/:path*', destination: '/dashboard/:path*', permanent: true },
      { source: '/vendor/products', destination: '/products', permanent: true },
      { source: '/vendor/products/new', destination: '/products/new', permanent: true },
      { source: '/vendor/products/:id/edit', destination: '/products/:id/edit', permanent: true },
      { source: '/onboarding', destination: '/signup?type=vendor', permanent: false },
    ];
  },
  async rewrites() {
    const apiOrigin = process.env.API_URL || process.env.NEXT_PUBLIC_API_ORIGIN;
    if (!apiOrigin) return [];
    const base = apiOrigin.replace(/\/$/, '');
    return [
      { source: '/v1/:path*', destination: `${base}/v1/:path*` },
    ];
  },
};

module.exports = nextConfig;

