1	import NextAuth from "next-auth";
2	import Credentials from "next-auth/providers/credentials";
3	import bcrypt from "bcryptjs";
4	import { eq, and } from "drizzle-orm";
5	import { getMetadataDb } from "@/db/client";
6	import { globalUsers, tenants, tenantMemberships } from "@/db/schema/metadata";
7	import { resolveActiveMembership } from "@/lib/membership";
8	import type { TenantStatus } from "@/lib/auth-urls";
9	
10	async function resolveTenantStatus(userId: string, tenantId: string): Promise<TenantStatus> {
11	  const db = getMetadataDb();
12	  const [row] = await db
13	    .select({ status: tenants.status })
14	    .from(tenantMemberships)
15	    .innerJoin(tenants, eq(tenantMemberships.tenantId, tenants.id))
16	    .where(
17	      and(
18	        eq(tenantMemberships.userId, userId),
19	        eq(tenantMemberships.tenantId, tenantId),
20	        eq(tenantMemberships.isActive, true),
21	      ),
22	    )
23	    .limit(1);
24	
25	  if (!row) return "none";
26	  if (row.status === "suspended") return "suspended";
27	  if (row.status === "pending_approval") return "demo";
28	  if (row.status === "trial_expired") return "trial_expired";
29	  if (row.status === "trial") return "trial";
30	  return "active";
31	}
32	
33	declare module "next-auth" {
34	  interface Session {
35	    user: {
36	      id: string;
37	      email: string;
38	      name?: string | null;
39	      tenantId?: string;
40	      role?: string;
41	      isEmailVerified?: boolean;
42	      tenantStatus?: TenantStatus;
43	    };
44	  }
45	
46	  interface User {
47	    tenantId?: string;
48	    role?: string;
49	    sessionVersion?: number;
50	    isEmailVerified?: boolean;
51	    tenantStatus?: TenantStatus;
52	  }
53	}
54	
55	declare module "@auth/core/jwt" {
56	  interface JWT {
57	    id: string;
58	    email?: string;
59	    name?: string;
60	    tenantId?: string;
61	    role?: string;
62	    sessionVersion?: number;
63	    isEmailVerified?: boolean;
64	    tenantStatus?: TenantStatus;
65	  }
66	}
67	
68	export const { handlers, signIn, signOut, auth } = NextAuth({
69	  trustHost: true,
70	  providers: [
71	    Credentials({
72	      name: "credentials",
73	      credentials: {
74	        email: { label: "Email", type: "email" },
75	        password: { label: "Password", type: "password" },
76	      },
77	      async authorize(credentials) {
78	        if (!credentials?.email || !credentials?.password) return null;
79	
80	        const db = getMetadataDb();
81	        const [user] = await db
82	          .select()
83	          .from(globalUsers)
84	          .where(eq(globalUsers.email, String(credentials.email).toLowerCase()))
85	          .limit(1);
86	
87	        if (!user?.passwordHash) return null;
88	
89	        const valid = await bcrypt.compare(
90	          String(credentials.password),
91	          user.passwordHash,
92	        );
93	        if (!valid) return null;
94	
95	        const membership = await resolveActiveMembership(user.id);
96	
97	        return {
98	          id: user.id,
99	          email: user.email,
100	          name: user.name,
101	          tenantId: membership?.tenantId,
102	          role: membership?.role,
103	          sessionVersion: user.sessionVersion ?? 1,
104	          isEmailVerified: !!user.emailVerified,
105	        };
106	      },
107	    }),
108	  ],
109	  pages: {
110	    signIn: "/login",
111	  },
112	  session: {
113	    strategy: "jwt",
114	    maxAge: 60 * 60 * 24,
115	    updateAge: 60 * 60 * 4,
116	  },
117	  callbacks: {
118	    async jwt({ token, user }) {
119	      if (user) {
120	        token.id = user.id!;
121	        token.email = user.email ?? undefined;
122	        token.name = user.name ?? undefined;
123	        token.tenantId = user.tenantId;
124	        token.role = user.role;
125	        token.sessionVersion = user.sessionVersion ?? 1;
126	        token.isEmailVerified = !!user.isEmailVerified;
127	      }
128	
129	      if (token.id) {
130	        const db = getMetadataDb();
131	        const [user] = await db
132	          .select({
133	            email: globalUsers.email,
134	            name: globalUsers.name,
135	            sessionVersion: globalUsers.sessionVersion,
136	            emailVerified: globalUsers.emailVerified,
137	          })
138	          .from(globalUsers)
139	          .where(eq(globalUsers.id, token.id))
140	          .limit(1);
141	
142	        if (!user) return token;
143	
144	        token.email = user.email;
145	        if (user.name) token.name = user.name;
146	        token.isEmailVerified = !!user.emailVerified;
147	
148	        const currentVersion = user.sessionVersion ?? 1;
149	        if ((token.sessionVersion ?? 1) !== currentVersion) {
150	          token.tenantId = undefined;
151	          token.role = undefined;
152	          token.tenantStatus = "none";
153	          return token;
154	        }
155	
156	        const membership = await resolveActiveMembership(token.id, token.tenantId);
157	        if (!membership) {
158	          token.tenantId = undefined;
159	          token.role = undefined;
160	          token.tenantStatus = "none";
161	          return token;
162	        }
163	
164	        token.tenantId = membership.tenantId;
