import NextAuth from "next-auth";
import Credentials from "next-auth/providers/credentials";
import bcrypt from "bcryptjs";
import { eq, and } from "drizzle-orm";
import { getMetadataDb } from "@/db/client";
import { globalUsers, tenants, tenantMemberships } from "@/db/schema/metadata";
import { resolveActiveMembership } from "@/lib/membership";
import type { TenantStatus } from "@/lib/auth-urls";

async function resolveTenantStatus(userId: string, tenantId: string): Promise<TenantStatus> {
  const db = getMetadataDb();
  const [row] = await db
    .select({ status: tenants.status })
    .from(tenantMemberships)
    .innerJoin(tenants, eq(tenantMemberships.tenantId, tenants.id))
    .where(
      and(
        eq(tenantMemberships.userId, userId),
        eq(tenantMemberships.tenantId, tenantId),
        eq(tenantMemberships.isActive, true),
      ),
    )
    .limit(1);

  if (!row) return "none";
  if (row.status === "suspended") return "suspended";
  if (row.status === "pending_approval") return "demo";
  if (row.status === "trial_expired") return "trial_expired";
  if (row.status === "trial") return "trial";
  return "active";
}

declare module "next-auth" {
  interface Session {
    user: {
      id: string;
      email: string;
      name?: string | null;
      tenantId?: string;
      role?: string;
      isEmailVerified?: boolean;
      tenantStatus?: TenantStatus;
    };
  }

  interface User {
    tenantId?: string;
    role?: string;
    sessionVersion?: number;
    isEmailVerified?: boolean;
    tenantStatus?: TenantStatus;
  }
}

declare module "@auth/core/jwt" {
  interface JWT {
    id: string;
    email?: string;
    name?: string;
    tenantId?: string;
    role?: string;
    sessionVersion?: number;
    isEmailVerified?: boolean;
    tenantStatus?: TenantStatus;
  }
}

export const { handlers, signIn, signOut, auth } = NextAuth({
  trustHost: true,
  providers: [
    Credentials({
      name: "credentials",
      credentials: {
        email: { label: "Email", type: "email" },
        password: { label: "Password", type: "password" },
      },
      async authorize(credentials) {
        if (!credentials?.email || !credentials?.password) return null;

        const db = getMetadataDb();
        const [user] = await db
          .select()
          .from(globalUsers)
          .where(eq(globalUsers.email, String(credentials.email).toLowerCase()))
          .limit(1);

        if (!user?.passwordHash) return null;

        const valid = await bcrypt.compare(
          String(credentials.password),
          user.passwordHash,
        );
        if (!valid) return null;

        const membership = await resolveActiveMembership(user.id);

        return {
          id: user.id,
          email: user.email,
          name: user.name,
          tenantId: membership?.tenantId,
          role: membership?.role,
          sessionVersion: user.sessionVersion ?? 1,
          isEmailVerified: !!user.emailVerified,
        };
      },
    }),
  ],
  pages: {
    signIn: "/login",
  },
  session: {
    strategy: "jwt",
    maxAge: 60 * 60 * 24,
    updateAge: 60 * 60 * 4,
  },
  callbacks: {
    async jwt({ token, user }) {
      if (user) {
        token.id = user.id!;
        token.email = user.email ?? undefined;
        token.name = user.name ?? undefined;
        token.tenantId = user.tenantId;
        token.role = user.role;
        token.sessionVersion = user.sessionVersion ?? 1;
        token.isEmailVerified = !!user.isEmailVerified;
      }

      if (token.id) {
        const db = getMetadataDb();
        const [user] = await db
          .select({
            email: globalUsers.email,
            name: globalUsers.name,
            sessionVersion: globalUsers.sessionVersion,
            emailVerified: globalUsers.emailVerified,
          })
          .from(globalUsers)
          .where(eq(globalUsers.id, token.id))
          .limit(1);

        if (!user) return token;

        token.email = user.email;
        if (user.name) token.name = user.name;
        token.isEmailVerified = !!user.emailVerified;

        const currentVersion = user.sessionVersion ?? 1;
        if ((token.sessionVersion ?? 1) !== currentVersion) {
          token.tenantId = undefined;
          token.role = undefined;
          token.tenantStatus = "none";
          return token;
        }

        const membership = await resolveActiveMembership(token.id, token.tenantId);
        if (!membership) {
          token.tenantId = undefined;
          token.role = undefined;
          token.tenantStatus = "none";
          return token;
        }

        token.tenantId = membership.tenantId;
        token.role = membership.role;
        token.tenantStatus = await resolveTenantStatus(token.id, membership.tenantId);
      } else {
        token.tenantStatus = "none";
      }

      return token;
    },
    async session({ session, token }) {
      if (session.user) {
        session.user.id = token.id;
        session.user.email = token.email ?? session.user.email;
        session.user.name = token.name ?? session.user.name;
        session.user.tenantId = token.tenantId;
        session.user.role = token.role;
        session.user.isEmailVerified = token.isEmailVerified ?? false;
        session.user.tenantStatus = token.tenantStatus ?? "none";
      }
      return session;
    },
  },
});

