import { createClient, type Client } from "@libsql/client";
import { drizzle, type LibSQLDatabase } from "drizzle-orm/libsql";
import { assertEnv, assertPreviewTursoIsolation } from "@/lib/env";
import * as metadataSchema from "./schema/metadata";

let _metadataDb: LibSQLDatabase<typeof metadataSchema> | null = null;

export function getMetadataDb() {
  if (!_metadataDb) {
    assertEnv();
    assertPreviewTursoIsolation();
    const client = createClient({
      url: process.env.TURSO_DATABASE_URL!,
      authToken: process.env.TURSO_AUTH_TOKEN!,
    });
    _metadataDb = drizzle(client, { schema: metadataSchema });
  }
  return _metadataDb;
}

export type MetadataDb = ReturnType<typeof getMetadataDb>;

export function createTenantClient(url: string, authToken: string): Client {
  return createClient({ url, authToken });
}

export function getTenantDb(url: string, authToken: string) {
  const client = createTenantClient(url, authToken);
  return drizzle(client);
}

