const REQUIRED = [
  "TURSO_DATABASE_URL",
  "TURSO_AUTH_TOKEN",
  "AUTH_SECRET",
] as const;

export function assertEnv(): void {
  const missing = REQUIRED.filter((key) => !process.env[key]);
  if (missing.length === 0) return;

  // Skip hard fail during `next build` static collection — env is validated at runtime on Vercel
  if (process.env.NEXT_PHASE === "phase-production-build") {
    console.warn(`[addplus] Missing env vars during build: ${missing.join(", ")}`);
    return;
  }

  if (process.env.NODE_ENV === "production" && process.env.VERCEL_ENV) {
    throw new Error(`Missing required environment variables: ${missing.join(", ")}`);
  }

  console.warn(`[addplus] Missing env vars (dev only): ${missing.join(", ")}`);
}

export function getEncryptionSecret(): string {
  const secret = process.env.ENCRYPTION_KEY ?? process.env.AUTH_SECRET;
  if (!secret) {
    if (process.env.NODE_ENV === "production") {
      throw new Error("ENCRYPTION_KEY or AUTH_SECRET must be set in production");
    }
    return "dev-only-encryption-key-not-for-production";
  }
  return secret;
}

export function getStreamPublicApiKey(): string {
  return process.env.NEXT_PUBLIC_STREAM_API_KEY ?? process.env.STREAM_API_KEY ?? "";
}

/** Preview deployments must not share production Turso API credentials. */
export function assertPreviewTursoIsolation(): void {
  if (process.env.VERCEL_ENV !== "preview") return;
  if (process.env.TURSO_API_TOKEN_PREVIEW) return;
  console.warn(
    "[solera] Preview deployment using production TURSO_API_TOKEN. Set TURSO_API_TOKEN_PREVIEW for isolation.",
  );
}

