import { NextResponse } from 'next/server'

function apiOrigin(): string {
  const raw =
    process.env.API_URL?.replace(/\/$/, '') ||
    process.env.NEXT_PUBLIC_API_URL?.replace(/\/v1\/?$/, '') ||
    'https://addplus-api.onrender.com'
  return raw
}

export async function POST(req: Request) {
  const body = await req.json().catch(() => ({}))
  const token = typeof body.token === 'string' ? body.token : ''
  const refresh = typeof body.refresh === 'string' ? body.refresh : ''

  if (!token) {
    return NextResponse.json({ error: 'Token required' }, { status: 400 })
  }

  const meRes = await fetch(`${apiOrigin()}/v1/auth/me`, {
    headers: { Authorization: `Bearer ${token}` },
    cache: 'no-store',
  })

  if (!meRes.ok) {
    return NextResponse.json({ error: 'Invalid session' }, { status: 401 })
  }

  const me = (await meRes.json()) as {
    user?: {
      role?: string
      email?: string | null
      email_verified?: boolean
    }
  }
  const user = me.user ?? {}

  const res = NextResponse.json({ ok: true, user })

  const cookieOpts = {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax' as const,
    path: '/',
  }

  res.cookies.set('access_token', token, { ...cookieOpts, maxAge: 60 * 15 })

  if (refresh) {
    res.cookies.set('refresh_token', refresh, { ...cookieOpts, maxAge: 60 * 60 * 24 * 7 })
  }

  if (user.role) {
    res.cookies.set('user_role', user.role, { ...cookieOpts, maxAge: 60 * 60 * 24 * 7 })
  }

  if (user.email) {
    res.cookies.set('user_email', String(user.email), { ...cookieOpts, maxAge: 60 * 60 * 24 * 7 })
  } else {
    res.cookies.set('user_email', '', { ...cookieOpts, maxAge: 0 })
  }

  const verified = user.email_verified === true
  res.cookies.set('email_verified', verified ? '1' : '0', { ...cookieOpts, maxAge: 60 * 60 * 24 * 7 })

  return res
}

export async function DELETE() {
  const res = NextResponse.json({ ok: true })
  const clear = { httpOnly: true, path: '/', maxAge: 0 }
  res.cookies.set('access_token', '', clear)
  res.cookies.set('refresh_token', '', clear)
  res.cookies.set('user_role', '', clear)
  res.cookies.set('user_email', '', clear)
  res.cookies.set('email_verified', '', clear)
  return res
}

