33	app.set('trust proxy', 1);
34	
35	// Security middleware with enhanced configuration
36	app.use(helmet({
37	  contentSecurityPolicy: {
38	    directives: {
39	      defaultSrc: ["'self'"],
40	      styleSrc: ["'self'", "'unsafe-inline'"],
41	      scriptSrc: ["'self'"],
42	      imgSrc: ["'self'", "data:", "https:"],
43	      connectSrc: ["'self'", process.env.CLIENT_URL || 'http://localhost:3000'],
44	    },
45	  },
46	  crossOriginEmbedderPolicy: false,
47	  hsts: {
48	    maxAge: 31536000,
49	    includeSubDomains: true,
50	    preload: true
51	  },
52	  referrerPolicy: { policy: "strict-origin-when-cross-origin" }
53	}));
54	const allowedOrigins = (process.env.CLIENT_URL || 'http://localhost:3000')
55	  .split(',')
56	  .map((o) => o.trim())
57	  .filter(Boolean);
58	
59	app.use(cors({
60	  origin(origin, callback) {
61	    if (!origin) return callback(null, true);
62	    if (allowedOrigins.includes(origin)) return callback(null, true);
63	    if (
64	      process.env.ALLOW_VERCEL_PREVIEWS === 'true' &&
65	      (origin.endsWith('.vercel.app') || origin === 'https://addplus.vercel.app')
66	    ) {
67	      return callback(null, true);
68	    }
69	    callback(null, false);
70	  },
71	  credentials: true,
72	  methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
73	  allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With'],
74	  exposedHeaders: ['Retry-After', 'X-RateLimit-Limit', 'X-RateLimit-Remaining']
75	}));
76	
77	// General rate limiting - 100 requests per 15 minutes
78	const limiter = rateLimit({
79	  windowMs: 15 * 60 * 1000,
80	  max: 100,
81	  standardHeaders: true,
82	  legacyHeaders: false,
83	  message: {
84	    error: 'Too many requests from this IP',
85	    retryAfter: '15 minutes'
86	  },
87	  handler: (req, res, next, options) => {
88	    res.status(429).json({
89	      error: options.message.error,
90	      retryAfter: Math.ceil(options.windowMs / 1000)
91	    });
92	  }
93	});
94	app.use(limiter);
95	
96	// Strict rate limit for authentication endpoints - 5 attempts per 15 minutes
97	const authLimiter = rateLimit({
98	  windowMs: 15 * 60 * 1000,
99	  max: 5,
100	  standardHeaders: true,
101	  legacyHeaders: false,
102	  skipSuccessfulRequests: true, // Don't count successful logins
103	  message: {
104	    error: 'Too many authentication attempts',
105	    retryAfter: '15 minutes'
106	  },
107	  handler: (req, res, next, options) => {
108	    res.status(429).json({
109	      error: options.message.error,
110	      retryAfter: Math.ceil(options.windowMs / 1000)
111	    });
112	  }
113	});
114	
115	// Rate limit for payment endpoints - 10 attempts per hour
116	const paymentLimiter = rateLimit({
117	  windowMs: 60 * 60 * 1000,
118	  max: 10,
119	  standardHeaders: true,
120	  legacyHeaders: false,
121	  message: {
122	    error: 'Too many payment attempts',
123	    retryAfter: '1 hour'
124	  }
125	});
126	
127	// Rate limit for file uploads - 5 per hour
128	const uploadLimiter = rateLimit({
129	  windowMs: 60 * 60 * 1000,
130	  max: 5,
131	  standardHeaders: true,
132	  legacyHeaders: false,
133	  message: {
134	    error: 'Too many upload attempts',
135	    retryAfter: '1 hour'
136	  }
137	});
138	
139	// Body parsing with stricter limits
140	app.use(express.json({ 
141	  limit: '1mb',
142	  strict: true // Only accept arrays and objects
143	}));
144	app.use(express.urlencoded({ 
145	  extended: true, 
146	  limit: '1mb',
147	  parameterLimit: 1000 // Limit number of query params
148	}));
149	
150	// Request logging
151	app.use(requestLogger);
152	
153	// Health check
154	app.get('/health', (req, res) => {
155	  res.json({ status: 'ok', timestamp: new Date().toISOString() });
156	});
157	
158	// API version prefix
159	const API_V1 = '/v1';
160	
161	// Routes with security middleware
162	app.use(`${API_V1}/auth`, authLimiter, authRoutes);
163	app.use(`${API_V1}/vendors`, validateInput, vendorRoutes);
164	app.use(`${API_V1}/products`, validateInput, productRoutes);
