import express, { Application } from 'express';
import cors from 'cors';
import helmet from 'helmet';
import rateLimit from 'express-rate-limit';
import dotenv from 'dotenv';

import { errorHandler } from './middleware/errorHandler';
import { requestLogger } from './middleware/requestLogger';
import { connectRedis } from './config/redis';
import { startAllCronJobs } from './jobs/crons';

import { validateInput } from './middleware/security';

// Import routes
import authRoutes from './routes/auth';
import vendorRoutes from './routes/vendors';
import productRoutes from './routes/products';
import orderRoutes from './routes/orders';
import paymentRoutes from './routes/payments';
import complianceRoutes from './routes/compliance';
import fundRoutes from './routes/fund';
import adminRoutes from './routes/admin';
import importationRoutes from './routes/importation';
import uploadRoutes from './routes/uploads';
import { ensureTursoSchema } from './lib/ensureTursoSchema';

dotenv.config();

const app: Application = express();
const PORT = process.env.PORT || 3001;

// Render/Vercel sit behind reverse proxies — required for rate limiting + callback IPs
app.set('trust proxy', 1);

// Security middleware with enhanced configuration
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'", process.env.CLIENT_URL || 'http://localhost:3000'],
    },
  },
  crossOriginEmbedderPolicy: false,
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  referrerPolicy: { policy: "strict-origin-when-cross-origin" }
}));
const allowedOrigins = (process.env.CLIENT_URL || 'http://localhost:3000')
  .split(',')
  .map((o) => o.trim())
  .filter(Boolean);

app.use(cors({
  origin(origin, callback) {
    if (!origin) return callback(null, true);
    if (allowedOrigins.includes(origin)) return callback(null, true);
    if (
      process.env.ALLOW_VERCEL_PREVIEWS === 'true' &&
      (origin.endsWith('.vercel.app') || origin === 'https://addplus.vercel.app')
    ) {
      return callback(null, true);
    }
    callback(null, false);
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With'],
  exposedHeaders: ['Retry-After', 'X-RateLimit-Limit', 'X-RateLimit-Remaining']
}));

// General rate limiting - 100 requests per 15 minutes
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: {
    error: 'Too many requests from this IP',
    retryAfter: '15 minutes'
  },
  handler: (req, res, next, options) => {
    res.status(429).json({
      error: options.message.error,
      retryAfter: Math.ceil(options.windowMs / 1000)
    });
  }
});
app.use(limiter);

// Strict rate limit for authentication endpoints - 5 attempts per 15 minutes
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  standardHeaders: true,
  legacyHeaders: false,
  skipSuccessfulRequests: true, // Don't count successful logins
  message: {
    error: 'Too many authentication attempts',
    retryAfter: '15 minutes'
  },
  handler: (req, res, next, options) => {
    res.status(429).json({
      error: options.message.error,
      retryAfter: Math.ceil(options.windowMs / 1000)
    });
  }
});

// Rate limit for payment endpoints - 10 attempts per hour
const paymentLimiter = rateLimit({
  windowMs: 60 * 60 * 1000,
  max: 10,
  standardHeaders: true,
  legacyHeaders: false,
  message: {
    error: 'Too many payment attempts',
    retryAfter: '1 hour'
  }
});

// Rate limit for file uploads - 5 per hour
const uploadLimiter = rateLimit({
  windowMs: 60 * 60 * 1000,
  max: 5,
  standardHeaders: true,
  legacyHeaders: false,
  message: {
    error: 'Too many upload attempts',
    retryAfter: '1 hour'
  }
});

// Body parsing with stricter limits
app.use(express.json({ 
  limit: '1mb',
  strict: true // Only accept arrays and objects
}));
app.use(express.urlencoded({ 
  extended: true, 
  limit: '1mb',
  parameterLimit: 1000 // Limit number of query params
}));

// Request logging
app.use(requestLogger);

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// API version prefix
const API_V1 = '/v1';

// Routes with security middleware
app.use(`${API_V1}/auth`, authLimiter, authRoutes);
app.use(`${API_V1}/vendors`, validateInput, vendorRoutes);
app.use(`${API_V1}/products`, validateInput, productRoutes);
app.use(`${API_V1}/orders`, validateInput, orderRoutes);
// M-Pesa webhooks: no rate limit or XSS heuristics — Safaricom POSTs fixed JSON payloads
app.use(`${API_V1}/payments`, paymentRoutes);
app.use(`${API_V1}/compliance`, validateInput, complianceRoutes);
app.use(`${API_V1}/fund`, validateInput, fundRoutes);
app.use(`${API_V1}/admin`, authLimiter, validateInput, adminRoutes);
app.use(`${API_V1}/importation`, validateInput, importationRoutes);
app.use(`${API_V1}/uploads`, uploadRoutes);

// Error handling
app.use(errorHandler);

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found' });
});

// Connect Redis (Upstash TLS), ensure Turso schema, then start server
connectRedis()
  .then(() => ensureTursoSchema())
  .then(() => {
    app.listen(PORT, () => {
      console.log(`ADDPlus+ API Server running on port ${PORT}`);
      console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
      startAllCronJobs();
    });
  });

export default app;

