import express from 'express';
import rateLimit from 'express-rate-limit';
import { MPesaService } from '../services/mpesaService';
import { AppError } from '../middleware/errorHandler';
import { authenticate, authorize, AuthRequest } from '../middleware/auth';
import { verifyPayHeroCallback } from '../lib/payheroWebhook';
import { handlePayHeroCallback } from '../services/payheroCallbackService';
import { getTransactionStatus } from '../services/payheroService';
import prisma from '../config/prisma';

const router = express.Router();
const mpesaService = new MPesaService();

const SAFARICOM_CALLBACK_IPS = new Set(
  (process.env.MPESA_CALLBACK_IPS ||
    '196.201.214.200,196.201.214.206,196.201.213.114,196.201.214.207,196.201.214.208,196.201.213.44,196.201.212.127,196.201.212.138,196.201.212.129,196.201.212.136,196.201.212.74,196.201.212.69'
  ).split(',').map((ip) => ip.trim())
);

function isSafaricomCallback(req: express.Request): boolean {
  const ip = (req.ip || req.socket.remoteAddress || '').replace(/^::ffff:/, '');
  return SAFARICOM_CALLBACK_IPS.has(ip);
}

const authenticatedPaymentLimiter = rateLimit({
  windowMs: 60 * 60 * 1000,
  max: 20,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many payment requests', retryAfter: '1 hour' },
});

// PayHero callback — marketplace order payments
router.post('/payhero/callback', async (req, res) => {
  try {
    const url = `${req.protocol}://${req.get('host')}${req.originalUrl}`;
    if (!verifyPayHeroCallback(req.headers as Record<string, string | string[] | undefined>, url)) {
      console.warn('[PayHero] Unauthorized callback');
      return res.status(401).json({ status: false, error: 'Unauthorized' });
    }

    await handlePayHeroCallback(req.body as Record<string, unknown>);
    return res.json({ status: true });
  } catch (error) {
    console.error('[PayHero] Callback error:', error);
    return res.status(500).json({ status: false });
  }
});

// Poll PayHero transaction status (web checkout)
router.get('/payhero/status/:reference', async (req, res, next) => {
  try {
    const status = await getTransactionStatus(req.params.reference);
    if (!status) {
      return res.status(404).json({ success: false, error: 'Transaction not found' });
    }
    res.json(status);
  } catch (error) {
    next(error);
  }
});

// STK Push callback - Security: Validate webhook signature and origin
router.post('/mpesa/stk-callback', async (req, res, next) => {
  try {
    if (!isSafaricomCallback(req)) {
      console.error('STK callback rejected — unknown IP:', req.ip);
      return res.status(403).json({ ResultCode: 1, ResultDesc: 'Forbidden' });
    }
    const signature = req.headers['x-mpesa-signature'] as string | undefined;
    const clientIp = req.ip || req.connection.remoteAddress || undefined;

    console.log('STK Callback received:', {
      timestamp: new Date().toISOString(),
      ip: clientIp,
      hasSignature: !!signature
    });

    // Security: Pass signature and IP for validation
    await mpesaService.handleSTKCallback(req.body, signature, clientIp);
    res.json({ ResultCode: 0, ResultDesc: 'Success' });
  } catch (error) {
    console.error('STK callback error:', error);
    // Always return success to M-Pesa to prevent retries
    res.json({ ResultCode: 0, ResultDesc: 'Received' });
  }
});

// B2C callback - Security: Enhanced validation
router.post('/mpesa/b2c-callback', async (req, res, next) => {
  try {
    if (!isSafaricomCallback(req)) {
      console.error('B2C callback rejected — unknown IP:', req.ip);
      return res.status(403).json({ ResultCode: 1, ResultDesc: 'Forbidden' });
    }
    const signature = req.headers['x-mpesa-signature'] as string | undefined;
    const clientIp = req.ip || req.connection.remoteAddress || undefined;

    console.log('B2C Callback received:', {
      timestamp: new Date().toISOString(),
      ip: clientIp,
      hasSignature: !!signature
    });

    await mpesaService.handleB2CCallback(req.body, signature, clientIp);
    res.json({ ResultCode: 0, ResultDesc: 'Success' });
  } catch (error) {
    console.error('B2C callback error:', error);
    res.json({ ResultCode: 0, ResultDesc: 'Received' });
  }
});

// B2C timeout callback
router.post('/mpesa/b2c-timeout', async (req, res, next) => {
  try {
    console.log('Timeout callback:', JSON.stringify(req.body, null, 2));
    res.json({ ResultCode: 0, ResultDesc: 'Received' });
  } catch (error) {
    next(error);
  }
});

// Get vendor escrow balance (vendor sees own, admin sees any)
router.get('/escrow/:vendorId', authenticatedPaymentLimiter, authenticate, async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);
    const { vendorId } = req.params;

    // Vendors can only see their own balance
    if (req.user.role !== 'admin') {
      const vp = await prisma.vendorProfile.findUnique({ where: { user_id: req.user.id }, select: { id: true } });
      if (!vp || vp.id !== vendorId) throw new AppError('Access denied', 403);
    }

    const [held, released] = await Promise.all([
      prisma.escrowLedger.aggregate({ where: { vendor_id: vendorId, status: 'held' }, _sum: { net_amount_cents: true } }),
      prisma.escrowLedger.aggregate({ where: { vendor_id: vendorId, status: 'released' }, _sum: { net_amount_cents: true } }),
    ]);

    res.json({
      success: true,
      vendorId,
      held_balance: Number(held._sum?.net_amount_cents || 0),
      released_total: Number(released._sum?.net_amount_cents || 0),
    });
  } catch (error) {
    next(error);
  }
});

// Initiate payout batch (admin only)
router.post('/payout/initiate', authenticatedPaymentLimiter, authenticate, authorize('admin'), async (req: AuthRequest, res, next) => {
  try {
    const { vendorIds } = req.body;
    res.json({ success: true, message: 'Payout initiated', vendorIds });
  } catch (error) {
    next(error);
  }
});

export default router;

