import { timingSafeEqual } from 'crypto';

function readBearerToken(header: string | undefined): string | null {
  if (!header) return null;
  return header.startsWith('Bearer ') ? header.slice(7) : header;
}

function secretsMatch(provided: string | null, secret: string): boolean {
  if (!provided || provided.length !== secret.length) return false;
  try {
    return timingSafeEqual(Buffer.from(provided), Buffer.from(secret));
  } catch {
    return false;
  }
}

/** Verify PayHero callback using shared secret header or query param. */
export function verifyPayHeroCallback(headers: Record<string, string | string[] | undefined>, url: string): boolean {
  const secret = process.env.PAYHERO_CALLBACK_SECRET;
  if (!secret) {
    return process.env.NODE_ENV !== 'production';
  }

  const headerToken =
    readBearerToken(headers['x-payhero-signature'] as string | undefined) ??
    readBearerToken(headers['x-callback-secret'] as string | undefined) ??
    readBearerToken(headers['authorization'] as string | undefined);

  if (secretsMatch(headerToken, secret)) return true;

  const queryToken = new URL(url, 'http://localhost').searchParams.get('secret');
  return secretsMatch(queryToken, secret);
}

/** Callback URL with secret query param for providers that cannot send custom headers. */
export function payHeroCallbackUrl(): string {
  const base =
    process.env.PAYHERO_CALLBACK_URL?.trim() ||
    `${process.env.API_BASE_URL?.trim() || 'http://localhost:3001'}/v1/payments/payhero/callback`;
  const secret = process.env.PAYHERO_CALLBACK_SECRET;
  if (!secret) return base;
  const url = new URL(base);
  url.searchParams.set('secret', secret);
  return url.toString();
}

