/** PayHero external reference for marketplace order STK payments. */
export function buildOrderPaymentReference(orderId: string): string {
  return `ORDER-${orderId}`;
}

export function parseOrderPaymentReference(ref: string): string | null {
  const match = ref.match(/^ORDER-(.+)$/);
  return match ? match[1] : null;
}

/** Legacy Daraja account reference format. */
export function parseDarajaOrderReference(ref: string): string | null {
  const match = ref.match(/^ADDPlus-(.+)$/);
  return match ? match[1] : null;
}

export function parseAnyOrderReference(ref: string): string | null {
  return parseOrderPaymentReference(ref) ?? parseDarajaOrderReference(ref);
}

