import { parseAnyOrderReference } from '../lib/paymentReferences';
import { parsePayHeroCallbackOutcome } from '../lib/payheroStatus';
import { confirmOrderPayment, failOrderPayment } from './paymentConfirmationService';

export async function handlePayHeroCallback(body: Record<string, unknown>): Promise<void> {
  const response = (body.response ?? body) as Record<string, unknown>;
  const externalRef = String(
    response.ExternalReference ?? response.external_reference ?? '',
  );
  const outcome = parsePayHeroCallbackOutcome(body);

  if (!externalRef) {
    console.warn('[PayHero] Callback missing external reference');
    return;
  }

  const orderId = parseAnyOrderReference(externalRef);
  if (!orderId) {
    console.warn('[PayHero] Unknown payment reference:', externalRef);
    return;
  }

  if (outcome === 'pending') {
    console.info('[PayHero] Non-terminal callback', { externalRef });
    return;
  }

  if (outcome === 'failed') {
    await failOrderPayment(
      orderId,
      String(response.CheckoutRequestID ?? response.checkout_request_id ?? ''),
    );
    return;
  }

  const amountRaw =
    response.Amount ??
    response.amount ??
    response.TransAmount ??
    response.trans_amount;
  const paidKes = amountRaw != null ? Math.round(Number(amountRaw)) : 0;

  await confirmOrderPayment({
    orderId,
    mpesaReceipt: String(
      response.MpesaReceiptNumber ??
        response.mpesa_receipt_number ??
        response.provider_reference ??
        response.reference ??
        '',
    ),
    mpesaPhone: String(response.PhoneNumber ?? response.phone_number ?? ''),
    checkoutRequestId: String(
      response.CheckoutRequestID ?? response.checkout_request_id ?? response.reference ?? '',
    ),
    paidKes,
  });
}

