import prisma from '../config/prisma';
import { notificationService } from './notificationService';
import { fromCents } from '../lib/money';

/** Confirm marketplace order payment and create escrow ledger entries. */
export async function confirmOrderPayment(params: {
  orderId: string;
  mpesaReceipt?: string | null;
  mpesaPhone?: string | null;
  checkoutRequestId?: string | null;
  paidKes: number;
}): Promise<void> {
  const { orderId, mpesaReceipt, mpesaPhone, checkoutRequestId, paidKes } = params;

  if (checkoutRequestId) {
    const existingOrder = await prisma.order.findFirst({
      where: { mpesa_request_id: checkoutRequestId, status: 'confirmed' },
    });
    if (existingOrder) {
      console.log(`Duplicate payment callback ignored for ${checkoutRequestId}`);
      return;
    }
  }

  const order = await prisma.order.findUnique({
    where: { id: orderId },
    include: { order_items: true },
  });

  if (!order) {
    console.error('Payment callback for unknown order:', orderId);
    return;
  }

  if (order.status === 'confirmed') {
    return;
  }

  if (checkoutRequestId && order.mpesa_request_id && order.mpesa_request_id !== checkoutRequestId) {
    console.error('CheckoutRequestID mismatch for order', orderId);
    return;
  }

  const expectedKes = Math.round(order.total_amount_cents / 100);
  const resolvedPaidKes = paidKes > 0 ? paidKes : expectedKes;
  if (resolvedPaidKes !== expectedKes) {
    console.error(`Amount mismatch order ${orderId}: paid ${resolvedPaidKes} expected ${expectedKes}`);
    return;
  }

  await prisma.$transaction(async (tx) => {
    const updatedOrder = await tx.order.update({
      where: { id: orderId },
      data: {
        status: 'confirmed',
        mpesa_ref: mpesaReceipt ?? order.mpesa_ref,
        mpesa_phone: mpesaPhone?.toString() ?? order.mpesa_phone,
        mpesa_request_id: checkoutRequestId || order.mpesa_request_id,
      },
    });

    notificationService.notifyPaymentReceived(updatedOrder.customer_id, orderId, resolvedPaidKes).catch(() => {});

    for (const item of order.order_items) {
      const grossCents = item.subtotal_cents;
      const levyFundCents = Math.round(grossCents * 0.05);
      const levyProfitCents = Math.round(grossCents * 0.05);
      const netCents = grossCents - levyFundCents - levyProfitCents;

      await tx.escrowLedger.create({
        data: {
          order_item_id: item.id,
          vendor_id: item.vendor_id,
          gross_amount_cents: grossCents,
          levy_5pct_fund_cents: levyFundCents,
          levy_5pct_profit_share_cents: levyProfitCents,
          net_amount_cents: netCents,
          status: 'held',
        },
      });

      await tx.collectiveFund.create({
        data: {
          source_order_item_id: item.id,
          vendor_id: item.vendor_id,
          amount_cents: levyFundCents,
          type: 'advancement_contribution',
          notes: `Order ${orderId} advancement fund levy`,
        },
      });

      await tx.collectiveFund.create({
        data: {
          source_order_item_id: item.id,
          vendor_id: item.vendor_id,
          amount_cents: levyProfitCents,
          type: 'profit_share_contribution',
          notes: `Order ${orderId} profit share pool levy`,
        },
      });
    }
  });
}

/** Mark order payment as failed/cancelled. */
export async function failOrderPayment(orderId: string, checkoutRequestId?: string | null): Promise<void> {
  await prisma.order.update({
    where: { id: orderId },
    data: {
      status: 'cancelled',
      mpesa_ref: checkoutRequestId ?? undefined,
    },
  });
}

