import { AppError } from '../middleware/errorHandler';
import { payHeroCallbackUrl } from '../lib/payheroWebhook';
import { buildOrderPaymentReference } from '../lib/paymentReferences';

const PAYHERO_API = 'https://backend.payhero.co.ke/api/v2';

export type StkPushResult = {
  success: boolean;
  checkoutRequestId?: string;
  reference?: string;
  message: string;
  simulated?: boolean;
};

function payHeroConfigured(): boolean {
  return !!(process.env.PAYHERO_AUTH_TOKEN && process.env.PAYHERO_CHANNEL_ID);
}

function authHeader(): string {
  const token = process.env.PAYHERO_AUTH_TOKEN!;
  return token.startsWith('Basic ') ? token : `Basic ${token}`;
}

/** Normalize Kenyan phone to 07XXXXXXXX for Pay Hero */
export function normalizeKenyanPhone(phone: string): string {
  const digits = phone.replace(/\D/g, '');
  if (digits.startsWith('254')) return `0${digits.slice(3)}`;
  if (digits.startsWith('0')) return digits;
  if (digits.length === 9) return `0${digits}`;
  return digits;
}

export function isPayHeroEnabled(): boolean {
  return payHeroConfigured();
}

/**
 * Initiate M-Pesa STK via Pay Hero Kenya.
 * @see https://docs.payhero.co.ke/
 */
export async function initiateOrderStkPush(params: {
  phone: string;
  amountKes: number;
  orderId: string;
  customerName?: string;
}): Promise<StkPushResult> {
  const phone = normalizeKenyanPhone(params.phone);
  const amountKes = Math.max(1, Math.round(params.amountKes));
  const accountReference = buildOrderPaymentReference(params.orderId);

  if (!payHeroConfigured()) {
    if (process.env.NODE_ENV === 'production') {
      throw new AppError('PayHero is not configured', 500);
    }
    const id = `SIM-${Date.now()}`;
    console.info('[PayHero] STK simulated', { phone, amountKes, id });
    return {
      success: true,
      checkoutRequestId: id,
      reference: id,
      message: 'STK push simulated (set PAYHERO_AUTH_TOKEN + PAYHERO_CHANNEL_ID)',
      simulated: true,
    };
  }

  const channelId = Number(process.env.PAYHERO_CHANNEL_ID);
  const res = await fetch(`${PAYHERO_API}/payments`, {
    method: 'POST',
    headers: {
      Authorization: authHeader(),
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      amount: amountKes,
      phone_number: phone,
      channel_id: channelId,
      provider: 'm-pesa',
      external_reference: accountReference.slice(0, 64),
      customer_name: params.customerName ?? 'ADDPlus+ Customer',
      callback_url: payHeroCallbackUrl(),
    }),
  });

  const data = (await res.json()) as {
    success?: boolean;
    status?: string;
    reference?: string;
    CheckoutRequestID?: string;
    error_message?: string;
  };

  if (!res.ok || !data.success) {
    console.error('[PayHero] STK failed', { data, status: res.status });
    throw new AppError(data.error_message ?? 'Pay Hero STK push failed', 502);
  }

  console.info('[PayHero] STK sent', {
    reference: data.reference,
    checkoutRequestId: data.CheckoutRequestID,
  });

  return {
    success: true,
    checkoutRequestId: data.CheckoutRequestID ?? data.reference,
    reference: data.reference,
    message: data.status ?? 'STK push queued',
  };
}

export async function getTransactionStatus(reference: string) {
  if (!payHeroConfigured()) return null;

  const res = await fetch(
    `${PAYHERO_API}/transaction-status?reference=${encodeURIComponent(reference)}`,
    { headers: { Authorization: authHeader() } },
  );

  if (!res.ok) return null;
  return res.json() as Promise<{
    success: boolean;
    status: string;
    reference: string;
    provider_reference?: string;
  }>;
}

