import { AppError } from '../middleware/errorHandler';
import { MPesaService } from './mpesaService';
import { initiateOrderStkPush, isPayHeroEnabled } from './payheroService';
import prisma from '../config/prisma';
import { notificationService } from './notificationService';
import { stringifyJsonObject } from '../lib/jsonFields';
import { fromCents } from '../lib/money';
import { serializeOrder, serializeOrderItem } from '../lib/serialize';
import { logActivity } from './activityLogService';
import { inventoryService } from './inventoryService';

const mpesaService = new MPesaService();

interface CartItem {
  product_id: string;
  quantity: number;
  vendor_notes?: string;
}

export class OrderService {
  async createOrder(customerId: string, cartItems: CartItem[], deliveryAddress: any, phone: string) {
    if (!cartItems || cartItems.length === 0) {
      throw new AppError('Cart is empty', 400);
    }

    // Get product details and calculate totals
    const itemsWithDetails = await Promise.all(
      cartItems.map(async (item) => {
        const product = await prisma.product.findFirst({
          where: {
            id: item.product_id,
            status: 'APPROVED',
            deleted_at: null,
            stock_qty: { gte: item.quantity },
            vendor: {
              kyc_status: 'approved',
              is_suspended: false
            }
          },
          include: {
            vendor: {
              select: { id: true, business_name: true, mpesa_number: true }
            }
          }
        });

        if (!product) {
          throw new AppError(`Product ${item.product_id} not available or out of stock`, 400);
        }

        const unitPriceCents = product.price_cents;
        return {
          ...item,
          product,
          unit_price_cents: unitPriceCents,
          subtotal_cents: unitPriceCents * item.quantity
        };
      })
    );

    const totalAmountCents = itemsWithDetails.reduce((sum, item) => sum + item.subtotal_cents, 0);

    const order = await prisma.order.create({
      data: {
        customer_id: customerId,
        total_amount_cents: totalAmountCents,
        mpesa_phone: phone,
        delivery_address: stringifyJsonObject(deliveryAddress),
        status: 'pending_payment',
        order_items: {
          create: itemsWithDetails.map(item => ({
            product_id: item.product_id,
            vendor_id: item.product.vendor_id,
            qty: item.quantity,
            unit_price_cents: item.unit_price_cents,
            subtotal_cents: item.subtotal_cents,
            customer_notes: item.vendor_notes
          }))
        }
      },
      include: {
        order_items: {
          include: {
            product: {
              select: { title: true, images: true }
            }
          }
        }
      }
    });

    // Notify customer order was placed
    notificationService.notifyOrderPlaced(customerId, order.id, fromCents(order.total_amount_cents)).catch(() => {});

    // Notify each vendor about their item
    for (const item of order.order_items) {
      const vp = await prisma.vendorProfile.findUnique({ where: { id: item.vendor_id }, select: { user_id: true } });
      if (vp) {
        notificationService.notifyVendorNewOrder(vp.user_id, item.id, item.product.title).catch(() => {});
      }
    }

    return order;
  }

  async initiatePayment(orderId: string, phone: string, customerId?: string, userRole?: string) {
    const order = await prisma.order.findUnique({
      where: { id: orderId },
      include: { order_items: true }
    });

    if (!order) {
      throw new AppError('Order not found', 404);
    }

    if (userRole !== 'admin' && customerId && order.customer_id !== customerId) {
      throw new AppError('You can only pay for your own orders', 403);
    }

    if (order.status !== 'pending_payment') {
      throw new AppError('Order is not pending payment', 400);
    }

    // Initiate STK Push — PayHero primary, Daraja fallback
    let checkoutRequestID: string | undefined;
    let message: string;

    if (isPayHeroEnabled()) {
      const stkResponse = await initiateOrderStkPush({
        phone,
        amountKes: fromCents(order.total_amount_cents),
        orderId,
        customerName: 'ADDPlus+ Customer',
      });
      checkoutRequestID = stkResponse.checkoutRequestId ?? stkResponse.reference;
      message = stkResponse.message;
    } else {
      const stkResponse = await mpesaService.initiateSTKPush(
        phone,
        fromCents(order.total_amount_cents),
        orderId,
        `ADDPlus+ Order #${orderId.substring(0, 8)}`,
      );
      checkoutRequestID = stkResponse.checkoutRequestID;
      message = stkResponse.customerMessage || 'Please check your phone and enter M-Pesa PIN to complete payment';
    }

    await prisma.order.update({
      where: { id: orderId },
      data: { mpesa_request_id: checkoutRequestID },
    });

    return {
      orderId,
      checkoutRequestID,
      gateway: isPayHeroEnabled() ? 'payhero' : 'daraja',
      message,
    };
  }

  async getOrderById(orderId: string, userId: string, userRole: string) {
    const where: any = { id: orderId };

    if (userRole === 'customer') {
      where.customer_id = userId;
    } else if (userRole === 'vendor') {
      const vp = await prisma.vendorProfile.findUnique({ where: { user_id: userId }, select: { id: true } });
      if (!vp) throw new AppError('Vendor profile not found', 403);
      where.order_items = { some: { vendor_id: vp.id } };
    }

    const order = await prisma.order.findFirst({
      where,
      include: {
        order_items: {
          include: {
            product: {
              select: {
                id: true,
                title: true,
                images: true
              }
            },
            vendor: {
              select: {
                id: true,
                business_name: true,
                mpesa_number: true
              }
            },
            escrow_entry: true
          }
        },
        customer: {
          select: {
            id: true,
            full_name: true,
            phone: true
          }
        }
      }
    });

    if (!order) {
      throw new AppError('Order not found', 404);
    }

    return order;
  }

  async getCustomerOrders(customerId: string, filters: any) {
    const orders = await prisma.order.findMany({
      where: { customer_id: customerId },
      orderBy: { created_at: 'desc' },
      skip: (filters.page - 1) * filters.limit,
      take: filters.limit,
      include: {
        order_items: {
          include: {
            product: {
              select: { id: true, title: true, images: true }
            },
            vendor: {
              select: { id: true, business_name: true }
            }
          }
        }
      }
    });

    const total = await prisma.order.count({ where: { customer_id: customerId } });

    return { orders, total, page: filters.page, limit: filters.limit };
  }

  async getVendorOrders(vendorId: string, filters: any) {
    const orderItems = await prisma.orderItem.findMany({
      where: { vendor_id: vendorId },
      orderBy: { created_at: 'desc' },
      skip: (filters.page - 1) * filters.limit,
      take: filters.limit,
      include: {
        order: {
          include: {
            customer: {
              select: { id: true, full_name: true, phone: true }
            }
          }
        },
        product: {
          select: { id: true, title: true, images: true }
        },
        escrow_entry: true
      }
    });

    const total = await prisma.orderItem.count({ where: { vendor_id: vendorId } });

    return { order_items: orderItems, total, page: filters.page, limit: filters.limit };
  }

  async updateOrderStatus(orderId: string, status: string, vendorId?: string) {
    const order = await prisma.order.findUnique({
      where: { id: orderId },
      include: { order_items: true }
    });

    if (!order) {
      throw new AppError('Order not found', 404);
    }

    // If vendor is provided, verify they have items in this order
    if (vendorId) {
      const hasItems = order.order_items.some(item => item.vendor_id === vendorId);
      if (!hasItems) {
        throw new AppError('Unauthorized to update this order', 403);
      }
    }

    const updated = await prisma.order.update({
      where: { id: orderId },
      data: { status: status as any },
      include: {
        order_items: {
          include: {
            product: { select: { title: true } }
          }
        }
      }
    });

    return updated;
  }

  async updateOrderItemStatus(orderItemId: string, vendorId: string, status: string, actorId?: string) {
    const orderItem = await prisma.orderItem.findFirst({
      where: { id: orderItemId, vendor_id: vendorId }
    });

    if (!orderItem) {
      throw new AppError('Order item not found or unauthorized', 404);
    }

    const autoReleaseAt = status === 'dispatched'
      ? new Date(Date.now() + 48 * 60 * 60 * 1000)
      : undefined;

    const updated = await prisma.orderItem.update({
      where: { id: orderItemId },
      data: {
        item_status: status as any,
        auto_release_at: autoReleaseAt,
        expected_delivery_at: status === 'dispatched' ? autoReleaseAt : orderItem.expected_delivery_at,
      }
    });

    if (actorId) {
      await logActivity({
        actorId,
        actorRole: 'vendor',
        action: 'order.status.updated',
        entityType: 'order_item',
        entityId: orderItemId,
        metadata: { status },
      });
    }

    return serializeOrderItem(updated);
  }

  async confirmDelivery(orderItemId: string, customerId: string) {
    const orderItem = await prisma.orderItem.findFirst({
      where: { 
        id: orderItemId,
        order: { customer_id: customerId }
      },
      include: {
        escrow_entry: true
      }
    });

    if (!orderItem) {
      throw new AppError('Order item not found', 404);
    }

    if (orderItem.vendor_escrow_status !== 'held') {
      throw new AppError('Order item is not in held status', 400);
    }

    // Update order item
    await prisma.orderItem.update({
      where: { id: orderItemId },
      data: { 
        vendor_escrow_status: 'released',
        delivery_confirmed_at: new Date()
      }
    });

    // Update escrow ledger and release to vendor
    if (orderItem.escrow_entry) {
      // Check for outstanding fines
      const vendor = await prisma.vendorProfile.findUnique({
        where: { id: orderItem.vendor_id },
        select: { fine_balance_cents: true, mpesa_number: true }
      });

      let netPayout = orderItem.escrow_entry.net_amount_cents;
      let fineDeduction = 0;

      if (vendor && vendor.fine_balance_cents > 0) {
        fineDeduction = Math.min(vendor.fine_balance_cents, netPayout);
        netPayout = netPayout - fineDeduction;

        await prisma.vendorProfile.update({
          where: { id: orderItem.vendor_id },
          data: { fine_balance_cents: { decrement: fineDeduction } }
        });

        await prisma.escrowLedger.update({
          where: { id: orderItem.escrow_entry.id },
          data: { 
            fine_deduction_cents: fineDeduction,
            status: 'released',
            released_at: new Date()
          }
        });

        await prisma.fineLedger.create({
          data: {
            vendor_id: orderItem.vendor_id,
            amount_cents: fineDeduction,
            reason: 'Auto-deducted from order payout',
            rule_violated: 'outstanding_balance',
            is_paid: true,
            paid_at: new Date(),
            deducted_from_escrow: true
          }
        });
      } else {
        await prisma.escrowLedger.update({
          where: { id: orderItem.escrow_entry.id },
          data: { 
            status: 'released',
            released_at: new Date()
          }
        });
      }

      // Trigger B2C payout if above minimum threshold
      if (netPayout >= 50000) {
        try {
          const b2cResponse = await mpesaService.initiateB2CPayout(
            vendor!.mpesa_number,
            fromCents(netPayout),
            `Payout for order ${orderItemId.substring(0, 8)}`,
            'VendorPayout'
          );

          // Update escrow with payout reference
          await prisma.escrowLedger.update({
            where: { id: orderItem.escrow_entry.id },
            data: { payout_mpesa_ref: b2cResponse.conversationID }
          });
        } catch (error) {
          console.error('B2C payout failed:', error);
          // Escrow is marked released but payout failed - admin needs to retry
        }
      }
    }

    // Notify vendor of payout
    const vp = await prisma.vendorProfile.findUnique({ where: { id: orderItem.vendor_id }, select: { user_id: true } });
    if (vp && orderItem.escrow_entry) {
      notificationService.notifyVendorEscrowReleased(vp.user_id, fromCents(orderItem.escrow_entry.net_amount_cents)).catch(() => {});
    }

    return { message: 'Delivery confirmed and payout initiated' };
  }

  async openDispute(orderItemId: string, customerId: string, reason: string, details?: string) {
    const orderItem = await prisma.orderItem.findFirst({
      where: { 
        id: orderItemId,
        order: { customer_id: customerId }
      },
      include: {
        order: true,
        escrow_entry: true
      }
    });

    if (!orderItem) {
      throw new AppError('Order item not found', 404);
    }

    if ((orderItem as any).vendor_escrow_status !== 'held') {
      throw new AppError('Cannot dispute - funds already released', 400);
    }

    // Check if within 48 hours of expected delivery
    const expectedDelivery = orderItem.expected_delivery_at || 
      new Date(orderItem.created_at.getTime() + 3 * 24 * 60 * 60 * 1000);

    const hoursSinceExpected = (Date.now() - expectedDelivery.getTime()) / (1000 * 60 * 60);

    if (hoursSinceExpected > 48) {
      throw new AppError('Dispute window has closed (48 hours after expected delivery)', 400);
    }

    // Create dispute
    const dispute = await prisma.dispute.create({
      data: {
        order_item_id: orderItemId,
        opened_by: customerId,
        reason,
        details,
        status: 'open'
      }
    });

    // Update order item status
    await prisma.orderItem.update({
      where: { id: orderItemId },
      data: { vendor_escrow_status: 'held' } // Freeze the funds
    });

    // Notify vendor of dispute
    const vp = await prisma.vendorProfile.findUnique({ where: { id: orderItem.vendor_id }, select: { user_id: true } });
    if (vp) {
      notificationService.notifyDisputeOpened(vp.user_id, orderItemId).catch(() => {});
    }

    return dispute;
  }

  async resolveDispute(disputeId: string, adminId: string, resolution: string, notes?: string, refundAmount?: number) {
    const dispute = await prisma.dispute.findUnique({
      where: { id: disputeId },
      include: {
        order_item: {
          include: { escrow_entry: true }
        }
      }
    });

    if (!dispute) {
      throw new AppError('Dispute not found', 404);
    }

    if (dispute.status !== 'open') {
      throw new AppError('Dispute already resolved', 400);
    }

    const updateData: any = {
      status: resolution,
      resolution_notes: notes,
      resolved_by: adminId,
      resolved_at: new Date()
    };

    if (refundAmount !== undefined) {
      updateData.refund_amount = refundAmount;
    }

    const resolved = await prisma.dispute.update({
      where: { id: disputeId },
      data: updateData
    });

    // Update order item and escrow based on resolution
    if (resolution === 'resolved_refund') {
      await prisma.orderItem.update({
        where: { id: dispute.order_item_id },
        data: { vendor_escrow_status: 'refunded' }
      });

      if (dispute.order_item.escrow_entry) {
        await prisma.escrowLedger.update({
          where: { id: dispute.order_item.escrow_entry.id },
          data: { status: 'refunded', released_at: new Date() }
        });
      }
    } else if (resolution === 'resolved_release') {
      await prisma.orderItem.update({
        where: { id: dispute.order_item_id },
        data: { vendor_escrow_status: 'released', delivery_confirmed_at: new Date() }
      });

      // Trigger vendor payout
      if (dispute.order_item.escrow_entry) {
        await prisma.escrowLedger.update({
          where: { id: dispute.order_item.escrow_entry.id },
          data: { status: 'released', released_at: new Date() }
        });
      }
    }

    return resolved;
  }

  async getDisputes(filters: any) {
    const where: any = {};

    if (filters.status) {
      where.status = filters.status;
    }

    const disputes = await prisma.dispute.findMany({
      where,
      orderBy: { created_at: 'desc' },
      skip: (filters.page - 1) * filters.limit,
      take: filters.limit,
      include: {
        order_item: {
          include: {
            product: { select: { title: true } },
            vendor: { select: { business_name: true } }
          }
        }
      }
    });

    const total = await prisma.dispute.count({ where });

    return { disputes, total, page: filters.page, limit: filters.limit };
  }
}

