import express from 'express';
import { OrderService } from '../services/orderService';
import { authenticate, authorize, AuthRequest } from '../middleware/auth';
import { AppError } from '../middleware/errorHandler';
import prisma from '../config/prisma';

const router = express.Router();
const orderService = new OrderService();

// Create order
router.post('/', authenticate, authorize('customer', 'admin'), async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);

    const { items, delivery_address, phone } = req.body;
    const order = await orderService.createOrder(req.user.id, items, delivery_address, phone);
    res.status(201).json({ success: true, order });
  } catch (error) {
    next(error);
  }
});

// Initiate payment
router.post('/:id/pay', authenticate, authorize('customer', 'admin'), async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);

    const { id } = req.params;
    const { phone } = req.body;
    const result = await orderService.initiatePayment(id, phone, req.user.id, req.user.role);
    res.json({ success: true, ...result });
  } catch (error) {
    next(error);
  }
});

// Get customer orders
router.get('/customer/:customerId', authenticate, async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);

    const { customerId } = req.params;
    if (req.user.id !== customerId && req.user.role !== 'admin') {
      throw new AppError('Unauthorized', 403);
    }

    const filters = {
      page: parseInt(req.query.page as string) || 1,
      limit: parseInt(req.query.limit as string) || 20
    };

    const result = await orderService.getCustomerOrders(customerId, filters);
    res.json({ success: true, ...result });
  } catch (error) {
    next(error);
  }
});

// Get vendor orders — resolves vendor profile from authenticated user
router.get('/vendor/me', authenticate, authorize('vendor', 'admin'), async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);

    let vendorId: string;
    if (req.user.role === 'admin' && req.query.vendor_id) {
      vendorId = req.query.vendor_id as string;
    } else {
      const vp = await prisma.vendorProfile.findUnique({
        where: { user_id: req.user.id },
        select: { id: true }
      });
      if (!vp) throw new AppError('Vendor profile not found', 403);
      vendorId = vp.id;
    }

    const filters = {
      page: parseInt(req.query.page as string) || 1,
      limit: parseInt(req.query.limit as string) || 20
    };
    const result = await orderService.getVendorOrders(vendorId, filters);
    res.json({ success: true, ...result });
  } catch (error) {
    next(error);
  }
});

// Get vendor orders by ID (admin only)
router.get('/vendor/:vendorId', authenticate, authorize('admin'), async (req: AuthRequest, res, next) => {
  try {
    const { vendorId } = req.params;
    const filters = {
      page: parseInt(req.query.page as string) || 1,
      limit: parseInt(req.query.limit as string) || 20
    };
    const result = await orderService.getVendorOrders(vendorId, filters);
    res.json({ success: true, ...result });
  } catch (error) {
    next(error);
  }
});

// Get single order
router.get('/:id', authenticate, async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);

    const { id } = req.params;
    const order = await orderService.getOrderById(id, req.user.id, req.user.role);
    res.json({ success: true, order });
  } catch (error) {
    next(error);
  }
});

// Confirm delivery
router.put('/:id/confirm-delivery', authenticate, authorize('customer', 'admin'), async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);

    const { id } = req.params;
    const result = await orderService.confirmDelivery(id, req.user.id);
    res.json({ success: true, ...result });
  } catch (error) {
    next(error);
  }
});

// Vendor updates order item dispatch status
router.put('/:itemId/status', authenticate, authorize('vendor', 'admin'), async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);
    const { itemId } = req.params;
    const { status } = req.body;
    const vp = await prisma.vendorProfile.findUnique({ where: { user_id: req.user.id }, select: { id: true } });
    if (!vp) throw new AppError('Vendor profile not found', 403);
    const updated = await orderService.updateOrderItemStatus(itemId, vp.id, status, req.user.id);
    res.json({ success: true, order_item: updated });
  } catch (error) {
    next(error);
  }
});

// Open dispute
router.post('/:id/dispute', authenticate, authorize('customer', 'admin'), async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);

    const { id } = req.params;
    const { reason, details } = req.body;
    const dispute = await orderService.openDispute(id, req.user.id, reason, details);
    res.status(201).json({ success: true, dispute });
  } catch (error) {
    next(error);
  }
});

export default router;

