import express from 'express';
import { z } from 'zod';
import { AuthService } from '../services/authService';
import { authenticate, AuthRequest } from '../middleware/auth';
import { AppError } from '../middleware/errorHandler';
import { notificationService } from '../services/notificationService';
import { validateInput, sanitizePhoneNumber, validatePhoneNumber } from '../middleware/security';
import prisma from '../config/prisma';

const router = express.Router();
const authService = new AuthService();

// Validation schemas
const phoneSchema = z.object({
  phone: z.string().min(10).max(15)
});

const otpVerifySchema = z.object({
  phone: z.string().min(10).max(15),
  code: z.string().length(6),
  full_name: z.string().min(2).max(100).optional(),
});

const vendorRegisterSchema = z.object({
  business_name: z.string().min(2).max(100),
  description: z.string().max(500).optional(),
  category_ids: z.array(z.string()).max(3),
  location_lat: z.number().optional(),
  location_lng: z.number().optional(),
  location_address: z.string().optional(),
  mpesa_number: z.string().optional(),
  business_photos: z.array(z.string()).optional()
});

const loginSchema = z.object({
  identifier: z.string().min(3),
  password: z.string().min(1),
});

const registerSchema = z.object({
  phone: z.string().min(10).max(15),
  email: z.string().email(),
  password: z.string().min(8),
  full_name: z.string().min(2).max(100).optional(),
});

const verifyEmailSchema = z.object({
  token: z.string().min(10).optional(),
  code: z.string().length(6).optional(),
  email: z.string().email().optional(),
}).refine((data) => data.token || (data.code && data.email), {
  message: 'Provide token or code with email',
});

const passwordSetupSchema = z.object({
  phone: z.string().min(10).max(15),
  password: z.string().min(8),
});

const forgotPasswordSchema = z.object({
  email: z.string().email(),
});

const resetPasswordSchema = z.object({
  token: z.string().min(10),
  password: z.string().min(8),
});

// Phone or email + password login (primary)
router.post('/login', async (req, res, next) => {
  try {
    const { identifier, password } = loginSchema.parse(req.body);
    const result = await authService.loginWithPassword(identifier, password);
    res.json({ success: true, ...result });
  } catch (error) {
    next(error);
  }
});

// First-time password for seeded admin/vendor without a password
router.post('/password/setup', async (req, res, next) => {
  try {
    const { phone, password } = passwordSetupSchema.parse(req.body);
    const result = await authService.setupPassword(phone, password);
    res.json({ success: true, ...result });
  } catch (error) {
    next(error);
  }
});

// Customer account registration (vendors use this before store setup)
router.post('/register', async (req, res, next) => {
  try {
    const { phone, password, full_name, email } = registerSchema.parse(req.body);
    const result = await authService.registerAccount(phone, password, full_name, email);
    res.json({ success: true, ...result });
  } catch (error) {
    next(error);
  }
});

router.post('/verify-email', async (req, res, next) => {
  try {
    const payload = verifyEmailSchema.parse(req.body);
    const result = await authService.verifyEmail(payload);
    res.json({ success: true, ...result });
  } catch (error) {
    next(error);
  }
});

router.post('/verify-email/resend', authenticate, async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);
    const result = await authService.resendVerificationEmail(req.user.id);
    res.json({ success: true, ...result });
  } catch (error) {
    next(error);
  }
});

router.post('/forgot-password', async (req, res, next) => {
  try {
    const { email } = forgotPasswordSchema.parse(req.body);
    const result = await authService.requestPasswordReset(email);
    res.json({ success: true, ...result });
  } catch (error) {
    next(error);
  }
});

router.post('/reset-password', async (req, res, next) => {
  try {
    const { token, password } = resetPasswordSchema.parse(req.body);
    const result = await authService.resetPassword(token, password);
    res.json({ success: true, ...result });
  } catch (error) {
    next(error);
  }
});

// Request OTP
router.post('/otp/request', async (req, res, next) => {
  try {
    const { phone } = phoneSchema.parse(req.body);
    const result = await authService.requestOTP(phone);
    res.json({ success: true, ...result });
  } catch (error) {
    next(error);
  }
});

// Verify OTP
router.post('/otp/verify', async (req, res, next) => {
  try {
    const { phone, code, full_name } = otpVerifySchema.parse(req.body);
    const result = await authService.verifyOTP(phone, code, full_name);
    res.json({ success: true, ...result });
  } catch (error) {
    next(error);
  }
});

// Register as vendor
router.post('/register/vendor', authenticate, async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);

    const data = vendorRegisterSchema.parse(req.body);
    const result = await authService.registerVendor(req.user.id, data);
    res.json({ success: true, ...result });
  } catch (error) {
    next(error);
  }
});

// Refresh token
router.post('/token/refresh', async (req, res, next) => {
  try {
    const { refreshToken } = req.body;
    if (!refreshToken) throw new AppError('Refresh token required', 400);

    const result = await authService.refreshToken(refreshToken);
    res.json({ success: true, ...result });
  } catch (error) {
    next(error);
  }
});

// Logout - Security: Revoke both access and refresh tokens
router.post('/logout', authenticate, async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);

    const authHeader = req.headers.authorization;
    const accessToken = authHeader ? authHeader.substring(7) : undefined;
    const { refreshToken } = req.body;
    const result = await authService.logout(req.user.id, refreshToken, accessToken);
    res.json({ success: true, ...result });
  } catch (error) {
    next(error);
  }
});

// Get current user (full profile for web session cookies)
router.get('/me', authenticate, async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);

    const user = await prisma.user.findUnique({
      where: { id: req.user.id },
      select: {
        id: true,
        phone: true,
        email: true,
        role: true,
        full_name: true,
        email_verified_at: true,
        deleted_at: true,
      },
    });
    if (!user || user.deleted_at) throw new AppError('Not authenticated', 401);

    res.json({
      success: true,
      user: {
        id: user.id,
        phone: user.phone,
        email: user.email,
        role: user.role,
        full_name: user.full_name,
        email_verified: !!user.email_verified_at,
      },
    });
  } catch (error) {
    next(error);
  }
});

// Register push token
router.post('/push-token', authenticate, async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);
    const { token } = req.body;
    if (!token) throw new AppError('Push token required', 400);
    await notificationService.registerToken(req.user.id, token);
    res.json({ success: true, message: 'Push token registered' });
  } catch (error) {
    next(error);
  }
});

export default router;

