21	function normalizePhone(phone: string): string {
22	  let clean = phone.replace(/\s/g, '').replace(/^\+/, '');
23	  if (clean.startsWith('0')) clean = '254' + clean.slice(1);
24	  if (!clean.startsWith('254')) clean = '254' + clean;
25	  return clean;
26	}
27	
28	function normalizeEmail(email: string): string {
29	  return email.trim().toLowerCase();
30	}
31	
32	function isValidEmail(email: string): boolean {
33	  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
34	}
