36	function webAppUrl(path: string): string {
37	  const base =
38	    process.env.ADDPLUS_WEB_URL ??
39	    process.env.CLIENT_URL?.split(',')[0]?.trim() ??
40	    'https://addplus.vercel.app';
41	  return `${base.replace(/\/$/, '')}${path}`;
42	}
