48	export class AuthService {
49	  private async buildAuthResponse(userId: string) {
50	    const user = await prisma.user.findUniqueOrThrow({ where: { id: userId } });
51	    const tokens = await this.generateTokens(user.id);
52	
53	    const vp = await prisma.vendorProfile.findFirst({
54	      where: { user_id: user.id, deleted_at: null },
55	      select: { id: true },
56	    });
57	    const vendor_profile_id = vp?.id;
58	
59	    return {
60	      user: {
61	        id: user.id,
62	        phone: user.phone,
63	        email: user.email,
64	        email_verified: !!user.email_verified_at,
65	        role: user.role,
66	        full_name: user.full_name,
67	        needs_password_setup: !user.password_hash && ['admin', 'vendor'].includes(user.role),
68	        ...(vendor_profile_id ? { vendor_profile_id } : {}),
69	      },
70	      ...tokens,
71	    };
72	  }
73	
74	  private async issueEmailVerification(userId: string, email: string, name: string) {
75	    const token = crypto.randomBytes(24).toString('hex');
76	    const code = crypto.randomInt(100000, 999999).toString();
77	    const expires = new Date(Date.now() + EMAIL_VERIFY_MS);
78	
79	    await prisma.user.update({
80	      where: { id: userId },
81	      data: {
82	        email_verification_token: token,
83	        email_verification_code: code,
84	        email_verification_expires: expires,
85	      },
86	    });
87	
88	    const link = webAppUrl(`/verify-email?token=${token}`);
89	    const result = await sendEmail(
90	      email,
91	      'Verify your ADDPlus+ account',
92	      verificationEmailHtml(name, link, code),
93	    );
94	
95	    if (!result.ok) {
96	      console.error('[ADDPlus+] verification email failed:', result.error);
97	    }
98	
99	    return { emailSent: result.ok, verificationLink: link, devCode: process.env.EXPOSE_DEV_OTP === 'true' ? code : undefined };
100	  }
101	
102	  async loginWithPassword(identifier: string, password: string) {
103	    const trimmed = identifier.trim();
104	    const isEmailLogin = trimmed.includes('@');
105	    const user = isEmailLogin
106	      ? await prisma.user.findFirst({
107	          where: { email: normalizeEmail(trimmed), deleted_at: null },
108	        })
109	      : await prisma.user.findUnique({
110	          where: { phone: normalizePhone(trimmed) },
111	        });
112	
113	    if (!user || user.deleted_at) {
114	      throw new AppError(
115	        isEmailLogin ? 'Invalid email or password' : 'Invalid phone number or password',
116	        401,
117	      );
118	    }
119	
120	    if (!user.password_hash) {
121	      if (['admin', 'vendor'].includes(user.role)) {
122	        return { needsPasswordSetup: true, phone: user.phone, role: user.role };
123	      }
124	      throw new AppError('Account has no password. Register or contact support.', 401);
125	    }
126	
127	    const valid = await bcrypt.compare(password, user.password_hash);
128	    if (!valid) {
129	      throw new AppError(
130	        isEmailLogin ? 'Invalid email or password' : 'Invalid phone number or password',
131	        401,
132	      );
133	    }
134	
135	    if (user.status !== 'active') {
136	      throw new AppError('Account is not active', 403);
137	    }
138	
139	    return this.buildAuthResponse(user.id);
140	  }
