142	  async setupPassword(phone: string, password: string) {
143	    const cleanPhone = normalizePhone(phone);
144	    const strength = validatePasswordStrength(password);
145	    if (!strength.valid) {
146	      throw new AppError(strength.errors.join('. '), 400);
147	    }
148	
149	    const user = await prisma.user.findUnique({ where: { phone: cleanPhone } });
150	    if (!user || user.deleted_at) {
151	      throw new AppError('Account not found', 404);
152	    }
153	    if (!['admin', 'vendor'].includes(user.role)) {
154	      throw new AppError('Password setup is only for admin and vendor accounts', 403);
155	    }
156	    if (user.password_hash) {
157	      throw new AppError('Password already set. Use login or change-password.', 400);
158	    }
159	
160	    const passwordHash = await bcrypt.hash(password, 12);
161	    await prisma.user.update({
162	      where: { id: user.id },
163	      data: { password_hash: passwordHash },
164	    });
165	    await invalidateUserCache(user.id);
