import jwt from 'jsonwebtoken';
import { v4 as uuidv4 } from 'uuid';
import crypto from 'crypto';
import bcrypt from 'bcryptjs';
import { AppError } from '../middleware/errorHandler';
import { SMSService } from './smsService';
import prisma from '../config/prisma';
import redisClient, { isRedisReady } from '../config/redis';
import { revokeToken, invalidateUserCache } from '../middleware/auth';
import { stringifyJsonArray, stringifyJsonObject } from '../lib/jsonFields';
import { validatePasswordStrength } from '../middleware/security';
import { sendEmail, verificationEmailHtml, passwordResetEmailHtml } from './emailService';

const OTP_RATE_LIMIT = 5;
const OTP_RATE_WINDOW = 15 * 60;
const EMAIL_VERIFY_MS = 24 * 60 * 60 * 1000;
const PASSWORD_RESET_MS = 60 * 60 * 1000;

const smsService = new SMSService();

function normalizePhone(phone: string): string {
  let clean = phone.replace(/\s/g, '').replace(/^\+/, '');
  if (clean.startsWith('0')) clean = '254' + clean.slice(1);
  if (!clean.startsWith('254')) clean = '254' + clean;
  return clean;
}

function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

function isValidEmail(email: string): boolean {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function webAppUrl(path: string): string {
  const base =
    process.env.ADDPLUS_WEB_URL ??
    process.env.CLIENT_URL?.split(',')[0]?.trim() ??
    'https://addplus.vercel.app';
  return `${base.replace(/\/$/, '')}${path}`;
}

function isOtpEnabled(): boolean {
  return process.env.ENABLE_OTP_AUTH === 'true';
}

export class AuthService {
  private async buildAuthResponse(userId: string) {
    const user = await prisma.user.findUniqueOrThrow({ where: { id: userId } });
    const tokens = await this.generateTokens(user.id);

    const vp = await prisma.vendorProfile.findFirst({
      where: { user_id: user.id, deleted_at: null },
      select: { id: true },
    });
    const vendor_profile_id = vp?.id;

    return {
      user: {
        id: user.id,
        phone: user.phone,
        email: user.email,
        email_verified: !!user.email_verified_at,
        role: user.role,
        full_name: user.full_name,
        needs_password_setup: !user.password_hash && ['admin', 'vendor'].includes(user.role),
        ...(vendor_profile_id ? { vendor_profile_id } : {}),
      },
      ...tokens,
    };
  }

  private async issueEmailVerification(userId: string, email: string, name: string) {
    const token = crypto.randomBytes(24).toString('hex');
    const code = crypto.randomInt(100000, 999999).toString();
    const expires = new Date(Date.now() + EMAIL_VERIFY_MS);

    await prisma.user.update({
      where: { id: userId },
      data: {
        email_verification_token: token,
        email_verification_code: code,
        email_verification_expires: expires,
      },
    });

    const link = webAppUrl(`/verify-email?token=${token}`);
    const result = await sendEmail(
      email,
      'Verify your ADDPlus+ account',
      verificationEmailHtml(name, link, code),
    );

    if (!result.ok) {
      console.error('[ADDPlus+] verification email failed:', result.error);
    }

    return { emailSent: result.ok, verificationLink: link, devCode: process.env.EXPOSE_DEV_OTP === 'true' ? code : undefined };
  }

  async loginWithPassword(identifier: string, password: string) {
    const trimmed = identifier.trim();
    const isEmailLogin = trimmed.includes('@');
    const user = isEmailLogin
      ? await prisma.user.findFirst({
          where: { email: normalizeEmail(trimmed), deleted_at: null },
        })
      : await prisma.user.findUnique({
          where: { phone: normalizePhone(trimmed) },
        });

    if (!user || user.deleted_at) {
      throw new AppError(
        isEmailLogin ? 'Invalid email or password' : 'Invalid phone number or password',
        401,
      );
    }

    if (!user.password_hash) {
      if (['admin', 'vendor'].includes(user.role)) {
        return { needsPasswordSetup: true, phone: user.phone, role: user.role };
      }
      throw new AppError('Account has no password. Register or contact support.', 401);
    }

    const valid = await bcrypt.compare(password, user.password_hash);
    if (!valid) {
      throw new AppError(
        isEmailLogin ? 'Invalid email or password' : 'Invalid phone number or password',
        401,
      );
    }

    if (user.status !== 'active') {
      throw new AppError('Account is not active', 403);
    }

    return this.buildAuthResponse(user.id);
  }

  async setupPassword(phone: string, password: string) {
    const cleanPhone = normalizePhone(phone);
    const strength = validatePasswordStrength(password);
    if (!strength.valid) {
      throw new AppError(strength.errors.join('. '), 400);
    }

    const user = await prisma.user.findUnique({ where: { phone: cleanPhone } });
    if (!user || user.deleted_at) {
      throw new AppError('Account not found', 404);
    }
    if (!['admin', 'vendor'].includes(user.role)) {
      throw new AppError('Password setup is only for admin and vendor accounts', 403);
    }
    if (user.password_hash) {
      throw new AppError('Password already set. Use login or change-password.', 400);
    }

    const passwordHash = await bcrypt.hash(password, 12);
    await prisma.user.update({
      where: { id: user.id },
      data: { password_hash: passwordHash },
    });
    await invalidateUserCache(user.id);

    return this.buildAuthResponse(user.id);
  }

  async registerAccount(phone: string, password: string, fullName?: string, email?: string) {
    const cleanPhone = normalizePhone(phone);
    const phoneRegex = /^254[0-9]{9}$/;
    if (!phoneRegex.test(cleanPhone)) {
      throw new AppError('Invalid phone number format. Use 254XXXXXXXXX', 400);
    }

    if (!email?.trim()) {
      throw new AppError('Email is required', 400);
    }
    const cleanEmail = normalizeEmail(email);
    if (!isValidEmail(cleanEmail)) {
      throw new AppError('Invalid email address', 400);
    }

    const strength = validatePasswordStrength(password);
    if (!strength.valid) {
      throw new AppError(strength.errors.join('. '), 400);
    }

    const emailTaken = await prisma.user.findFirst({
      where: { email: cleanEmail, deleted_at: null },
    });
    if (emailTaken && emailTaken.phone !== cleanPhone) {
      throw new AppError('Email already registered. Sign in instead.', 409);
    }

    const existing = await prisma.user.findUnique({ where: { phone: cleanPhone } });
    if (existing) {
      if (existing.password_hash) {
        throw new AppError('Phone already registered. Sign in instead.', 409);
      }
      const passwordHash = await bcrypt.hash(password, 12);
      await prisma.user.update({
        where: { id: existing.id },
        data: {
          password_hash: passwordHash,
          full_name: fullName?.trim() || existing.full_name,
          email: cleanEmail,
          email_verified_at: null,
        },
      });
      const verification = await this.issueEmailVerification(
        existing.id,
        cleanEmail,
        fullName?.trim() || existing.full_name || 'there',
      );
      const auth = await this.buildAuthResponse(existing.id);
      return { ...auth, verification };
    }

    const passwordHash = await bcrypt.hash(password, 12);
    const user = await prisma.user.create({
      data: {
        phone: cleanPhone,
        email: cleanEmail,
        role: 'customer',
        status: 'active',
        full_name: fullName?.trim() || null,
        password_hash: passwordHash,
      },
    });

    const verification = await this.issueEmailVerification(
      user.id,
      cleanEmail,
      fullName?.trim() || 'there',
    );
    const auth = await this.buildAuthResponse(user.id);
    return { ...auth, verification };
  }

  async verifyEmail(input: { token?: string; code?: string; email?: string }) {
    const { token, code, email } = input;
    if (!token && !(code && email)) {
      throw new AppError('Verification token or code with email is required', 400);
    }

    const user = token
      ? await prisma.user.findFirst({
          where: { email_verification_token: token, deleted_at: null },
        })
      : await prisma.user.findFirst({
          where: {
            email: normalizeEmail(email!),
            email_verification_code: code,
            deleted_at: null,
          },
        });

    if (!user) {
      throw new AppError('Invalid or expired verification', 400);
    }
    if (!user.email_verification_expires || user.email_verification_expires < new Date()) {
      throw new AppError('Verification has expired. Request a new email.', 400);
    }

    await prisma.user.update({
      where: { id: user.id },
      data: {
        email_verified_at: new Date(),
        email_verification_token: null,
        email_verification_code: null,
        email_verification_expires: null,
      },
    });
    await invalidateUserCache(user.id);

    return this.buildAuthResponse(user.id);
  }

  async resendVerificationEmail(userId: string) {
    const user = await prisma.user.findUnique({ where: { id: userId } });
    if (!user || user.deleted_at) {
      throw new AppError('User not found', 404);
    }
    if (!user.email) {
      throw new AppError('No email on account', 400);
    }
    if (user.email_verified_at) {
      throw new AppError('Email already verified', 400);
    }

    const verification = await this.issueEmailVerification(
      user.id,
      user.email,
      user.full_name || 'there',
    );
    return { message: 'Verification email sent', ...verification };
  }

  async requestPasswordReset(email: string) {
    const normalized = normalizeEmail(email);
    if (!isValidEmail(normalized)) {
      throw new AppError('Invalid email address', 400);
    }

    const user = await prisma.user.findFirst({
      where: { email: normalized, deleted_at: null },
    });

    const generic = { message: 'If an account exists for that email, a reset link has been sent.' };

    if (!user?.password_hash) {
      return generic;
    }

    const token = crypto.randomBytes(24).toString('hex');
    const expires = new Date(Date.now() + PASSWORD_RESET_MS);

    await prisma.user.update({
      where: { id: user.id },
      data: {
        password_reset_token: token,
        password_reset_expires: expires,
      },
    });

    const link = webAppUrl(`/reset-password?token=${token}`);
    const result = await sendEmail(
      normalized,
      'Reset your ADDPlus+ password',
      passwordResetEmailHtml(user.full_name || 'there', link),
    );

    if (!result.ok) {
      console.error('[ADDPlus+] password reset email failed:', result.error);
    }

    return { ...generic, emailSent: result.ok };
  }

  async resetPassword(token: string, password: string) {
    const strength = validatePasswordStrength(password);
    if (!strength.valid) {
      throw new AppError(strength.errors.join('. '), 400);
    }

    const user = await prisma.user.findFirst({
      where: { password_reset_token: token, deleted_at: null },
    });

    if (!user?.password_reset_expires || user.password_reset_expires < new Date()) {
      throw new AppError('Invalid or expired reset link', 400);
    }

    const passwordHash = await bcrypt.hash(password, 12);

    await prisma.user.update({
      where: { id: user.id },
      data: {
        password_hash: passwordHash,
        password_reset_token: null,
        password_reset_expires: null,
      },
    });

    await prisma.refreshToken.deleteMany({ where: { user_id: user.id } });
    await invalidateUserCache(user.id);

    return { message: 'Password updated. You can sign in now.' };
  }

  async requestOTP(phone: string) {
    if (!isOtpEnabled()) {
      throw new AppError('OTP login is disabled. Use phone and password.', 503);
    }
    const phoneRegex = /^254[0-9]{9}$/;
    const cleanPhone = phone.replace(/\s/g, '').replace(/^0/, '254').replace(/^\+/, '');

    if (!phoneRegex.test(cleanPhone)) {
      throw new AppError('Invalid phone number format. Use 254XXXXXXXXX', 400);
    }

    if (isRedisReady()) {
      const key = `otp:rate:${cleanPhone}`;
      const count = await redisClient.incr(key);
      if (count === 1) await redisClient.expire(key, OTP_RATE_WINDOW);
      if (count > OTP_RATE_LIMIT) {
        const ttl = await redisClient.ttl(key);
        throw new AppError(`Too many OTP requests. Try again in ${Math.ceil(ttl / 60)} minutes.`, 429);
      }
    }

    const code = crypto.randomInt(100000, 999999).toString();
    const expiresAt = new Date(Date.now() + 10 * 60 * 1000);

    await prisma.otpCode.updateMany({
      where: { phone: cleanPhone, used: false },
      data: { used: true },
    });

    await prisma.otpCode.create({
      data: {
        phone: cleanPhone,
        code,
        expires_at: expiresAt,
      },
    });

    await smsService.sendOTP(cleanPhone, code);

    const devExpose =
      process.env.NODE_ENV === 'development' || process.env.EXPOSE_DEV_OTP === 'true';

    return {
      message: 'OTP sent successfully',
      expiresIn: '10 minutes',
      ...(devExpose ? { devCode: code } : {}),
    };
  }

  async verifyOTP(phone: string, code: string, fullName?: string) {
    if (!isOtpEnabled()) {
      throw new AppError('OTP login is disabled. Use phone and password.', 503);
    }
    const cleanPhone = normalizePhone(phone);

    const otpRecord = await prisma.otpCode.findFirst({
      where: {
        phone: cleanPhone,
        code,
        used: false,
        expires_at: { gt: new Date() },
      },
    });

    if (!otpRecord) {
      throw new AppError('Invalid or expired OTP', 400);
    }

    await prisma.otpCode.update({
      where: { id: otpRecord.id },
      data: { used: true },
    });

    let user = await prisma.user.findUnique({
      where: { phone: cleanPhone },
    });

    if (!user) {
      user = await prisma.user.create({
        data: {
          phone: cleanPhone,
          role: 'customer',
          otp_verified: true,
          full_name: fullName?.trim() || null,
        },
      });
    } else {
      await prisma.user.update({
        where: { id: user.id },
        data: {
          otp_verified: true,
          ...(fullName?.trim() ? { full_name: fullName.trim() } : {}),
        },
      });
      user = await prisma.user.findUniqueOrThrow({ where: { id: user.id } });
    }

    return this.buildAuthResponse(user.id);
  }

  async registerVendor(userId: string, vendorData: any) {
    const user = await prisma.user.findUnique({
      where: { id: userId },
    });

    if (!user) {
      throw new AppError('User not found', 404);
    }

    if (user.role !== 'customer') {
      throw new AppError('User already has a role', 400);
    }

    const referralCode = this.generateReferralCode(vendorData.business_name);

    const autoApprove = process.env.AUTO_APPROVE_VENDORS !== 'false';

    const vendorProfile = await prisma.vendorProfile.create({
      data: {
        user_id: userId,
        business_name: vendorData.business_name,
        description: vendorData.description,
        category_ids: stringifyJsonArray(vendorData.category_ids),
        location_lat: vendorData.location_lat,
        location_lng: vendorData.location_lng,
        location_address: vendorData.location_address,
        mpesa_number: vendorData.mpesa_number || user.phone,
        business_photos: stringifyJsonArray(vendorData.business_photos),
        referral_code: referralCode,
        documents: stringifyJsonObject(vendorData.documents),
        kyc_status: autoApprove ? 'approved' : 'pending',
        compliance_score: autoApprove ? 50 : 0,
      },
    });

    await prisma.user.update({
      where: { id: userId },
      data: { role: 'vendor' },
    });

    await invalidateUserCache(userId);

    return {
      message: autoApprove
        ? 'Vendor store created — add your first product'
        : 'Vendor registration submitted for approval',
      vendorId: vendorProfile.id,
      kycStatus: vendorProfile.kyc_status,
    };
  }

  async refreshToken(refreshToken: string) {
    const storedToken = await prisma.refreshToken.findUnique({
      where: { token: refreshToken },
      include: { user: true },
    });

    if (!storedToken || storedToken.expires_at < new Date()) {
      throw new AppError('Invalid or expired refresh token', 401);
    }

    const user = storedToken.user;
    if (user.deleted_at || user.status !== 'active') {
      await prisma.refreshToken.delete({ where: { id: storedToken.id } }).catch(() => undefined);
      throw new AppError('Invalid or expired refresh token', 401);
    }

    await prisma.refreshToken.delete({
      where: { id: storedToken.id },
    });

    return this.generateTokens(storedToken.user_id);
  }

  async logout(userId: string, refreshToken?: string, accessToken?: string) {
    if (accessToken) {
      await revokeToken(accessToken);
    }

    await invalidateUserCache(userId);

    if (refreshToken) {
      await prisma.refreshToken.deleteMany({ where: { token: refreshToken } });
    } else {
      await prisma.refreshToken.deleteMany({ where: { user_id: userId } });
    }

    return { message: 'Logged out successfully' };
  }

  private async generateTokens(userId: string) {
    if (!process.env.JWT_SECRET) {
      throw new Error('JWT_SECRET not configured');
    }

    const accessToken = jwt.sign({ userId }, process.env.JWT_SECRET, {
      expiresIn: '15m',
      algorithm: 'HS256',
      issuer: process.env.JWT_ISSUER || 'addplus-api',
      audience: process.env.JWT_AUDIENCE || 'addplus-client',
    });

    const refreshToken = uuidv4();
    const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

    await prisma.refreshToken.create({
      data: {
        user_id: userId,
        token: refreshToken,
        expires_at: refreshExpires,
      },
    });

    return {
      accessToken,
      refreshToken,
      expiresIn: '15m',
    };
  }

  private generateReferralCode(businessName: string): string {
    const clean = businessName.toUpperCase().replace(/[^A-Z0-9]/g, '').substring(0, 8);
    const random = Math.floor(1000 + Math.random() * 9000);
    return `${clean}${random}`;
  }
}

