import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';
import { AppError } from './errorHandler';
import { securityLog } from './requestLogger';
import prisma from '../config/prisma';
import redisClient, { isRedisReady } from '../config/redis';

const USER_CACHE_TTL = 300; // 5 minutes
const ACCESS_TOKEN_TTL = 900; // 15 minutes — matches JWT expiry

export interface AuthRequest extends Request {
  user?: {
    id: string;
    phone: string;
    role: string;
  };
}

// Security: Enhanced authentication with comprehensive validation
export const authenticate = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const authHeader = req.headers.authorization;

    // Security: Check for Authorization header presence and format
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res.status(401).json({ error: 'Access denied. No token provided.' });
    }

    const token = authHeader.substring(7);

    // Security: Validate token format (JWT structure: header.payload.signature)
    const tokenParts = token.split('.');
    if (tokenParts.length !== 3) {
      return res.status(401).json({ error: 'Invalid token format' });
    }

    // H1: Check Redis token blacklist (revoked tokens)
    if (isRedisReady()) {
      const blacklisted = await redisClient.get(`blacklist:${token}`);
      if (blacklisted) {
        return res.status(401).json({ error: 'Token has been revoked. Please login again.' });
      }
    }

    // Security: Verify JWT secret is configured
    if (!process.env.JWT_SECRET) {
      console.error('Security Error: JWT_SECRET not configured');
      throw new AppError('Authentication service unavailable', 503);
    }

    // Security: Verify token with strict options
    const decoded = jwt.verify(token, process.env.JWT_SECRET, {
      algorithms: ['HS256'], // Only allow HS256 algorithm
      issuer: process.env.JWT_ISSUER || 'addplus-api',
      audience: process.env.JWT_AUDIENCE || 'addplus-client'
    }) as any;

    // Security: Validate token payload structure
    if (!decoded.userId || !decoded.iat || !decoded.exp) {
      return res.status(401).json({ error: 'Invalid token payload' });
    }

    // Security: Check token expiration manually as extra safety
    const now = Math.floor(Date.now() / 1000);
    if (decoded.exp < now) {
      return res.status(401).json({ error: 'Token has expired. Please login again.' });
    }

    // H7: Try Redis user cache before hitting DB
    let user: { id: string; phone: string; role: string; status: string; deleted_at: Date | null } | null = null;
    if (isRedisReady()) {
      const cached = await redisClient.get(`user:${decoded.userId}`);
      if (cached) user = JSON.parse(cached);
    }
    if (!user) {
      user = await prisma.user.findUnique({
        where: { id: decoded.userId },
        select: { id: true, phone: true, role: true, status: true, deleted_at: true }
      });
      if (user && isRedisReady()) {
        await redisClient.setEx(`user:${decoded.userId}`, USER_CACHE_TTL, JSON.stringify(user));
      }
    }

    if (!user) {
      return res.status(401).json({ error: 'User not found. Token may be invalid.' });
    }

    // Security: Check if user account is active (UserStatus enum uses lowercase)
    if (user.status !== 'active') {
      return res.status(403).json({ error: 'Account is not active. Please contact support.' });
    }

    // Security: Check if user account is deleted
    if (user.deleted_at) {
      return res.status(401).json({ error: 'Account has been deleted.' });
    }

    // Security: Attach user to request for downstream use
    req.user = {
      id: user.id,
      phone: user.phone,
      role: user.role
    };

    next();
  } catch (error) {
    if (error instanceof jwt.JsonWebTokenError) {
      return res.status(401).json({ error: 'Invalid token. Authentication failed.' });
    }
    if (error instanceof jwt.TokenExpiredError) {
      return res.status(401).json({ error: 'Token has expired. Please login again.' });
    }
    if (error instanceof jwt.NotBeforeError) {
      return res.status(401).json({ error: 'Token not active. Please try again later.' });
    }

    // Security: Log unexpected authentication errors
    console.error('Authentication error:', error);
    return res.status(500).json({ error: 'Authentication service error' });
  }
};

// Security: Role-based authorization middleware
export const authorize = (...roles: string[]) => {
  return (req: AuthRequest, res: Response, next: NextFunction) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Authentication required' });
    }

    if (!roles.includes(req.user.role)) {
      // Security: Log unauthorized access using structured audit format
      securityLog('unauthorized_access', req as any, {
        userId: req.user.id,
        userRole: req.user.role,
        requiredRoles: roles
      }, req.user.id);

      return res.status(403).json({ error: 'Access denied. Insufficient permissions.' });
    }

    next();
  };
};

// Security: Ownership verification middleware
// Ensures users can only access/modify their own resources
export const verifyOwnership = (paramName: string = 'id') => {
  return async (req: AuthRequest, res: Response, next: NextFunction) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Authentication required' });
    }

    const resourceId = req.params[paramName];

    // Admins can access any resource
    if (req.user.role === 'admin') {
      return next();
    }

    // For vendors, verify they own the resource
    if (req.user.role === 'vendor') {
      const vendorProfile = await prisma.vendorProfile.findFirst({
        where: { user_id: req.user.id },
        select: { id: true }
      });

      if (!vendorProfile) {
        return res.status(403).json({ error: 'Vendor profile not found' });
      }

      const resource = await prisma.product.findFirst({
        where: { 
          id: resourceId,
          vendor_id: vendorProfile.id
        },
        select: { id: true }
      });

      if (!resource) {
        return res.status(403).json({ error: 'Access denied. You do not own this resource.' });
      }
    }

    // Customers can only access their own resources
    if (req.user.role === 'customer') {
      // Add logic for customer-specific resource ownership
      // This depends on the specific resource type (orders, reviews, etc.)
    }

    next();
  };
};

// H1: Revoke access token in Redis with TTL equal to remaining token lifetime
export const revokeToken = async (token: string): Promise<void> => {
  if (!isRedisReady()) return;
  await redisClient.setEx(`blacklist:${token}`, ACCESS_TOKEN_TTL, '1');
};

// H7: Invalidate cached user (call on suspend/delete/role-change)
export const invalidateUserCache = async (userId: string): Promise<void> => {
  if (!isRedisReady()) return;
  await redisClient.del(`user:${userId}`);
};

