import axios from 'axios';
import { AppError } from '../middleware/errorHandler';
import prisma from '../config/prisma';
import { parseDarajaOrderReference } from '../lib/paymentReferences';
import { confirmOrderPayment, failOrderPayment } from './paymentConfirmationService';

/** Public Daraja sandbox defaults for Lipa Na M-Pesa Online (STK Push). */
const SANDBOX_SHORTCODE = '174379';
const SANDBOX_PASSKEY =
  'bfb279f9aa9bdbcf158e97dd71a467cd2e0c893059b10f78e6b72ada1ed2c919';

export class MPesaService {
  private consumerKey: string;
  private consumerSecret: string;
  private passkey: string;
  private shortcode: string;
  private env: 'sandbox' | 'production';

  constructor() {
    this.env = (process.env.MPESA_ENV as 'sandbox' | 'production') || 'sandbox';
    this.consumerKey = (process.env.MPESA_CONSUMER_KEY || '').trim();
    this.consumerSecret = (process.env.MPESA_CONSUMER_SECRET || '').trim();
    this.shortcode = (process.env.MPESA_SHORTCODE || '').trim();
    this.passkey = (process.env.MPESA_PASSKEY || '').trim();

    if (this.env === 'sandbox') {
      if (!this.shortcode) this.shortcode = SANDBOX_SHORTCODE;
      if (!this.passkey) this.passkey = SANDBOX_PASSKEY;
    } else if (!this.shortcode) {
      this.shortcode = SANDBOX_SHORTCODE;
    }
  }

  // Security: Validate M-Pesa webhook signature
  validateWebhookSignature(callbackData: any, signature: string | undefined): boolean {
    // Security: M-Pesa callbacks should be validated with a signature
    // In production, Safaricom provides a way to validate callbacks
    // This is a placeholder implementation - actual implementation depends on M-Pesa's specific signature mechanism

    if (!signature) {
      console.warn('Security Warning: M-Pesa callback received without signature');
      // In sandbox, allow without signature for testing
      if (this.env === 'sandbox') {
        return true;
      }
      return false;
    }

    // Security: Implement signature verification logic here
    // This would typically involve:
    // 1. Extracting timestamp and signed content
    // 2. Using shared secret to compute expected signature
    // 3. Comparing with provided signature using timing-safe comparison

    // For now, log the signature for monitoring
    console.log('M-Pesa callback signature received:', signature.substring(0, 20) + '...');

    return true; // TODO: Implement actual signature verification
  }

  // Security: Validate callback origin IP (optional additional security)
  validateCallbackOrigin(ip: string): boolean {
    const normalized = ip.replace(/^::ffff:/, '');
    const defaults =
      '196.201.214.200,196.201.214.206,196.201.213.114,196.201.214.207,196.201.214.208,196.201.213.44,196.201.212.127,196.201.212.138,196.201.212.129,196.201.212.136,196.201.212.74,196.201.212.69';
    const allowedOrigins = (process.env.MPESA_CALLBACK_IPS || defaults).split(',').map((s) => s.trim());
    return allowedOrigins.includes(normalized);
  }

  private getBaseUrl(): string {
    return this.env === 'production'
      ? 'https://api.safaricom.co.ke'
      : 'https://sandbox.safaricom.co.ke';
  }

  private darajaHeaders(extra: Record<string, string> = {}): Record<string, string> {
    return {
      'Content-Type': 'application/json',
      'User-Agent': 'ADDPlus-API/1.0',
      ...extra,
    };
  }

  private async getAccessToken(): Promise<string> {
    if (!this.consumerKey || !this.consumerSecret) {
      throw new AppError('M-Pesa consumer key/secret not configured', 500);
    }

    const url = `${this.getBaseUrl()}/oauth/v1/generate?grant_type=client_credentials`;
    const auth = Buffer.from(`${this.consumerKey}:${this.consumerSecret}`).toString('base64');

    try {
      const response = await axios.get(url, {
        headers: this.darajaHeaders({ Authorization: `Basic ${auth}` }),
      });
      const token = response.data?.access_token;
      if (!token) {
        console.error('M-Pesa auth: no access_token in response', response.data);
        throw new AppError('Failed to authenticate with M-Pesa', 500);
      }
      return token;
    } catch (error: any) {
      console.error('M-Pesa auth error:', error.response?.data || error.message);
      throw new AppError('Failed to authenticate with M-Pesa', 500);
    }
  }

  async initiateSTKPush(
    phone: string,
    amount: number,
    orderId: string,
    description: string
  ): Promise<any> {
    const accessToken = await this.getAccessToken();
    const url = `${this.getBaseUrl()}/mpesa/stkpush/v1/processrequest`;

    const timestamp = this.generateTimestamp();
    const password = Buffer.from(
      `${this.shortcode}${this.passkey}${timestamp}`
    ).toString('base64');

    const cleanPhone = phone.startsWith('0') 
      ? `254${phone.substring(1)}` 
      : phone.startsWith('+') 
        ? phone.substring(1) 
        : phone;

    const payload = {
      BusinessShortCode: this.shortcode,
      Password: password,
      Timestamp: timestamp,
      TransactionType: 'CustomerPayBillOnline',
      Amount: Math.round(amount),
      PartyA: cleanPhone,
      PartyB: this.shortcode,
      PhoneNumber: cleanPhone,
      CallBackURL: `${process.env.API_BASE_URL}/v1/payments/mpesa/stk-callback`,
      AccountReference: `ADDPlus-${orderId}`,
      TransactionDesc: description.substring(0, 13)
    };

    try {
      const response = await axios.post(url, payload, {
        headers: this.darajaHeaders({ Authorization: `Bearer ${accessToken}` }),
      });

      const data = response.data;
      if (data.ResponseCode && data.ResponseCode !== '0') {
        console.error('STK Push rejected:', data);
        throw new AppError(data.CustomerMessage || data.ResponseDescription || 'Payment request rejected', 502);
      }

      return {
        checkoutRequestID: data.CheckoutRequestID,
        merchantRequestID: data.MerchantRequestID,
        responseCode: data.ResponseCode,
        responseDescription: data.ResponseDescription,
        customerMessage: data.CustomerMessage,
      };
    } catch (error: any) {
      if (error instanceof AppError) throw error;
      const daraja = error.response?.data;
      console.error('STK Push error:', daraja || error.message);
      const hint =
        daraja?.errorCode === '404.001.03'
          ? 'Check MPESA_CONSUMER_KEY/SECRET and that Lipa Na M-Pesa Online is enabled on your Daraja app'
          : undefined;
      if (hint) console.error('STK Push hint:', hint);
      throw new AppError('Failed to initiate payment', 500);
    }
  }

  // Security: Enhanced STK callback handler with validation
  async handleSTKCallback(callbackData: any, signature?: string, clientIp?: string): Promise<void> {
    // Security: Validate webhook signature
    if (!this.validateWebhookSignature(callbackData, signature)) {
      throw new AppError('Invalid webhook signature', 401);
    }

    // Security: Validate callback origin (if configured)
    if (clientIp && !this.validateCallbackOrigin(clientIp)) {
      console.error('Security Alert: M-Pesa callback from unauthorized IP:', clientIp);
      throw new AppError('Unauthorized callback origin', 403);
    }

    // Security: Log all payment callbacks for audit trail
    console.log('M-Pesa STK Callback received:', {
      timestamp: new Date().toISOString(),
      ip: clientIp,
      hasSignature: !!signature,
      merchantRequestID: callbackData?.Body?.stkCallback?.MerchantRequestID
    });

    const { Body } = callbackData;
    const checkoutRequestId = Body?.stkCallback?.CheckoutRequestID;

    // M2 fix: Idempotency check — look up order by mpesa_request_id to detect duplicate callbacks
    if (checkoutRequestId) {
      const existingOrder = await prisma.order.findFirst({
        where: { mpesa_request_id: checkoutRequestId, status: 'confirmed' }
      });
      if (existingOrder) {
        console.log(`Duplicate STK callback ignored for CheckoutRequestID: ${checkoutRequestId}`);
        return;
      }
    }

    if (!Body || Body.stkCallback.ResultCode !== 0) {
      const failedOrderId = parseDarajaOrderReference(
        Body?.stkCallback?.CallbackMetadata?.Item?.find((i: any) => i.Name === 'AccountReference')?.Value || ''
      );

      if (failedOrderId) {
        await failOrderPayment(failedOrderId, Body?.stkCallback?.CheckoutRequestID);
      }
      return;
    }

    const metadata = Body.stkCallback.CallbackMetadata.Item;
    const mpesaReceipt = metadata.find((i: any) => i.Name === 'MpesaReceiptNumber')?.Value;
    const phone = metadata.find((i: any) => i.Name === 'PhoneNumber')?.Value;
    const amount = metadata.find((i: any) => i.Name === 'Amount')?.Value;
    const accountRef = metadata.find((i: any) => i.Name === 'AccountReference')?.Value;

    const orderId = parseDarajaOrderReference(accountRef);

    if (!orderId) {
      console.error('Could not extract order ID from reference:', accountRef);
      return;
    }

    await confirmOrderPayment({
      orderId,
      mpesaReceipt: mpesaReceipt?.toString(),
      mpesaPhone: phone?.toString(),
      checkoutRequestId,
      paidKes: Math.round(Number(amount || 0)),
    });
  }

  // H4: Importation deposit STK Push — uses IMPORT-{requestId} account ref + dedicated callback
  async initiateImportationDepositSTK(
    phone: string,
    amount: number,
    requestId: string
  ): Promise<any> {
    const accessToken = await this.getAccessToken();
    const url = `${this.getBaseUrl()}/mpesa/stkpush/v1/processrequest`;

    const timestamp = this.generateTimestamp();
    const password = Buffer.from(
      `${this.shortcode}${this.passkey}${timestamp}`
    ).toString('base64');

    const cleanPhone = phone.startsWith('0')
      ? `254${phone.substring(1)}`
      : phone.startsWith('+')
        ? phone.substring(1)
        : phone;

    const payload = {
      BusinessShortCode: this.shortcode,
      Password: password,
      Timestamp: timestamp,
      TransactionType: 'CustomerPayBillOnline',
      Amount: Math.round(amount),
      PartyA: cleanPhone,
      PartyB: this.shortcode,
      PhoneNumber: cleanPhone,
      CallBackURL: `${process.env.API_BASE_URL}/v1/importation/stk-callback`,
      AccountReference: `IMPORT-${requestId}`,
      TransactionDesc: 'Importation deposit'
    };

    try {
      const response = await axios.post(url, payload, {
        headers: { Authorization: `Bearer ${accessToken}` }
      });

      return {
        checkoutRequestID: response.data.CheckoutRequestID,
        merchantRequestID: response.data.MerchantRequestID,
        responseCode: response.data.ResponseCode,
        responseDescription: response.data.ResponseDescription,
        customerMessage: response.data.CustomerMessage
      };
    } catch (error: any) {
      console.error('Importation STK Push error:', error.response?.data || error.message);
      throw new AppError('Failed to initiate importation deposit payment', 500);
    }
  }

  // H4: Handle importation deposit STK callback — matches by deposit_checkout_request_id
  async handleImportationSTKCallback(callbackData: any, signature?: string, clientIp?: string): Promise<void> {
    if (!this.validateWebhookSignature(callbackData, signature)) {
      throw new AppError('Invalid webhook signature', 401);
    }
    if (clientIp && !this.validateCallbackOrigin(clientIp)) {
      throw new AppError('Unauthorized callback origin', 403);
    }

    const { Body } = callbackData;
    const checkoutRequestId = Body?.stkCallback?.CheckoutRequestID;

    if (!checkoutRequestId) return;

    // Idempotency: skip if already confirmed
    const existing = await prisma.importationRequest.findFirst({
      where: { deposit_checkout_request_id: checkoutRequestId, deposit_mpesa_ref: { not: 'PENDING' } }
    });
    if (existing && existing.deposit_mpesa_ref && existing.deposit_mpesa_ref !== 'PENDING') {
      console.log(`Duplicate importation STK callback ignored for ${checkoutRequestId}`);
      return;
    }

    if (!Body || Body.stkCallback.ResultCode !== 0) {
      // Payment failed — reset deposit fields
      await prisma.importationRequest.updateMany({
        where: { deposit_checkout_request_id: checkoutRequestId },
        data: { deposit_mpesa_ref: null, deposit_amount_cents: null, deposit_checkout_request_id: null }
      });
      console.log(`Importation deposit failed for checkout ${checkoutRequestId}: ${Body?.stkCallback?.ResultDesc}`);
      return;
    }

    const metadata = Body.stkCallback.CallbackMetadata.Item;
    const mpesaReceipt = metadata.find((i: any) => i.Name === 'MpesaReceiptNumber')?.Value;
    const amount = metadata.find((i: any) => i.Name === 'Amount')?.Value;

    await prisma.importationRequest.updateMany({
      where: { deposit_checkout_request_id: checkoutRequestId },
      data: { deposit_mpesa_ref: mpesaReceipt, deposit_amount_cents: Number(amount || 0) }
    });

    console.log(`Importation deposit confirmed: ${mpesaReceipt} for checkout ${checkoutRequestId}`);
  }

  async initiateB2CPayout(
    phone: string,
    amount: number,
    remarks: string,
    occasion: string
  ): Promise<any> {
    const accessToken = await this.getAccessToken();
    const url = `${this.getBaseUrl()}/mpesa/b2c/v1/paymentrequest`;

    const cleanPhone = phone.startsWith('0') 
      ? `254${phone.substring(1)}` 
      : phone.startsWith('+') 
        ? phone.substring(1) 
        : phone;

    const payload = {
      InitiatorName: process.env.MPESA_INITIATOR_NAME,
      SecurityCredential: process.env.MPESA_SECURITY_CREDENTIAL,
      CommandID: 'BusinessPayment',
      Amount: Math.round(amount),
      PartyA: this.shortcode,
      PartyB: cleanPhone,
      Remarks: remarks.substring(0, 140),
      QueueTimeOutURL: `${process.env.API_BASE_URL}/v1/payments/mpesa/b2c-timeout`,
      ResultURL: `${process.env.API_BASE_URL}/v1/payments/mpesa/b2c-callback`,
      Occasion: occasion.substring(0, 20)
    };

    try {
      const response = await axios.post(url, payload, {
        headers: { Authorization: `Bearer ${accessToken}` }
      });

      return {
        conversationID: response.data.ConversationID,
        originatorConversationID: response.data.OriginatorConversationID,
        responseCode: response.data.ResponseCode,
        responseDescription: response.data.ResponseDescription
      };
    } catch (error: any) {
      console.error('B2C error:', error.response?.data || error.message);
      throw new AppError('Failed to initiate payout', 500);
    }
  }

  // Security: Enhanced B2C callback handler with validation
  async handleB2CCallback(callbackData: any, signature?: string, clientIp?: string): Promise<void> {
    // Security: Validate webhook signature
    if (!this.validateWebhookSignature(callbackData, signature)) {
      throw new AppError('Invalid webhook signature', 401);
    }

    // Security: Validate callback origin
    if (clientIp && !this.validateCallbackOrigin(clientIp)) {
      console.error('Security Alert: B2C callback from unauthorized IP:', clientIp);
      throw new AppError('Unauthorized callback origin', 403);
    }

    // Security: Log callback for audit
    console.log('M-Pesa B2C Callback received:', {
      timestamp: new Date().toISOString(),
      ip: clientIp,
      hasSignature: !!signature,
      conversationID: callbackData?.Result?.ConversationID
    });

    const { Result } = callbackData;

    if (Result.ResultCode === 0) {
      // Successful payout
      const transactionId = Result.TransactionID;

      // Update escrow ledger
      await prisma.escrowLedger.updateMany({
        where: { payout_mpesa_ref: transactionId },
        data: { 
          status: 'released',
          released_at: new Date()
        }
      });
    } else {
      console.error('B2C failed:', Result.ResultDesc);
      // Handle failed payout - notify admin
    }
  }

  private generateTimestamp(): string {
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    const hours = String(now.getHours()).padStart(2, '0');
    const minutes = String(now.getMinutes()).padStart(2, '0');
    const seconds = String(now.getSeconds()).padStart(2, '0');
    return `${year}${month}${day}${hours}${minutes}${seconds}`;
  }
}

