import { AppError } from '../middleware/errorHandler';
import { toCents } from '../lib/money';
import { MPesaService } from './mpesaService';
import prisma from '../config/prisma';
const mpesaService = new MPesaService();

export class FundService {
  async getFundBalance() {
    const [advancementContributions, profitShareContributions, disbursements] = await Promise.all([
      prisma.collectiveFund.aggregate({
        where: { type: 'advancement_contribution' },
        _sum: { amount_cents: true }
      }),
      prisma.collectiveFund.aggregate({
        where: { type: 'profit_share_contribution' },
        _sum: { amount_cents: true }
      }),
      prisma.collectiveFund.aggregate({
        where: { type: 'disbursement' },
        _sum: { amount_cents: true }
      })
    ]);

    const totalContributions =
      Number(advancementContributions._sum.amount_cents || 0) +
      Number(profitShareContributions._sum.amount_cents || 0);
    const totalDisbursements = Number(disbursements._sum.amount_cents || 0);
    const balance = totalContributions - totalDisbursements;

    const sixMonthsAgo = new Date(Date.now() - 6 * 30 * 24 * 60 * 60 * 1000);
    const monthlyRows = await prisma.collectiveFund.findMany({
      where: { created_at: { gte: sixMonthsAgo } },
      select: { created_at: true, type: true, amount_cents: true },
      orderBy: { created_at: 'desc' },
    });

    const monthlyMap = new Map<string, { contributions: number; disbursements: number }>();
    for (const row of monthlyRows) {
      const month = row.created_at.toISOString().slice(0, 7);
      const bucket = monthlyMap.get(month) ?? { contributions: 0, disbursements: 0 };
      if (row.type === 'advancement_contribution' || row.type === 'profit_share_contribution') {
        bucket.contributions += Number(row.amount_cents || 0);
      } else if (row.type === 'disbursement') {
        bucket.disbursements += Number(row.amount_cents || 0);
      }
      monthlyMap.set(month, bucket);
    }

    const monthlyData = [...monthlyMap.entries()]
      .sort(([a], [b]) => b.localeCompare(a))
      .map(([month, data]) => ({ month, ...data }));

    return {
      balance,
      advancement_fund: advancementContributions._sum.amount_cents || 0,
      profit_share_pool: profitShareContributions._sum.amount_cents || 0,
      total_contributions: totalContributions,
      total_disbursements: totalDisbursements,
      monthly_trend: monthlyData
    };
  }

  async getVendorContributions(vendorId: string) {
    const contributions = await prisma.collectiveFund.findMany({
      where: {
        vendor_id: vendorId,
        type: { in: ['advancement_contribution', 'profit_share_contribution'] }
      },
      orderBy: { created_at: 'desc' }
    });

    const total = await prisma.collectiveFund.aggregate({
      where: {
        vendor_id: vendorId,
        type: { in: ['advancement_contribution', 'profit_share_contribution'] }
      },
      _sum: { amount_cents: true }
    });

    return {
      contributions,
      total_contributed: total._sum.amount_cents || 0
    };
  }

  async getFundLedger(filters: any) {
    const where: any = {};

    if (filters.type) {
      where.type = filters.type;
    }

    if (filters.vendor_id) {
      where.vendor_id = filters.vendor_id;
    }

    const entries = await prisma.collectiveFund.findMany({
      where,
      orderBy: { created_at: 'desc' },
      skip: (filters.page - 1) * filters.limit,
      take: filters.limit,
      include: {
        vendor: {
          select: { business_name: true }
        }
      }
    });

    const total = await prisma.collectiveFund.count({ where });

    return { entries, total, page: filters.page, limit: filters.limit };
  }

  async submitGrantApplication(vendorId: string, data: any) {
    const vendor = await prisma.vendorProfile.findUnique({
      where: { id: vendorId }
    });

    if (!vendor) {
      throw new AppError('Vendor not found', 404);
    }

    // Check eligibility (75% compliance score, no outstanding fines)
    if (vendor.compliance_score < 75) {
      throw new AppError('Compliance score below 75% - not eligible for grant', 400);
    }

    if (Number(vendor.fine_balance_cents) > 0) {
      throw new AppError('Outstanding fines must be paid before applying for grant', 400);
    }

    // Get current month cycle
    const now = new Date();
    const cycleMonth = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;

    // Check if already applied this month
    const existing = await prisma.grantApplication.findFirst({
      where: {
        vendor_id: vendorId,
        cycle_month: cycleMonth
      }
    });

    if (existing) {
      throw new AppError('Already applied for grant this cycle', 400);
    }

    const application = await prisma.grantApplication.create({
      data: {
        vendor_id: vendorId,
        cycle_month: cycleMonth,
        business_plan_text: data.business_plan_text,
        requested_amount_cents: toCents(Number(data.requested_amount)),
        status: 'submitted'
      }
    });

    return application;
  }

  async getGrantApplications(filters: any) {
    const where: any = {};

    if (filters.status) {
      where.status = filters.status;
    }

    if (filters.cycle_month) {
      where.cycle_month = filters.cycle_month;
    }

    if (filters.vendor_id) {
      where.vendor_id = filters.vendor_id;
    }

    const applications = await prisma.grantApplication.findMany({
      where,
      orderBy: { created_at: 'desc' },
      skip: (filters.page - 1) * filters.limit,
      take: filters.limit,
      include: {
        vendor: {
          select: {
            business_name: true,
            compliance_score: true,
            user: { select: { phone: true } }
          }
        }
      }
    });

    const total = await prisma.grantApplication.count({ where });

    return { applications, total, page: filters.page, limit: filters.limit };
  }

  async approveGrant(applicationId: string, adminId: string, data: any) {
    const application = await prisma.grantApplication.findUnique({
      where: { id: applicationId },
      include: {
        vendor: { select: { mpesa_number: true, business_name: true } }
      }
    });

    if (!application) {
      throw new AppError('Application not found', 404);
    }

    if (application.status !== 'submitted') {
      throw new AppError('Application already processed', 400);
    }

    // Get current fund balance
    const fundBalance = await this.getFundBalance();

    if (fundBalance.balance < Number(data.amount)) {
      throw new AppError('Insufficient fund balance', 400);
    }

    // Initiate B2C payout
    try {
      const b2cResponse = await mpesaService.initiateB2CPayout(
        application.vendor.mpesa_number,
        Number(data.amount),
        `ADDPlus+ Grant - ${application.cycle_month}`,
        'GrantPayout'
      );

      // Update application
      const updated = await prisma.grantApplication.update({
        where: { id: applicationId },
        data: {
          status: 'disbursed',
          amount_approved_cents: toCents(Number(data.amount)),
          disbursement_mpesa_ref: b2cResponse.conversationID,
          equity_stake_pct: data.equity_stake_pct || null,
          admin_notes: data.notes
        }
      });

      // Record disbursement in fund ledger
      await prisma.collectiveFund.create({
        data: {
          vendor_id: application.vendor_id,
          amount_cents: toCents(Number(data.amount)),
          type: 'disbursement',
          grant_id: applicationId,
          notes: `Grant disbursement for ${application.cycle_month}`
        }
      });

      return updated;
    } catch (error) {
      // Mark as approved but disbursement pending retry
      const updated = await prisma.grantApplication.update({
        where: { id: applicationId },
        data: {
          status: 'approved',
          amount_approved_cents: toCents(Number(data.amount)),
          equity_stake_pct: data.equity_stake_pct || null,
          admin_notes: `Payout failed, needs retry: ${data.notes}`
        }
      });

      return updated;
    }
  }

  async rejectGrant(applicationId: string, adminId: string, reason: string) {
    const application = await prisma.grantApplication.findUnique({
      where: { id: applicationId }
    });

    if (!application) {
      throw new AppError('Application not found', 404);
    }

    if (application.status !== 'submitted') {
      throw new AppError('Application already processed', 400);
    }

    const updated = await prisma.grantApplication.update({
      where: { id: applicationId },
      data: {
        status: 'rejected',
        admin_notes: reason
      }
    });

    return updated;
  }

  async selectTopGrantsForMonth(cycleMonth: string, count: number = 2) {
    // Get pending applications for the cycle
    const pending = await prisma.grantApplication.findMany({
      where: {
        cycle_month: cycleMonth,
        status: 'submitted'
      },
      include: {
        vendor: {
          select: {
            compliance_score: true,
            created_at: true,
            business_name: true
          }
        }
      }
    });

    // Score applications: compliance * 0.6 + recency * 0.4
    // Newer vendors get a bonus
    const scored = pending.map((app: any) => {
      const vendorAge = Date.now() - app.vendor.created_at.getTime();
      const monthsOld = vendorAge / (30 * 24 * 60 * 60 * 1000);
      const recencyScore = Math.max(0, 1 - monthsOld / 12); // Bonus for first year

      const score = app.vendor.compliance_score * 0.6 + recencyScore * 40;

      return { ...app, calculated_score: score };
    });

    // Sort by score descending
    scored.sort((a: any, b: any) => b.calculated_score - a.calculated_score);

    return scored.slice(0, count);
  }
}

import prisma from '../config/prisma'
import { AppError } from '../middleware/errorHandler'
import { toCents } from '../lib/money'
import { stringifyJsonArray, stringifyJsonObject } from '../lib/jsonFields'
import { serializeProduct } from '../lib/serialize'
import { logActivity } from './activityLogService'
import { inventoryService } from './inventoryService'
import { v2 as cloudinary } from 'cloudinary'

if (
  process.env.CLOUDINARY_CLOUD_NAME &&
  process.env.CLOUDINARY_API_KEY &&
  process.env.CLOUDINARY_API_SECRET &&
  !process.env.CLOUDINARY_CLOUD_NAME.startsWith('your-')
) {
  cloudinary.config({
    cloud_name: process.env.CLOUDINARY_CLOUD_NAME,
    api_key: process.env.CLOUDINARY_API_KEY,
    api_secret: process.env.CLOUDINARY_API_SECRET,
  })
}

const approvedPublic = { status: 'APPROVED', deleted_at: null }

export class ProductService {
  async createProduct(vendorId: string, data: any, actorId?: string) {
    const vendor = await prisma.vendorProfile.findUnique({ where: { id: vendorId } })
    if (!vendor) throw new AppError('Vendor not found', 404)
    if (vendor.is_suspended) throw new AppError('Vendor account is suspended', 403)

    const category = await prisma.category.findUnique({ where: { id: data.category_id } })
    if (!category) throw new AppError('Category not found', 400)

    const priceCents = data.price_cents ?? toCents(Number(data.price))
    const compareCents = data.compare_price != null ? toCents(Number(data.compare_price)) : null
    const stockQty = Number(data.stock_qty) || 0

    const product = await prisma.product.create({
      data: {
        vendor_id: vendorId,
        title: data.title,
        description: data.description,
        price_cents: priceCents,
        compare_price_cents: compareCents,
        category_id: data.category_id,
        images: stringifyJsonArray(data.images || []),
        variants: stringifyJsonObject(data.variants),
        stock_qty: 0,
        status: data.submit ? 'PENDING_REVIEW' : 'DRAFT',
        submitted_at: data.submit ? new Date() : null,
        reviewed_at: null,
        is_featured: data.is_featured === true,
        importation_flag: data.importation_flag === true,
      },
    })

    if (stockQty > 0) {
      await inventoryService.recordMovement({
        productId: product.id,
        type: 'quantity_added',
        quantity: stockQty,
        actorId,
        notes: 'Initial stock',
      })
    }

    if (actorId) {
      await logActivity({
        actorId,
        actorRole: 'vendor',
        action: 'product.created',
        entityType: 'product',
        entityId: product.id,
        metadata: { title: product.title },
      })
    }

    return serializeProduct(await prisma.product.findUnique({ where: { id: product.id } }))
  }

  async updateProduct(productId: string, vendorId: string, data: any, actorId?: string) {
    const product = await prisma.product.findFirst({ where: { id: productId, vendor_id: vendorId } })
    if (!product) throw new AppError('Product not found or unauthorized', 404)

    const updated = await prisma.product.update({
      where: { id: productId },
      data: {
        title: data.title,
        description: data.description,
        price_cents: data.price != null ? toCents(Number(data.price)) : undefined,
        compare_price_cents: data.compare_price != null ? toCents(Number(data.compare_price)) : undefined,
        category_id: data.category_id,
        images: data.images ? stringifyJsonArray(data.images) : undefined,
        variants: data.variants != null ? stringifyJsonObject(data.variants) : undefined,
        is_featured: data.is_featured,
        importation_flag: data.importation_flag,
        status: data.submit ? 'PENDING_REVIEW' : undefined,
        submitted_at: data.submit ? new Date() : undefined,
      },
    })

    if (actorId) {
      await logActivity({
        actorId,
        actorRole: 'vendor',
        action: 'product.updated',
        entityType: 'product',
        entityId: productId,
      })
    }

    return serializeProduct(updated)
  }

  async deleteProduct(productId: string, vendorId: string, actorId?: string) {
    const product = await prisma.product.findFirst({ where: { id: productId, vendor_id: vendorId } })
    if (!product) throw new AppError('Product not found or unauthorized', 404)

    await prisma.product.update({
      where: { id: productId },
      data: { deleted_at: new Date(), status: 'ARCHIVED' },
    })

    if (actorId) {
      await logActivity({
        actorId,
        actorRole: 'vendor',
        action: 'product.deleted',
        entityType: 'product',
        entityId: productId,
      })
    }

    return { message: 'Product deleted successfully' }
  }

  async moderateProduct(productId: string, adminId: string, action: 'approve' | 'reject', reason?: string) {
    const status = action === 'approve' ? 'APPROVED' : 'REJECTED'
    const updated = await prisma.product.update({
      where: { id: productId },
      data: {
        status,
        reviewed_at: new Date(),
        reviewed_by: adminId,
        rejection_reason: action === 'reject' ? reason : null,
      },
    })

    await logActivity({
      actorId: adminId,
      actorRole: 'admin',
      action: `product.${action}d`,
      entityType: 'product',
      entityId: productId,
      metadata: { reason },
    })

    return serializeProduct(updated)
  }

  async getProductById(productId: string, includeDraft = false) {
    const product = await prisma.product.findFirst({
      where: {
        id: productId,
        deleted_at: null,
        ...(includeDraft ? {} : approvedPublic),
      },
      include: {
        vendor: { select: { id: true, business_name: true, referral_code: true, kyc_status: true } },
        category: true,
      },
    })

    if (!product) throw new AppError('Product not found', 404)

    await prisma.product.update({ where: { id: productId }, data: { views_count: { increment: 1 } } })
    return serializeProduct(product)
  }

  async listProducts(filters: any) {
    const where: any = {
      deleted_at: null,
      vendor: { kyc_status: 'approved', is_suspended: false },
    }

    if (filters.vendor_id) {
      where.vendor_id = filters.vendor_id
      if (!filters.include_drafts) where.status = filters.status || 'APPROVED'
    } else {
      where.status = 'APPROVED'
    }

    if (filters.category_id) where.category_id = filters.category_id
    if (filters.min_price != null) where.price_cents = { ...(where.price_cents || {}), gte: toCents(Number(filters.min_price)) }
    if (filters.max_price != null) where.price_cents = { ...(where.price_cents || {}), lte: toCents(Number(filters.max_price)) }
    if (filters.search) {
      where.OR = [
        { title: { contains: filters.search } },
        { description: { contains: filters.search } },
      ]
    }

    const orderBy: any =
      filters.sort_by === 'price_asc' ? { price_cents: 'asc' }
      : filters.sort_by === 'price_desc' ? { price_cents: 'desc' }
      : filters.sort_by === 'popular' ? { sales_count: 'desc' }
      : { created_at: 'desc' }

    const products = await prisma.product.findMany({
      where,
      include: {
        vendor: { select: { id: true, business_name: true, referral_code: true } },
        category: { select: { id: true, name: true, slug: true } },
      },
      orderBy,
      skip: (filters.page - 1) * filters.limit,
      take: filters.limit,
    })

    const total = await prisma.product.count({ where })
    return {
      products: products.map(serializeProduct),
      total,
      page: filters.page,
      limit: filters.limit,
    }
  }

  async getFeaturedProducts(limit = 10) {
    const products = await prisma.product.findMany({
      where: { ...approvedPublic, is_featured: true, vendor: { kyc_status: 'approved', is_suspended: false } },
      include: { vendor: { select: { id: true, business_name: true } } },
      orderBy: { created_at: 'desc' },
      take: limit,
    })
    return products.map(serializeProduct)
  }

  async getNewArrivals(limit = 20) {
    const products = await prisma.product.findMany({
      where: { ...approvedPublic, vendor: { kyc_status: 'approved', is_suspended: false } },
      include: { vendor: { select: { id: true, business_name: true } } },
      orderBy: { created_at: 'desc' },
      take: limit,
    })
    return products.map(serializeProduct)
  }

  async getTrendingProducts(limit = 20) {
    const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000)
    const products = await prisma.product.findMany({
      where: { ...approvedPublic, updated_at: { gte: sevenDaysAgo }, vendor: { kyc_status: 'approved', is_suspended: false } },
      include: { vendor: { select: { id: true, business_name: true } } },
      orderBy: [{ views_count: 'desc' }, { sales_count: 'desc' }],
      take: limit,
    })
    return products.map(serializeProduct)
  }

  async getRelatedProducts(productId: string, limit = 8) {
    const product = await prisma.product.findUnique({ where: { id: productId } })
    if (!product) throw new AppError('Product not found', 404)

    const related = await prisma.product.findMany({
      where: {
        id: { not: productId },
        category_id: product.category_id,
        ...approvedPublic,
        vendor: { kyc_status: 'approved', is_suspended: false },
      },
      include: { vendor: { select: { id: true, business_name: true } } },
      orderBy: { sales_count: 'desc' },
      take: limit,
    })
    return related.map(serializeProduct)
  }

  async getCategories() {
    return prisma.category.findMany({
      where: { is_active: true },
      include: {
        children: { where: { is_active: true }, select: { id: true, name: true, slug: true } },
        _count: { select: { products: { where: { status: 'APPROVED', deleted_at: null } } } },
      },
      orderBy: { sort_order: 'asc' },
    })
  }

  async uploadImage(fileBuffer: Buffer): Promise<string> {
    return new Promise((resolve, reject) => {
      cloudinary.uploader.upload_stream(
        { folder: 'addplus/products', transformation: [{ width: 800, height: 800, crop: 'limit' }, { quality: 'auto:good' }] },
        (error, result) => {
          if (error) reject(error)
          else resolve(result?.secure_url || '')
        }
      ).end(fileBuffer)
    })
  }
}

import prisma from '../config/prisma'
import { AppError } from '../middleware/errorHandler'

const deltaForType = (type: string, quantity: number): number => {
  switch (type) {
    case 'quantity_added':
    case 'returned':
      return quantity
    case 'quantity_removed':
    case 'sold':
      return -quantity
    case 'adjustment':
      return quantity
    default:
      return quantity
  }
}

export class InventoryService {
  async recordMovement(params: {
    productId: string
    type: string
    quantity: number
    actorId?: string
    orderId?: string
    notes?: string
  }) {
    if (params.quantity <= 0) throw new AppError('Quantity must be positive', 400)

    const delta = deltaForType(params.type, params.quantity)

    return prisma.$transaction(async (tx) => {
      const product = await tx.product.findUnique({ where: { id: params.productId } })
      if (!product) throw new AppError('Product not found', 404)

      const nextQty = product.stock_qty + delta
      if (nextQty < 0) throw new AppError('Insufficient stock', 400)

      const movement = await tx.inventoryMovement.create({
        data: {
          product_id: params.productId,
          type: params.type,
          quantity: params.quantity,
          actor_id: params.actorId,
          order_id: params.orderId,
          notes: params.notes,
        },
      })

      await tx.product.update({
        where: { id: params.productId },
        data: { stock_qty: nextQty },
      })

      return movement
    })
  }
}

export const inventoryService = new InventoryService()

