/**
 * Applies idempotent schema patches to Turso when Prisma migrate deploy
 * only targets the local SQLite file in schema.prisma.
 */
import { createClient } from '@libsql/client';

const PATCHES = [
  'ALTER TABLE users ADD COLUMN email_verified_at DATETIME',
  'ALTER TABLE users ADD COLUMN email_verification_token TEXT',
  'ALTER TABLE users ADD COLUMN email_verification_code TEXT',
  'ALTER TABLE users ADD COLUMN email_verification_expires DATETIME',
  'ALTER TABLE users ADD COLUMN password_reset_token TEXT',
  'ALTER TABLE users ADD COLUMN password_reset_expires DATETIME',
  'CREATE UNIQUE INDEX IF NOT EXISTS users_email_key ON users(email)',
];

export async function ensureTursoSchema(): Promise<void> {
  const url = process.env.TURSO_DATABASE_URL;
  if (!url || !url.startsWith('libsql://')) return;

  const client = createClient({
    url,
    authToken: process.env.DATABASE_AUTH_TOKEN || undefined,
  });

  for (const sql of PATCHES) {
    try {
      await client.execute(sql);
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : String(error);
      if (message.includes('duplicate column') || message.includes('already exists')) {
        continue;
      }
      console.warn('[schema] patch skipped or failed:', sql, message);
    }
  }
}

