8	// ─── H2: Escrow Auto-Release ──────────────────────────────────────────────────
9	// Runs every 30 minutes. Releases escrow for order items where auto_release_at
10	// has passed, no active dispute exists, and status is still 'held'.
11	export const startEscrowAutoRelease = () => {
12	  cron.schedule('*/30 * * * *', async () => {
13	    try {
14	      const now = new Date();
15	
16	      const overdueItems = await prisma.orderItem.findMany({
17	        where: {
18	          vendor_escrow_status: 'held',
19	          auto_release_at: { lte: now },
20	          dispute: null,
21	        },
22	        include: {
23	          escrow_entry: true,
24	          vendor: { select: { id: true, mpesa_number: true, fine_balance_cents: true } },
25	        },
26	      });
27	
28	      if (overdueItems.length === 0) return;
29	      console.log(`[Escrow Cron] Auto-releasing ${overdueItems.length} item(s)`);
30	
31	      for (const item of overdueItems) {
32	        try {
33	          let netPayoutCents = item.escrow_entry ? Number(item.escrow_entry.net_amount_cents) : 0;
34	          let fineDeductionCents = 0;
35	
36	          if (item.vendor && Number(item.vendor.fine_balance_cents) > 0) {
37	            fineDeductionCents = Math.min(Number(item.vendor.fine_balance_cents), netPayoutCents);
38	            netPayoutCents -= fineDeductionCents;
39	
40	            await prisma.vendorProfile.update({
41	              where: { id: item.vendor_id },
42	              data: { fine_balance_cents: { decrement: fineDeductionCents } },
43	            });
44	          }
45	
46	          await prisma.orderItem.update({
47	            where: { id: item.id },
48	            data: {
49	              vendor_escrow_status: 'released',
50	              delivery_confirmed_at: now,
51	            },
52	          });
53	
54	          if (item.escrow_entry) {
55	            await prisma.escrowLedger.update({
56	              where: { id: item.escrow_entry.id },
57	              data: {
58	                status: 'released',
59	                released_at: now,
60	                fine_deduction_cents: fineDeductionCents,
61	              },
62	            });
63	          }
64	
65	          if (netPayoutCents > 0 && item.vendor?.mpesa_number) {
66	            try {
67	              await mpesaService.initiateB2CPayout(
68	                item.vendor.mpesa_number,
69	                fromCents(netPayoutCents),
