89	// ─── H3: Daily Compliance Scoring ────────────────────────────────────────────
90	// Runs at 23:55 every day. Scores each active vendor for the current day:
91	// checks post count, referral shares, profile post. Issues fines if below threshold.
92	export const startComplianceScoring = () => {
