import cron from 'node-cron';
import prisma from '../config/prisma';
import { fromCents, toCents } from '../lib/money';
import { MPesaService } from '../services/mpesaService';

const mpesaService = new MPesaService();

// ─── H2: Escrow Auto-Release ──────────────────────────────────────────────────
// Runs every 30 minutes. Releases escrow for order items where auto_release_at
// has passed, no active dispute exists, and status is still 'held'.
export const startEscrowAutoRelease = () => {
  cron.schedule('*/30 * * * *', async () => {
    try {
      const now = new Date();

      const overdueItems = await prisma.orderItem.findMany({
        where: {
          vendor_escrow_status: 'held',
          auto_release_at: { lte: now },
          dispute: null,
        },
        include: {
          escrow_entry: true,
          vendor: { select: { id: true, mpesa_number: true, fine_balance_cents: true } },
        },
      });

      if (overdueItems.length === 0) return;
      console.log(`[Escrow Cron] Auto-releasing ${overdueItems.length} item(s)`);

      for (const item of overdueItems) {
        try {
          let netPayoutCents = item.escrow_entry ? Number(item.escrow_entry.net_amount_cents) : 0;
          let fineDeductionCents = 0;

          if (item.vendor && Number(item.vendor.fine_balance_cents) > 0) {
            fineDeductionCents = Math.min(Number(item.vendor.fine_balance_cents), netPayoutCents);
            netPayoutCents -= fineDeductionCents;

            await prisma.vendorProfile.update({
              where: { id: item.vendor_id },
              data: { fine_balance_cents: { decrement: fineDeductionCents } },
            });
          }

          await prisma.orderItem.update({
            where: { id: item.id },
            data: {
              vendor_escrow_status: 'released',
              delivery_confirmed_at: now,
            },
          });

          if (item.escrow_entry) {
            await prisma.escrowLedger.update({
              where: { id: item.escrow_entry.id },
              data: {
                status: 'released',
                released_at: now,
                fine_deduction_cents: fineDeductionCents,
              },
            });
          }

          if (netPayoutCents > 0 && item.vendor?.mpesa_number) {
            try {
              await mpesaService.initiateB2CPayout(
                item.vendor.mpesa_number,
                fromCents(netPayoutCents),
                item.id,
                'AutoRelease'
              );
            } catch (payoutErr: any) {
              console.error(`[Escrow Cron] B2C payout failed for item ${item.id}:`, payoutErr.message);
            }
          }
        } catch (itemErr: any) {
          console.error(`[Escrow Cron] Failed to release item ${item.id}:`, itemErr.message);
        }
      }
    } catch (err: any) {
      console.error('[Escrow Cron] Error:', err.message);
    }
  });

  console.log('[Cron] Escrow auto-release scheduled (every 30 min)');
};

// ─── H3: Daily Compliance Scoring ────────────────────────────────────────────
// Runs at 23:55 every day. Scores each active vendor for the current day:
// checks post count, referral shares, profile post. Issues fines if below threshold.
export const startComplianceScoring = () => {
  cron.schedule('55 23 * * *', async () => {
    try {
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      const vendors = await prisma.vendorProfile.findMany({
        where: { is_suspended: false, kyc_status: 'approved' },
        select: { id: true, compliance_score: true },
      });

      console.log(`[Compliance Cron] Scoring ${vendors.length} vendor(s) for ${today.toDateString()}`);

      const POSTS_REQUIRED = 5;
      const REFERRALS_REQUIRED = 3;

      for (const vendor of vendors) {
        try {
          const [postsMade, referralsMade, profilePost] = await Promise.all([
            prisma.vendorPost.count({
              where: {
                vendor_id: vendor.id,
                post_type: 'product',
                created_at: { gte: today },
              },
            }),
            prisma.referralShare.count({
              where: {
                vendor_id: vendor.id,
                created_at: { gte: today },
              },
            }),
            prisma.vendorPost.count({
              where: {
                vendor_id: vendor.id,
                post_type: 'profile',
                created_at: { gte: today },
              },
            }),
          ]);

          const postScore = Math.min((postsMade / POSTS_REQUIRED) * 60, 60);
          const referralScore = Math.min((referralsMade / REFERRALS_REQUIRED) * 30, 30);
          const profileScore = profilePost > 0 ? 10 : 0;
          const score = postScore + referralScore + profileScore;

          const fineAmountCents = score < 60 ? toCents(score < 30 ? 500 : 200) : 0;

          await prisma.complianceLog.upsert({
            where: { vendor_id_log_date: { vendor_id: vendor.id, log_date: today } },
            create: {
              vendor_id: vendor.id,
              log_date: today,
              posts_made: postsMade,
              posts_required: POSTS_REQUIRED,
              referrals_shared: referralsMade,
              referrals_required: REFERRALS_REQUIRED,
              profile_post_made: profilePost > 0,
              score,
              fine_issued_amount_cents: fineAmountCents,
            },
            update: {
              posts_made: postsMade,
              referrals_shared: referralsMade,
              profile_post_made: profilePost > 0,
              score,
              fine_issued_amount_cents: fineAmountCents,
            },
          });

          if (fineAmountCents > 0) {
            await prisma.vendorProfile.update({
              where: { id: vendor.id },
              data: { fine_balance_cents: { increment: fineAmountCents } },
            });

            await prisma.fineLedger.create({
              data: {
                vendor_id: vendor.id,
                amount_cents: fineAmountCents,
                reason: `Daily compliance score ${score.toFixed(1)}/100 — below threshold`,
                rule_violated: 'daily_posting_requirement',
                strike_level: score < 30 ? 2 : 1,
              },
            });

            await prisma.collectiveFund.create({
              data: {
                vendor_id: vendor.id,
                amount_cents: fineAmountCents,
                type: 'fine_revenue',
                notes: `Compliance fine — ${today.toISOString().split('T')[0]}`,
              },
            });
          }

          // Update rolling 7-day compliance score on vendor profile
          const sevenDaysAgo = new Date(today.getTime() - 7 * 24 * 60 * 60 * 1000);
          const recentLogs = await prisma.complianceLog.findMany({
            where: { vendor_id: vendor.id, log_date: { gte: sevenDaysAgo } },
            select: { score: true },
          });
          const avgScore =
            recentLogs.length > 0
              ? recentLogs.reduce((sum: number, l: any) => sum + l.score, 0) / recentLogs.length
              : 0;

          await prisma.vendorProfile.update({
            where: { id: vendor.id },
            data: { compliance_score: avgScore },
          });
        } catch (vendorErr: any) {
          console.error(`[Compliance Cron] Failed for vendor ${vendor.id}:`, vendorErr.message);
        }
      }

      console.log('[Compliance Cron] Daily scoring complete');
    } catch (err: any) {
      console.error('[Compliance Cron] Error:', err.message);
    }
  });

  console.log('[Cron] Daily compliance scoring scheduled (23:55 daily)');
};

// ─── H4: Weekly Profit-Share Distribution ────────────────────────────────────
// Runs every Monday at 06:00. Distributes accumulated profit-share fund entries
// to qualifying vendors proportionally based on their sales in the past week.
export const startProfitShareDistribution = () => {
  cron.schedule('0 6 * * 1', async () => {
    try {
      const now = new Date();
      const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

      // Total undistributed profit-share pot
      const pot = await prisma.collectiveFund.aggregate({
        where: { type: 'profit_share_contribution', grant_id: null },
        _sum: { amount_cents: true },
      });

      const totalPot = Number(pot._sum.amount_cents || 0);
      if (totalPot <= 0) {
        console.log('[ProfitShare Cron] No funds to distribute');
        return;
      }

      // Get released escrow totals per vendor for the past week
      const vendorSales = await prisma.escrowLedger.groupBy({
        by: ['vendor_id'],
        where: {
          status: 'released',
          released_at: { gte: weekAgo },
        },
        _sum: { gross_amount_cents: true },
      });

      const totalSales = vendorSales.reduce(
        (sum: number, v: any) => sum + Number(v._sum.gross_amount_cents || 0),
        0
      );

      if (totalSales === 0) {
        console.log('[ProfitShare Cron] No sales this week — skipping distribution');
        return;
      }

      console.log(
        `[ProfitShare Cron] Distributing KES ${totalPot.toFixed(2)} across ${vendorSales.length} vendor(s)`
      );

      for (const vendorSale of vendorSales) {
        const shareCents = Math.round(
          (Number(vendorSale._sum.gross_amount_cents || 0) / totalSales) * totalPot
        );
        if (shareCents < toCents(10)) continue;

        const vendor = await prisma.vendorProfile.findUnique({
          where: { id: vendorSale.vendor_id },
          select: { mpesa_number: true },
        });

        if (!vendor?.mpesa_number) continue;

        try {
          await mpesaService.initiateB2CPayout(
            vendor.mpesa_number,
            fromCents(shareCents),
            `profit-share-${vendorSale.vendor_id}-${now.toISOString().split('T')[0]}`,
            'ProfitShare'
          );

          await prisma.collectiveFund.create({
            data: {
              vendor_id: vendorSale.vendor_id,
              amount_cents: -shareCents,
              type: 'disbursement',
              notes: `Weekly profit-share payout — ${now.toISOString().split('T')[0]}`,
            },
          });
        } catch (payoutErr: any) {
          console.error(
            `[ProfitShare Cron] Payout failed for vendor ${vendorSale.vendor_id}:`,
            payoutErr.message
          );
        }
      }

      console.log('[ProfitShare Cron] Weekly distribution complete');
    } catch (err: any) {
      console.error('[ProfitShare Cron] Error:', err.message);
    }
  });

  console.log('[Cron] Weekly profit-share distribution scheduled (Monday 06:00)');
};

// ─── Start all cron jobs ──────────────────────────────────────────────────────
export const startAllCronJobs = () => {
  startEscrowAutoRelease();
  startComplianceScoring();
  startProfitShareDistribution();
  console.log('[Cron] All jobs registered');
};

