1	/**
2	 * Security Utilities
3	 * Centralized security functions for input sanitization, validation, and threat detection
4	 */
5	
6	import crypto from 'crypto';
7	import { Request, Response, NextFunction } from 'express';
8	import { securityLog } from './requestLogger';
9	
10	// Security: SQL Injection pattern detection
11	const SQL_INJECTION_PATTERNS = [
12	  /(\b(SELECT|INSERT|UPDATE|DELETE|DROP|CREATE|ALTER|EXEC|EXECUTE)\b)/i,
13	  /(\b(OR|AND)\b.*=.*)/i,
14	  /(--|;|\/\*|\*\/)/,
15	  /(\bUNION\b.*\bSELECT\b)/i,
16	  /(\bSLEEP\s*\()/i,
17	  /(\bBENCHMARK\s*\()/i
18	];
19	
20	// Security: XSS pattern detection
21	const XSS_PATTERNS = [
22	  /<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi,
23	  /javascript:/gi,
24	  /on\w+\s*=/gi,  // onclick, onload, etc.
25	  /<iframe/gi,
26	  /<object/gi,
27	  /<embed/gi
28	];
29	
30	// Security: Command injection patterns
31	const COMMAND_INJECTION_PATTERNS = [
32	  /[;&|`$]/,
33	  /\$\(/,
34	  /`.*`/,
35	  /\|\|/,
36	  /&&/
37	];
38	
39	// NoSQL injection patterns removed — ADDPlus+ uses PostgreSQL via Prisma (parameterized queries).
40	// These MongoDB-specific patterns ($or, $and, $in etc.) incorrectly block legitimate product
41	// descriptions, search queries, and filter parameters. (Bug H8 fix)
42	const NOSQL_INJECTION_PATTERNS: RegExp[] = [];
43	
44	// Security: Detect potential threats in input
45	export const detectThreats = (input: string): { type: string; pattern: string }[] => {
46	  const threats: { type: string; pattern: string }[] = [];
47	
48	  // Check SQL injection
49	  SQL_INJECTION_PATTERNS.forEach((pattern, index) => {
50	    if (pattern.test(input)) {
51	      threats.push({ type: 'SQL_INJECTION', pattern: `Pattern ${index + 1}` });
52	    }
53	  });
54	
55	  // Check XSS
56	  XSS_PATTERNS.forEach((pattern, index) => {
57	    if (pattern.test(input)) {
58	      threats.push({ type: 'XSS', pattern: `Pattern ${index + 1}` });
59	    }
60	  });
61	
62	  // Check Command Injection
63	  COMMAND_INJECTION_PATTERNS.forEach((pattern, index) => {
64	    if (pattern.test(input)) {
65	      threats.push({ type: 'COMMAND_INJECTION', pattern: `Pattern ${index + 1}` });
66	    }
67	  });
68	
69	  return threats;
70	};
71	
72	// Security: Sanitize string input
73	export const sanitizeString = (input: string): string => {
74	  if (typeof input !== 'string') return input;
75	  
76	  return input
77	    .replace(/[<>]/g, '') // Remove < and > to prevent HTML tags
78	    .replace(/["']/g, '') // Remove quotes
79	    .trim()
80	    .substring(0, 1000); // Limit length
81	};
82	
83	// Security: Deep sanitize object
84	export const sanitizeObject = (obj: any): any => {
85	  if (typeof obj === 'string') {
86	    return sanitizeString(obj);
87	  }
88	  if (Array.isArray(obj)) {
89	    return obj.map(sanitizeObject);
90	  }
91	  if (obj && typeof obj === 'object') {
92	    const sanitized: any = {};
93	    for (const key in obj) {
94	      if (obj.hasOwnProperty(key)) {
95	        // Sanitize keys too
96	        const sanitizedKey = sanitizeString(key);
97	        sanitized[sanitizedKey] = sanitizeObject(obj[key]);
98	      }
99	    }
100	    return sanitized;
101	  }
102	  return obj;
103	};
104	
105	// Security: Input validation middleware
106	export const validateInput = (req: Request, res: Response, next: NextFunction) => {
107	  // Check all input sources
108	  const inputs = [
109	    JSON.stringify(req.body),
110	    JSON.stringify(req.query),
111	    JSON.stringify(req.params)
112	  ].join(' ');
113	
114	  const threats = detectThreats(inputs);
115	  
116	  if (threats.length > 0) {
117	    // Security: Log input violation using structured audit format
118	    securityLog('input_violation', req, { threats: threats.map(t => t.type) });
119	    
120	    return res.status(400).json({
121	      error: 'Invalid input detected',
122	      requestId: (req as any).requestId || `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`
123	    });
124	  }
125	
126	  // Sanitize inputs
127	  req.body = sanitizeObject(req.body);
128	  req.query = sanitizeObject(req.query);
129	  
130	  next();
131	};
132	
133	// Security: File upload validation
134	export const validateFileUpload = (allowedTypes: string[], maxSizeMB: number) => {
135	  return (req: Request & { file?: any; files?: any }, res: Response, next: NextFunction) => {
136	    if (!req.file && !req.files) {
137	      return next();
138	    }
139	
140	    const files: any[] = req.files ? (Array.isArray(req.files) ? req.files : Object.values(req.files).flat()) : [req.file];
141	    const maxSize = maxSizeMB * 1024 * 1024;
142	
143	    for (const file of files) {
144	      // Check file size
145	      if (file.size > maxSize) {
146	        return res.status(400).json({
147	          error: `File too large. Maximum size is ${maxSizeMB}MB`
148	        });
149	      }
150	
151	      // Validate MIME type (not just extension)
152	      if (!allowedTypes.includes(file.mimetype)) {
153	        return res.status(400).json({
154	          error: `Invalid file type. Allowed types: ${allowedTypes.join(', ')}`
155	        });
156	      }
157	
158	      // Check for double extensions (security risk)
159	      const filename = file.originalname || file.name;
160	      if (filename.split('.').length > 2) {
161	        return res.status(400).json({
162	          error: 'Invalid filename format'
163	        });
164	      }
165	
166	      // Check for executable extensions
167	      const dangerousExtensions = ['.exe', '.bat', '.cmd', '.sh', '.php', '.jsp', '.asp'];
168	      const ext = filename.toLowerCase().substring(filename.lastIndexOf('.'));
169	      if (dangerousExtensions.includes(ext)) {
170	        return res.status(400).json({
171	          error: 'Executable files are not allowed'
172	        });
173	      }
174	    }
175	
176	    next();
177	  };
178	};
179	
180	// Security: Request size validation
181	export const validateRequestSize = (maxSizeMB: number) => {
182	  return (req: Request, res: Response, next: NextFunction) => {
183	    const contentLength = parseInt(req.get('content-length') || '0', 10);
184	    const maxSize = maxSizeMB * 1024 * 1024;
185	
186	    if (contentLength > maxSize) {
187	      return res.status(413).json({
188	        error: `Request entity too large. Maximum is ${maxSizeMB}MB`
189	      });
