/**
 * Security Utilities
 * Centralized security functions for input sanitization, validation, and threat detection
 */

import crypto from 'crypto';
import { Request, Response, NextFunction } from 'express';
import { securityLog } from './requestLogger';

// Security: SQL Injection pattern detection
const SQL_INJECTION_PATTERNS = [
  /(\b(SELECT|INSERT|UPDATE|DELETE|DROP|CREATE|ALTER|EXEC|EXECUTE)\b)/i,
  /(\b(OR|AND)\b.*=.*)/i,
  /(--|;|\/\*|\*\/)/,
  /(\bUNION\b.*\bSELECT\b)/i,
  /(\bSLEEP\s*\()/i,
  /(\bBENCHMARK\s*\()/i
];

// Security: XSS pattern detection
const XSS_PATTERNS = [
  /<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi,
  /javascript:/gi,
  /on\w+\s*=/gi,  // onclick, onload, etc.
  /<iframe/gi,
  /<object/gi,
  /<embed/gi
];

// Security: Command injection patterns
const COMMAND_INJECTION_PATTERNS = [
  /[;&|`$]/,
  /\$\(/,
  /`.*`/,
  /\|\|/,
  /&&/
];

// NoSQL injection patterns removed — ADDPlus+ uses PostgreSQL via Prisma (parameterized queries).
// These MongoDB-specific patterns ($or, $and, $in etc.) incorrectly block legitimate product
// descriptions, search queries, and filter parameters. (Bug H8 fix)
const NOSQL_INJECTION_PATTERNS: RegExp[] = [];

// Security: Detect potential threats in input
export const detectThreats = (input: string): { type: string; pattern: string }[] => {
  const threats: { type: string; pattern: string }[] = [];

  // Check SQL injection
  SQL_INJECTION_PATTERNS.forEach((pattern, index) => {
    if (pattern.test(input)) {
      threats.push({ type: 'SQL_INJECTION', pattern: `Pattern ${index + 1}` });
    }
  });

  // Check XSS
  XSS_PATTERNS.forEach((pattern, index) => {
    if (pattern.test(input)) {
      threats.push({ type: 'XSS', pattern: `Pattern ${index + 1}` });
    }
  });

  // Check Command Injection
  COMMAND_INJECTION_PATTERNS.forEach((pattern, index) => {
    if (pattern.test(input)) {
      threats.push({ type: 'COMMAND_INJECTION', pattern: `Pattern ${index + 1}` });
    }
  });

  return threats;
};

// Security: Sanitize string input
export const sanitizeString = (input: string): string => {
  if (typeof input !== 'string') return input;

  return input
    .replace(/[<>]/g, '') // Remove < and > to prevent HTML tags
    .replace(/["']/g, '') // Remove quotes
    .trim()
    .substring(0, 1000); // Limit length
};

// Security: Deep sanitize object
export const sanitizeObject = (obj: any): any => {
  if (typeof obj === 'string') {
    return sanitizeString(obj);
  }
  if (Array.isArray(obj)) {
    return obj.map(sanitizeObject);
  }
  if (obj && typeof obj === 'object') {
    const sanitized: any = {};
    for (const key in obj) {
      if (obj.hasOwnProperty(key)) {
        // Sanitize keys too
        const sanitizedKey = sanitizeString(key);
        sanitized[sanitizedKey] = sanitizeObject(obj[key]);
      }
    }
    return sanitized;
  }
  return obj;
};

// Security: Input validation middleware
export const validateInput = (req: Request, res: Response, next: NextFunction) => {
  // Check all input sources
  const inputs = [
    JSON.stringify(req.body),
    JSON.stringify(req.query),
    JSON.stringify(req.params)
  ].join(' ');

  const threats = detectThreats(inputs);

  if (threats.length > 0) {
    // Security: Log input violation using structured audit format
    securityLog('input_violation', req, { threats: threats.map(t => t.type) });

    return res.status(400).json({
      error: 'Invalid input detected',
      requestId: (req as any).requestId || `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`
    });
  }

  // Sanitize inputs
  req.body = sanitizeObject(req.body);
  req.query = sanitizeObject(req.query);

  next();
};

// Security: File upload validation
export const validateFileUpload = (allowedTypes: string[], maxSizeMB: number) => {
  return (req: Request & { file?: any; files?: any }, res: Response, next: NextFunction) => {
    if (!req.file && !req.files) {
      return next();
    }

    const files: any[] = req.files ? (Array.isArray(req.files) ? req.files : Object.values(req.files).flat()) : [req.file];
    const maxSize = maxSizeMB * 1024 * 1024;

    for (const file of files) {
      // Check file size
      if (file.size > maxSize) {
        return res.status(400).json({
          error: `File too large. Maximum size is ${maxSizeMB}MB`
        });
      }

      // Validate MIME type (not just extension)
      if (!allowedTypes.includes(file.mimetype)) {
        return res.status(400).json({
          error: `Invalid file type. Allowed types: ${allowedTypes.join(', ')}`
        });
      }

      // Check for double extensions (security risk)
      const filename = file.originalname || file.name;
      if (filename.split('.').length > 2) {
        return res.status(400).json({
          error: 'Invalid filename format'
        });
      }

      // Check for executable extensions
      const dangerousExtensions = ['.exe', '.bat', '.cmd', '.sh', '.php', '.jsp', '.asp'];
      const ext = filename.toLowerCase().substring(filename.lastIndexOf('.'));
      if (dangerousExtensions.includes(ext)) {
        return res.status(400).json({
          error: 'Executable files are not allowed'
        });
      }
    }

    next();
  };
};

// Security: Request size validation
export const validateRequestSize = (maxSizeMB: number) => {
  return (req: Request, res: Response, next: NextFunction) => {
    const contentLength = parseInt(req.get('content-length') || '0', 10);
    const maxSize = maxSizeMB * 1024 * 1024;

    if (contentLength > maxSize) {
      return res.status(413).json({
        error: `Request entity too large. Maximum is ${maxSizeMB}MB`
      });
    }

    next();
  };
};

// Security: IP whitelist middleware (for admin routes)
export const ipWhitelist = (allowedIps: string[]) => {
  return (req: Request, res: Response, next: NextFunction) => {
    const clientIp = req.ip || req.connection.remoteAddress || '';

    if (!allowedIps.includes(clientIp)) {
      // Security: Log unauthorized access attempt using structured audit format
      securityLog('unauthorized_access', req, { 
        attemptedIp: clientIp,
        allowedIps 
      });

      return res.status(403).json({
        error: 'Access denied'
      });
    }

    next();
  };
};

// Security: Generate cryptographically secure random token
// CRITICAL FIX: Replaced Math.random() with crypto.randomBytes()
export const generateSecureToken = (length: number = 32): string => {
  return crypto.randomBytes(length).toString('hex').slice(0, length);
};

// Security: Password strength validation
export const validatePasswordStrength = (password: string): { valid: boolean; errors: string[] } => {
  const errors: string[] = [];

  if (password.length < 8) {
    errors.push('Password must be at least 8 characters long');
  }
  if (!/[A-Z]/.test(password)) {
    errors.push('Password must contain at least one uppercase letter');
  }
  if (!/[a-z]/.test(password)) {
    errors.push('Password must contain at least one lowercase letter');
  }
  if (!/[0-9]/.test(password)) {
    errors.push('Password must contain at least one number');
  }
  if (!/[!@#$%^&*(),.?":{}|<>]/.test(password)) {
    errors.push('Password must contain at least one special character');
  }

  return {
    valid: errors.length === 0,
    errors
  };
};

// Security: Phone number sanitization and validation
export const sanitizePhoneNumber = (phone: string): string => {
  // Remove all non-numeric characters
  return phone.replace(/\D/g, '');
};

export const validatePhoneNumber = (phone: string): boolean => {
  // Kenya format: 254 followed by 9 digits
  const kenyaPattern = /^254[0-9]{9}$/;
  return kenyaPattern.test(phone);
};

// Security: Request logging for audit trail
export const auditLog = (action: string, userId: string | null, details: any) => {
  console.log(JSON.stringify({
    type: 'AUDIT',
    timestamp: new Date().toISOString(),
    action,
    userId,
    details: sanitizeObject(details)
  }));
};

