import express from 'express';
import fs from 'fs';
import path from 'path';
import multer from 'multer';
import { authenticate, AuthRequest } from '../middleware/auth';
import { AppError } from '../middleware/errorHandler';
import { uploadImageBuffer } from '../lib/imageUpload';

const router = express.Router();

const upload = multer({
  storage: multer.memoryStorage(),
  limits: { fileSize: 10 * 1024 * 1024 },
  fileFilter: (_req, file, cb) => {
    if (!file.mimetype.startsWith('image/')) {
      return cb(new Error('Only image files are allowed'));
    }
    cb(null, true);
  },
});

router.get('/files/:folder/:filename', (req, res, next) => {
  try {
    const filePath = path.join(process.cwd(), 'uploads', req.params.folder, req.params.filename);
    if (!fs.existsSync(filePath)) throw new AppError('File not found', 404);
    res.sendFile(filePath);
  } catch (error) {
    next(error);
  }
});

router.post('/products', authenticate, upload.array('images', 5), async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);
    const files = req.files as Express.Multer.File[] | undefined;
    if (!files || files.length === 0) throw new AppError('No images provided', 400);

    const urls = await Promise.all(
      files.map((f) => uploadImageBuffer(f.buffer, 'products', f.originalname))
    );

    res.json({ success: true, urls });
  } catch (error) {
    next(error);
  }
});

router.post('/vendor-profile', authenticate, upload.single('photo'), async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);
    const file = req.file as Express.Multer.File | undefined;
    if (!file) throw new AppError('No photo provided', 400);

    const url = await uploadImageBuffer(file.buffer, 'vendors', file.originalname);
    res.json({ success: true, url });
  } catch (error) {
    next(error);
  }
});

router.post('/compliance', authenticate, upload.array('images', 3), async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);
    const files = req.files as Express.Multer.File[] | undefined;
    if (!files || files.length === 0) throw new AppError('No images provided', 400);

    const urls = await Promise.all(
      files.map((f) => uploadImageBuffer(f.buffer, 'compliance', f.originalname))
    );

    res.json({ success: true, urls });
  } catch (error) {
    next(error);
  }
});

export default router;

