const BREVO_API = 'https://api.brevo.com/v3/smtp/email';

function parseSender(): { name: string; email: string } {
  const raw = process.env.BREVO_FROM ?? process.env.BREVO_SENDER_EMAIL ?? 'noreply@addplus.co.ke';
  const match = raw.match(/^(.+?)\s*<([^>]+)>$/);
  if (match) return { name: match[1].trim(), email: match[2].trim() };
  return { name: 'ADDPlus+', email: raw };
}

export type SendEmailResult = { ok: true } | { ok: false; error: string };

export async function sendEmail(
  to: string,
  subject: string,
  html: string,
): Promise<SendEmailResult> {
  const apiKey = process.env.BREVO_API_KEY;
  if (!apiKey) {
    const error = 'BREVO_API_KEY not configured';
    console.warn('[ADDPlus+]', error, { to, subject });
    return { ok: false, error };
  }

  const sender = parseSender();
  const res = await fetch(BREVO_API, {
    method: 'POST',
    headers: {
      'api-key': apiKey,
      'Content-Type': 'application/json',
      Accept: 'application/json',
    },
    body: JSON.stringify({
      sender,
      to: [{ email: to }],
      subject,
      htmlContent: html,
    }),
  });

  if (!res.ok) {
    const body = await res.text();
    console.error('[ADDPlus+] Brevo error:', body);
    let message = 'Brevo rejected the email';
    try {
      const parsed = JSON.parse(body) as { message?: string };
      if (parsed.message) message = parsed.message;
    } catch {
      // use default message
    }
    return { ok: false, error: message };
  }
  return { ok: true };
}

export async function sendSms(phone: string, message: string): Promise<boolean> {
  const apiKey = process.env.BREVO_API_KEY;
  const sender = process.env.BREVO_SMS_SENDER;
  if (!apiKey || !sender) {
    console.warn('[ADDPlus+] BREVO_API_KEY or BREVO_SMS_SENDER not set — SMS not sent');
    return false;
  }

  const normalized = phone.replace(/\D/g, '').replace(/^0/, '254');
  const res = await fetch('https://api.brevo.com/v3/transactionalSMS/sms', {
    method: 'POST',
    headers: {
      'api-key': apiKey,
      'Content-Type': 'application/json',
      Accept: 'application/json',
    },
    body: JSON.stringify({
      sender,
      recipient: normalized,
      content: message,
      type: 'transactional',
    }),
  });

  if (!res.ok) {
    console.error('[ADDPlus+] Brevo SMS error:', await res.text());
    return false;
  }
  return true;
}

export function orderPlacedEmailHtml(orderId: string, totalKes: number): string {
  return `
    <p>Your ADDPlus+ order <strong>#${orderId.slice(0, 8)}</strong> for <strong>KES ${totalKes.toFixed(2)}</strong> has been placed.</p>
