import fs from 'fs';
import path from 'path';
import { v4 as uuidv4 } from 'uuid';
import { v2 as cloudinary } from 'cloudinary';

const useCloudinary = Boolean(
  process.env.CLOUDINARY_CLOUD_NAME &&
    process.env.CLOUDINARY_API_KEY &&
    process.env.CLOUDINARY_API_SECRET
);

if (useCloudinary) {
  cloudinary.config({
    cloud_name: process.env.CLOUDINARY_CLOUD_NAME,
    api_key: process.env.CLOUDINARY_API_KEY,
    api_secret: process.env.CLOUDINARY_API_SECRET,
  });
}

function uploadToCloudinary(buffer: Buffer, folder: string): Promise<string> {
  return new Promise((resolve, reject) => {
    const stream = cloudinary.uploader.upload_stream(
      { folder, resource_type: 'image', transformation: [{ quality: 'auto', fetch_format: 'auto' }] },
      (err, result) => {
        if (err || !result) return reject(err ?? new Error('Upload failed'));
        resolve(result.secure_url);
      }
    );
    stream.end(buffer);
  });
}

function uploadToDisk(buffer: Buffer, folder: string, originalname: string): string {
  const safeName = originalname.replace(/[^a-zA-Z0-9._-]/g, '_');
  const filename = `${uuidv4()}-${safeName}`;
  const dir = path.join(process.cwd(), 'uploads', folder);
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, filename), buffer);
  const base = (process.env.API_BASE_URL || `http://localhost:${process.env.PORT || 3001}`).replace(/\/$/, '');
  return `${base}/v1/uploads/files/${folder}/${filename}`;
}

export async function uploadImageBuffer(
  buffer: Buffer,
  folder: string,
  originalname = 'image.jpg'
): Promise<string> {
  if (useCloudinary) {
    return uploadToCloudinary(buffer, `addplus/${folder}`);
  }
  return uploadToDisk(buffer, folder, originalname);
}

export function isCloudinaryEnabled(): boolean {
  return useCloudinary;
}

