import express from 'express';
import { ComplianceService } from '../services/complianceService';
import { authenticate, authorize, AuthRequest } from '../middleware/auth';
import { AppError } from '../middleware/errorHandler';
import { requireVendorOwnership } from '../lib/vendorAccess';

const router = express.Router();
const complianceService = new ComplianceService();

router.get('/me/score', authenticate, authorize('vendor', 'admin'), async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);
    const scoreData = await complianceService.getComplianceScoreForUser(req.user.id);
    res.json({ success: true, ...scoreData });
  } catch (error) {
    next(error);
  }
});

router.get('/me/calendar', authenticate, authorize('vendor', 'admin'), async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);
    const days = parseInt(req.query.days as string) || 30;
    const calendar = await complianceService.getComplianceCalendarForUser(req.user.id, days);
    res.json({ success: true, calendar });
  } catch (error) {
    next(error);
  }
});

// Create post (vendor)
router.post('/posts', authenticate, authorize('vendor', 'admin'), async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);

    const post = await complianceService.createPost(req.user.id, req.body);
    res.status(201).json({ success: true, post });
  } catch (error) {
    next(error);
  }
});

// Log referral share
router.post('/referrals', authenticate, authorize('vendor', 'admin'), async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);

    const share = await complianceService.logReferralShare(req.user.id, req.body);
    res.status(201).json({ success: true, share });
  } catch (error) {
    next(error);
  }
});

// Get compliance score
router.get('/:vendorId/score', authenticate, authorize('vendor', 'admin'), async (req: AuthRequest, res, next) => {
  try {
    const { vendorId } = req.params;
    await requireVendorOwnership(req, vendorId);
    const scoreData = await complianceService.getComplianceScore(vendorId);
    res.json({ success: true, ...scoreData });
  } catch (error) {
    next(error);
  }
});

// Get compliance calendar
router.get('/:vendorId/calendar', authenticate, authorize('vendor', 'admin'), async (req: AuthRequest, res, next) => {
  try {
    const { vendorId } = req.params;
    await requireVendorOwnership(req, vendorId);
    const days = parseInt(req.query.days as string) || 30;
    const calendar = await complianceService.getComplianceCalendar(vendorId, days);
    res.json({ success: true, calendar });
  } catch (error) {
    next(error);
  }
});

// Issue fine (admin only)
router.post('/fines', authenticate, authorize('admin'), async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);

    const { vendorId, amount, reason, rule, posting_ban_days } = req.body;
    const fine = await complianceService.issueFine(vendorId, { amount, reason, rule, posting_ban_days }, req.user.id);
    res.status(201).json({ success: true, fine });
  } catch (error) {
    next(error);
  }
});

// Apply posting ban (admin only)
router.post('/ban', authenticate, authorize('admin'), async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);

    const { vendorId, days } = req.body;
    const result = await complianceService.applyPostingBan(vendorId, days, req.user.id);
    res.json({ success: true, ...result });
  } catch (error) {
    next(error);
  }
});

// Remove posting ban (admin only)
router.post('/unban', authenticate, authorize('admin'), async (req: AuthRequest, res, next) => {
  try {
    const { vendorId } = req.body;
    const result = await complianceService.removePostingBan(vendorId);
    res.json({ success: true, ...result });
  } catch (error) {
    next(error);
  }
});

export default router;

