import { AppError } from '../middleware/errorHandler';
import prisma from '../config/prisma';
import type { AuthRequest } from '../middleware/auth';

/** Ensures non-admin users can only access their own vendor profile. */
export async function requireVendorOwnership(req: AuthRequest, vendorId: string): Promise<void> {
  if (!req.user) throw new AppError('Not authenticated', 401);
  if (req.user.role === 'admin') return;

  const vp = await prisma.vendorProfile.findUnique({
    where: { user_id: req.user.id },
    select: { id: true },
  });
  if (!vp || vp.id !== vendorId) {
    throw new AppError('Access denied', 403);
  }
}

