import express from 'express';
import { authenticate, authorize, AuthRequest } from '../middleware/auth';
import { AppError } from '../middleware/errorHandler';
import prisma from '../config/prisma';
import { toCents } from '../lib/money';
import { MPesaService } from '../services/mpesaService';

const router = express.Router();
const mpesaService = new MPesaService();

// Submit importation request (vendor)
router.post('/requests', authenticate, authorize('vendor'), async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);
    const vp = await prisma.vendorProfile.findUnique({ where: { user_id: req.user.id }, select: { id: true } });
    if (!vp) throw new AppError('Vendor profile not found', 403);

    const { product_description, target_qty, max_price, reference_image_url } = req.body;
    const now = new Date();
    const cycleMonth = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;

    const request = await prisma.importationRequest.create({
      data: {
        vendor_id: vp.id,
        product_description,
        target_qty,
        max_price_cents: toCents(Number(max_price)),
        reference_image_url,
        cycle_month: cycleMonth
      }
    });

    res.status(201).json({ success: true, request });
  } catch (error) {
    next(error);
  }
});

// Get importation requests (admin sees all, vendor sees own)
router.get('/requests', authenticate, async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);

    const where: any = {};

    if (req.user.role !== 'admin') {
      const vp = await prisma.vendorProfile.findUnique({ where: { user_id: req.user.id }, select: { id: true } });
      if (!vp) throw new AppError('Vendor profile not found', 403);
      where.vendor_id = vp.id;
    }

    if (req.query.cycle_month) {
      where.cycle_month = req.query.cycle_month;
    }

    if (req.query.status) {
      where.status = req.query.status;
    }

    const requests = await prisma.importationRequest.findMany({
      where,
      orderBy: { created_at: 'desc' },
      include: req.user.role === 'admin' ? {
        vendor: {
          select: { business_name: true, user: { select: { phone: true } } }
        }
      } : undefined
    });

    res.json({ success: true, requests });
  } catch (error) {
    next(error);
  }
});

// Update importation request status (admin only)
router.put('/requests/:id/status', authenticate, authorize('admin'), async (req: AuthRequest, res, next) => {
  try {
    const { id } = req.params;
    const { status, admin_notes } = req.body;

    const request = await prisma.importationRequest.update({
      where: { id },
      data: { status, admin_notes }
    });

    res.json({ success: true, request });
  } catch (error) {
    next(error);
  }
});

// H4: Pay deposit for importation via STK Push
router.post('/deposits', authenticate, authorize('vendor'), async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);

    const { request_id, amount, phone } = req.body;
    if (!request_id || !amount) throw new AppError('request_id and amount are required', 400);

    const vp = await prisma.vendorProfile.findUnique({
      where: { user_id: req.user.id },
      select: { id: true, mpesa_number: true }
    });
    if (!vp) throw new AppError('Vendor profile not found', 403);

    // Verify request belongs to this vendor and is in correct state
    const importRequest = await prisma.importationRequest.findFirst({
      where: { id: request_id, vendor_id: vp.id }
    });
    if (!importRequest) throw new AppError('Importation request not found', 404);
    if (importRequest.deposit_mpesa_ref && importRequest.deposit_mpesa_ref !== 'PENDING') {
      throw new AppError('Deposit already paid for this request', 409);
    }

    const payPhone = phone || vp.mpesa_number;
    const stkResult = await mpesaService.initiateImportationDepositSTK(payPhone, Number(amount), request_id);

    // Mark as PENDING — updated to actual receipt via STK callback
    await prisma.importationRequest.update({
      where: { id: request_id },
      data: {
        deposit_amount_cents: toCents(Number(amount)),
        deposit_mpesa_ref: 'PENDING',
        deposit_checkout_request_id: stkResult.checkoutRequestID
      }
    });

    res.json({
      success: true,
      checkoutRequestId: stkResult.checkoutRequestID,
      message: stkResult.customerMessage || 'STK Push sent to your phone'
    });
  } catch (error) {
    next(error);
  }
});

// H4: Importation deposit STK callback (called by Safaricom)
router.post('/stk-callback', async (req, res, next) => {
  try {
    const signature = req.headers['x-mpesa-signature'] as string | undefined;
    const clientIp = req.ip || req.connection.remoteAddress || undefined;
    await mpesaService.handleImportationSTKCallback(req.body, signature, clientIp);
    res.json({ ResultCode: 0, ResultDesc: 'Success' });
  } catch (error) {
    console.error('Importation STK callback error:', error);
    res.json({ ResultCode: 0, ResultDesc: 'Received' });
  }
});

export default router;

import { PrismaClient } from '@prisma/client'
import { PrismaLibSQL } from '@prisma/adapter-libsql'
import { createClient } from '@libsql/client'

const globalForPrisma = globalThis as unknown as { prisma: PrismaClient }

function createPrismaClient(): PrismaClient {
  const url = process.env.TURSO_DATABASE_URL || process.env.DATABASE_URL || 'file:./prisma/dev.db'
  const authToken = process.env.DATABASE_AUTH_TOKEN

  const libsql = createClient({
    url,
    authToken: authToken || undefined,
  })

  const adapter = new PrismaLibSQL(libsql)

  return new PrismaClient({
    adapter,
    log: process.env.NODE_ENV === 'development' ? ['error', 'warn'] : ['error'],
  })
}

export const prisma = globalForPrisma.prisma ?? createPrismaClient()

if (process.env.NODE_ENV !== 'production') {
  globalForPrisma.prisma = prisma
}

export default prisma

