import express from 'express';
import { FundService } from '../services/fundService';
import { authenticate, authorize, AuthRequest } from '../middleware/auth';
import { AppError } from '../middleware/errorHandler';
import { requireVendorOwnership } from '../lib/vendorAccess';
import prisma from '../config/prisma';

const router = express.Router();
const fundService = new FundService();

// Get fund balance (public)
router.get('/balance', async (req, res, next) => {
  try {
    const balance = await fundService.getFundBalance();
    res.json({ success: true, ...balance });
  } catch (error) {
    next(error);
  }
});

// Get vendor contributions
router.get('/contributions/:vendorId', authenticate, authorize('vendor', 'admin'), async (req: AuthRequest, res, next) => {
  try {
    const { vendorId } = req.params;
    await requireVendorOwnership(req, vendorId);
    const contributions = await fundService.getVendorContributions(vendorId);
    res.json({ success: true, ...contributions });
  } catch (error) {
    next(error);
  }
});

// Get fund ledger (admin only)
router.get('/ledger', authenticate, authorize('admin'), async (req: AuthRequest, res, next) => {
  try {
    const filters = {
      page: parseInt(req.query.page as string) || 1,
      limit: parseInt(req.query.limit as string) || 20,
      type: req.query.type as string | undefined,
      vendor_id: req.query.vendor_id as string | undefined
    };

    const result = await fundService.getFundLedger(filters);
    res.json({ success: true, ...result });
  } catch (error) {
    next(error);
  }
});

// Submit grant application (vendor)
router.post('/grants/apply', authenticate, authorize('vendor'), async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);
    const vp = await prisma.vendorProfile.findUnique({ where: { user_id: req.user.id }, select: { id: true } });
    if (!vp) throw new AppError('Vendor profile not found', 403);
    const application = await fundService.submitGrantApplication(vp.id, req.body);
    res.status(201).json({ success: true, application });
  } catch (error) {
    next(error);
  }
});

// Get grant applications
router.get('/grants', authenticate, authorize('admin'), async (req: AuthRequest, res, next) => {
  try {
    const filters = {
      page: parseInt(req.query.page as string) || 1,
      limit: parseInt(req.query.limit as string) || 20,
      status: req.query.status as string | undefined,
      cycle_month: req.query.cycle_month as string | undefined,
      vendor_id: req.query.vendor_id as string | undefined
    };

    const result = await fundService.getGrantApplications(filters);
    res.json({ success: true, ...result });
  } catch (error) {
    next(error);
  }
});

// Approve and disburse grant (admin only)
router.post('/grants/:id/approve', authenticate, authorize('admin'), async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);

    const { id } = req.params;
    const result = await fundService.approveGrant(id, req.user.id, req.body);
    res.json({ success: true, result });
  } catch (error) {
    next(error);
  }
});

// Reject grant (admin only)
router.post('/grants/:id/reject', authenticate, authorize('admin'), async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);

    const { id } = req.params;
    const { reason } = req.body;
    const result = await fundService.rejectGrant(id, req.user.id, reason);
    res.json({ success: true, result });
  } catch (error) {
    next(error);
  }
});

export default router;

