import express from 'express';
import { ProductService } from '../services/productService';
import { authenticate, authorize, AuthRequest } from '../middleware/auth';
import { AppError } from '../middleware/errorHandler';
import prisma from '../config/prisma';

const router = express.Router();
const productService = new ProductService();

// List all products
router.get('/', async (req, res, next) => {
  try {
    const filters = {
      page: parseInt(req.query.page as string) || 1,
      limit: parseInt(req.query.limit as string) || 20,
      category_id: req.query.category_id as string | undefined,
      vendor_id: req.query.vendor_id as string | undefined,
      include_drafts: req.query.include_drafts === 'true',
      status: req.query.status as string | undefined,
      min_price: req.query.min_price ? parseFloat(req.query.min_price as string) : undefined,
      max_price: req.query.max_price ? parseFloat(req.query.max_price as string) : undefined,
      search: req.query.search as string | undefined,
      sort_by: req.query.sort_by as string | undefined
    };

    const result = await productService.listProducts(filters);
    res.json({ success: true, ...result });
  } catch (error) {
    next(error);
  }
});

// Search products
router.get('/search', async (req, res, next) => {
  try {
    const filters = {
      page: parseInt(req.query.page as string) || 1,
      limit: parseInt(req.query.limit as string) || 20,
      search: req.query.q as string | undefined,
      category_id: req.query.category_id as string | undefined,
      sort_by: req.query.sort_by as string | undefined
    };

    const result = await productService.listProducts(filters);
    res.json({ success: true, ...result });
  } catch (error) {
    next(error);
  }
});

// Get featured products
router.get('/featured', async (req, res, next) => {
  try {
    const limit = parseInt(req.query.limit as string) || 10;
    const products = await productService.getFeaturedProducts(limit);
    res.json({ success: true, products });
  } catch (error) {
    next(error);
  }
});

// Get new arrivals
router.get('/new-arrivals', async (req, res, next) => {
  try {
    const limit = parseInt(req.query.limit as string) || 20;
    const products = await productService.getNewArrivals(limit);
    res.json({ success: true, products });
  } catch (error) {
    next(error);
  }
});

// Get trending products
router.get('/trending', async (req, res, next) => {
  try {
    const limit = parseInt(req.query.limit as string) || 20;
    const products = await productService.getTrendingProducts(limit);
    res.json({ success: true, products });
  } catch (error) {
    next(error);
  }
});

// Get categories
router.get('/categories', async (req, res, next) => {
  try {
    const categories = await productService.getCategories();
    res.json({ success: true, categories });
  } catch (error) {
    next(error);
  }
});

// Vendor's own products (drafts + approved) — no KYC gate for read
router.get('/vendor/me', authenticate, authorize('vendor', 'admin'), async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);
    const vendorId = await resolveVendorProfileId(req.user.id);
    const filters = {
      page: parseInt(req.query.page as string) || 1,
      limit: parseInt(req.query.limit as string) || 100,
      vendor_id: vendorId,
      include_drafts: true,
    };
    const result = await productService.listProducts(filters);
    res.json({ success: true, ...result });
  } catch (error) {
    next(error);
  }
});

// Get single product
router.get('/:id', async (req, res, next) => {
  try {
    const { id } = req.params;
    const product = await productService.getProductById(id);
    res.json({ success: true, product });
  } catch (error) {
    next(error);
  }
});

// Get related products
router.get('/:id/related', async (req, res, next) => {
  try {
    const { id } = req.params;
    const limit = parseInt(req.query.limit as string) || 8;
    const products = await productService.getRelatedProducts(id, limit);
    res.json({ success: true, products });
  } catch (error) {
    next(error);
  }
});

async function resolveVendorProfileId(userId: string): Promise<string> {
  const vendor = await prisma.vendorProfile.findUnique({
    where: { user_id: userId },
    select: { id: true },
  });
  if (!vendor) throw new AppError('Vendor profile not found', 403);
  return vendor.id;
}

// Helper: resolve vendor profile ID from authenticated user (writes require approval)
async function getVendorId(userId: string): Promise<string> {
  const vendor = await prisma.vendorProfile.findUnique({
    where: { user_id: userId },
    select: { id: true, kyc_status: true, is_suspended: true }
  });
  if (!vendor) throw new AppError('Vendor profile not found', 403);
  if (vendor.kyc_status !== 'approved') throw new AppError('Vendor account pending approval', 403);
  if (vendor.is_suspended) throw new AppError('Vendor account is suspended', 403);
  return vendor.id;
}

// Create product (vendor only)
router.post('/', authenticate, authorize('vendor', 'admin'), async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);
    const vendorId = await getVendorId(req.user.id);
    const product = await productService.createProduct(vendorId, req.body, req.user.id);
    res.status(201).json({ success: true, product });
  } catch (error) {
    next(error);
  }
});

// Update product
router.put('/:id', authenticate, authorize('vendor', 'admin'), async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);
    const vendorId = await getVendorId(req.user.id);
    const { id } = req.params;
    const product = await productService.updateProduct(id, vendorId, req.body, req.user.id);
    res.json({ success: true, product });
  } catch (error) {
    next(error);
  }
});

// Delete product
router.delete('/:id', authenticate, authorize('vendor', 'admin'), async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);
    const vendorId = await getVendorId(req.user.id);
    const { id } = req.params;
    const result = await productService.deleteProduct(id, vendorId, req.user.id);
    res.json({ success: true, ...result });
  } catch (error) {
    next(error);
  }
});

export default router;

