import express from 'express';
import { authenticate, authorize, AuthRequest, invalidateUserCache } from '../middleware/auth';
import { AppError } from '../middleware/errorHandler';
import { parseJsonObject, stringifyJsonObject } from '../lib/jsonFields';
import { OrderService } from '../services/orderService';
import { ProductService } from '../services/productService';
import prisma from '../config/prisma';

const router = express.Router();
const orderService = new OrderService();
const productService = new ProductService();

router.get('/health', authenticate, authorize('admin'), async (_req, res, next) => {
  try {
    const [
      productsPendingReview,
      lowStockProducts,
      avgCompliance,
      openDisputes,
      oldestDispute,
    ] = await Promise.all([
      prisma.product.count({ where: { status: 'PENDING_REVIEW', deleted_at: null } }),
      prisma.product.count({ where: { status: 'APPROVED', stock_qty: { lt: 5 }, deleted_at: null } }),
      prisma.vendorProfile.aggregate({ where: { kyc_status: 'approved' }, _avg: { compliance_score: true } }),
      prisma.dispute.count({ where: { status: 'open' } }),
      prisma.dispute.findFirst({ where: { status: 'open' }, orderBy: { created_at: 'asc' } }),
    ]);

    const approvedVendors = await prisma.vendorProfile.count({ where: { kyc_status: 'approved' } });
    const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);
    const activeVendors = await prisma.orderItem.groupBy({
      by: ['vendor_id'],
      where: { created_at: { gte: thirtyDaysAgo } },
    });

    const delivered = await prisma.order.count({ where: { status: 'delivered' } });
    const closed = await prisma.order.count({
      where: { status: { in: ['delivered', 'disputed', 'cancelled'] } },
    });

    res.json({
      success: true,
      health: {
        products_pending_review: productsPendingReview,
        low_stock_products: lowStockProducts,
        avg_compliance_score: avgCompliance._avg.compliance_score || 0,
        vendor_retention_30d_pct: approvedVendors ? (activeVendors.length / approvedVendors) * 100 : 0,
        order_fulfillment_rate_pct: closed ? (delivered / closed) * 100 : 0,
        open_disputes: openDisputes,
        oldest_dispute_hours: oldestDispute
          ? (Date.now() - oldestDispute.created_at.getTime()) / 3600000
          : null,
      },
    });
  } catch (error) {
    next(error);
  }
});

// Get admin dashboard overview
router.get('/dashboard', authenticate, authorize('admin'), async (req: AuthRequest, res, next) => {
  try {
    // Get counts
    const [
      totalVendors,
      pendingVendors,
      totalCustomers,
      totalOrders,
      pendingOrders,
      disputedOrders,
      fundBalance
    ] = await Promise.all([
      prisma.vendorProfile.count({ where: { kyc_status: 'approved' } }),
      prisma.vendorProfile.count({ where: { kyc_status: 'pending' } }),
      prisma.user.count({ where: { role: 'customer' } }),
      prisma.order.count(),
      prisma.order.count({ where: { status: { in: ['confirmed', 'processing'] } } }),
      prisma.dispute.count({ where: { status: 'open' } }),
      prisma.collectiveFund.aggregate({
        where: { type: { in: ['advancement_contribution', 'profit_share_contribution'] } },
        _sum: { amount_cents: true }
      })
    ]);

    const today = new Date();
    const startOfMonth = new Date(today.getFullYear(), today.getMonth(), 1);

    const monthlyGMV = await prisma.order.aggregate({
      where: { created_at: { gte: startOfMonth } },
      _sum: { total_amount_cents: true }
    });

    res.json({
      success: true,
      overview: {
        total_vendors: totalVendors,
        pending_vendors: pendingVendors,
        total_customers: totalCustomers,
        total_orders: totalOrders,
        pending_orders: pendingOrders,
        disputed_orders: disputedOrders,
        fund_balance_cents: fundBalance._sum.amount_cents || 0,
        monthly_gmv_cents: monthlyGMV._sum.total_amount_cents || 0
      }
    });
  } catch (error) {
    next(error);
  }
});

// Get pending vendors
router.get('/vendors/pending', authenticate, authorize('admin'), async (req: AuthRequest, res, next) => {
  try {
    const vendors = await prisma.vendorProfile.findMany({
      where: { kyc_status: 'pending' },
      include: {
        user: {
          select: { phone: true, full_name: true, created_at: true }
        }
      },
      orderBy: { created_at: 'desc' }
    });

    res.json({ success: true, vendors });
  } catch (error) {
    next(error);
  }
});

// Approve vendor
router.post('/vendors/:id/approve', authenticate, authorize('admin'), async (req: AuthRequest, res, next) => {
  try {
    const { id } = req.params;

    const vendor = await prisma.vendorProfile.update({
      where: { id },
      data: { kyc_status: 'approved' }
    });

    await invalidateUserCache(vendor.user_id);
    res.json({ success: true, vendor });
  } catch (error) {
    next(error);
  }
});

// Reject vendor
router.post('/vendors/:id/reject', authenticate, authorize('admin'), async (req: AuthRequest, res, next) => {
  try {
    const { id } = req.params;
    const { reason } = req.body;

    const existing = await prisma.vendorProfile.findUnique({ where: { id }, select: { documents: true } });
    const docs = parseJsonObject<Record<string, unknown>>(existing?.documents);
    const vendor = await prisma.vendorProfile.update({
      where: { id },
      data: {
        kyc_status: 'rejected',
        documents: stringifyJsonObject({ ...docs, rejection_reason: reason }),
      }
    });

    await invalidateUserCache(vendor.user_id);
    res.json({ success: true, vendor });
  } catch (error) {
    next(error);
  }
});

// Suspend vendor
router.post('/vendors/:id/suspend', authenticate, authorize('admin'), async (req: AuthRequest, res, next) => {
  try {
    const { id } = req.params;

    const vendor = await prisma.vendorProfile.update({
      where: { id },
      data: { is_suspended: true }
    });

    await invalidateUserCache(vendor.user_id);
    res.json({ success: true, vendor });
  } catch (error) {
    next(error);
  }
});

// Get disputes
router.get('/disputes', authenticate, authorize('admin'), async (req: AuthRequest, res, next) => {
  try {
    const filters = {
      page: parseInt(req.query.page as string) || 1,
      limit: parseInt(req.query.limit as string) || 20,
      status: req.query.status as string | undefined
    };

    const result = await orderService.getDisputes(filters);
    res.json({ success: true, ...result });
  } catch (error) {
    next(error);
  }
});

// Resolve dispute
router.put('/disputes/:id/resolve', authenticate, authorize('admin'), async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);

    const { id } = req.params;
    const { resolution, notes, refund_amount } = req.body;

    const result = await orderService.resolveDispute(id, req.user.id, resolution, notes, refund_amount);
    res.json({ success: true, result });
  } catch (error) {
    next(error);
  }
});

// List orders (admin)
router.get('/orders', authenticate, authorize('admin'), async (req: AuthRequest, res, next) => {
  try {
    const page = parseInt(req.query.page as string) || 1;
    const limit = parseInt(req.query.limit as string) || 20;
    const status = req.query.status as string | undefined;

    const where: any = {};
    if (status) where.status = status;

    const [orders, total] = await Promise.all([
      prisma.order.findMany({
        where,
        orderBy: { created_at: 'desc' },
        skip: (page - 1) * limit,
        take: limit,
        include: {
          customer: { select: { phone: true, full_name: true } },
          order_items: {
            include: {
              product: { select: { title: true } },
              vendor: { select: { business_name: true } },
            },
          },
        },
      }),
      prisma.order.count({ where }),
    ]);

    res.json({ success: true, orders, total, page, limit });
  } catch (error) {
    next(error);
  }
});

// Products pending review
router.get('/products/pending', authenticate, authorize('admin'), async (req: AuthRequest, res, next) => {
  try {
    const products = await prisma.product.findMany({
      where: { status: 'PENDING_REVIEW', deleted_at: null },
      orderBy: { submitted_at: 'asc' },
      include: {
        vendor: { select: { business_name: true } },
        category: { select: { name: true } },
      },
    });
    res.json({ success: true, products });
  } catch (error) {
    next(error);
  }
});

router.put('/products/:id/moderate', authenticate, authorize('admin'), async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);
    const { id } = req.params;
    const { action, reason } = req.body;
    if (!['approve', 'reject'].includes(action)) throw new AppError('Invalid action', 400);
    const product = await productService.moderateProduct(id, req.user.id, action, reason);
    res.json({ success: true, product });
  } catch (error) {
    next(error);
  }
});

// List market insights
router.get('/insights', authenticate, authorize('admin'), async (req: AuthRequest, res, next) => {
  try {
    const insights = await prisma.marketInsight.findMany({
      orderBy: { created_at: 'desc' },
      include: { author: { select: { full_name: true, phone: true } } },
    });
    res.json({ success: true, insights });
  } catch (error) {
    next(error);
  }
});

// Publish market insights
router.post('/insights', authenticate, authorize('admin'), async (req: AuthRequest, res, next) => {
  try {
    if (!req.user) throw new AppError('Not authenticated', 401);

    const { title, body, attachments } = req.body;

    const insight = await prisma.marketInsight.create({
      data: {
        author_id: req.user.id,
        title,
        body,
        attachments: stringifyJsonObject(attachments ?? []),
        is_published: true,
        published_at: new Date()
      }
    });

    res.status(201).json({ success: true, insight });
  } catch (error) {
    next(error);
  }
});

export default router;

