import { Request, Response, NextFunction } from 'express';
import { ZodError } from 'zod';
import { Prisma } from '@prisma/client';

export class AppError extends Error {
  statusCode: number;
  isOperational: boolean;

  constructor(message: string, statusCode: number) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

// Security: Generic error messages to prevent information leakage
const getGenericErrorMessage = (statusCode: number): string => {
  const messages: Record<number, string> = {
    400: 'Bad request',
    401: 'Unauthorized',
    403: 'Access denied',
    404: 'Resource not found',
    409: 'Resource conflict',
    429: 'Too many requests',
    500: 'Internal server error',
    502: 'Service unavailable',
    503: 'Service temporarily unavailable'
  };
  return messages[statusCode] || 'An error occurred';
};

// Security: Sanitize error messages to remove sensitive info
const sanitizeErrorMessage = (message: string): string => {
  // Remove potential sensitive patterns
  const sensitivePatterns = [
    /password/i,
    /secret/i,
    /token/i,
    /key/i,
    /credential/i,
    /jwt/i,
    /auth/i,
    /database/i,
    /prisma/i,
    /connection/i,
    /timeout/i
  ];

  let sanitized = message;
  sensitivePatterns.forEach(pattern => {
    sanitized = sanitized.replace(pattern, '[REDACTED]');
  });

  return sanitized;
};

export const errorHandler = (
  err: Error | AppError | ZodError,
  req: Request,
  res: Response,
  next: NextFunction
) => {
  let statusCode = 500;
  let message = 'Internal server error';
  let errors: any = null;

  if (err instanceof AppError) {
    statusCode = err.statusCode;
    // Operational 4xx messages are safe to return to clients (e.g. password rules, conflicts).
    message = statusCode >= 500 && process.env.NODE_ENV === 'production'
      ? getGenericErrorMessage(statusCode)
      : err.message;
  } else if (err instanceof ZodError) {
    statusCode = 400;
    message = 'Validation error';
    errors = err.errors.map(e => ({
      field: e.path.join('.'),
      message: e.message
    }));
  } else if (err instanceof Prisma.PrismaClientKnownRequestError) {
    statusCode = 400;
    // Security: Never expose Prisma error details in production
    if (process.env.NODE_ENV === 'production') {
      message = 'Database error';
    } else {
      if (err.code === 'P2002') {
        message = 'Unique constraint violation';
      } else if (err.code === 'P2025') {
        statusCode = 404;
        message = 'Record not found';
      } else {
        message = 'Database operation failed';
      }
    }
  } else if (err instanceof Prisma.PrismaClientValidationError) {
    statusCode = 400;
    message = process.env.NODE_ENV === 'production' 
      ? 'Invalid data provided' 
      : 'Validation failed';
  } else if (err instanceof Prisma.PrismaClientInitializationError) {
    statusCode = 503;
    message = 'Service temporarily unavailable';
  }

  // Security: Log full error details server-side only
  if (process.env.NODE_ENV === 'development') {
    console.error('Error:', err);
  } else {
    // Production: Log to monitoring service (structured logging)
    console.error(JSON.stringify({
      timestamp: new Date().toISOString(),
      error: sanitizeErrorMessage(err.message),
      stack: err.stack,
      path: req.path,
      method: req.method,
      ip: req.ip,
      userAgent: req.get('user-agent')
    }));
  }

  // Security: Never expose stack traces in production
  const clientError =
    err instanceof AppError && err.isOperational && statusCode < 500
      ? message
      : sanitizeErrorMessage(message);

  const response: any = {
    success: false,
    error: clientError,
    ...(errors && { errors })
  };

  // Only include requestId for tracing in production
  if (process.env.NODE_ENV === 'production') {
    response.requestId = `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }

  res.status(statusCode).json(response);
};

// Security: Async handler wrapper for consistent error handling
export const asyncHandler = (fn: Function) => {
  return (req: Request, res: Response, next: NextFunction) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
};

// Security: Unhandled rejection handler
process.on('unhandledRejection', (reason: any, promise: Promise<any>) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, you might want to exit and let PM2/docker restart
  if (process.env.NODE_ENV === 'production') {
    process.exit(1);
  }
});

// Security: Uncaught exception handler
process.on('uncaughtException', (error: Error) => {
  console.error('Uncaught Exception:', error);
  // Always exit on uncaught exceptions to prevent undefined state
  process.exit(1);
});

