1	import { Expo, ExpoPushMessage, ExpoPushTicket } from 'expo-server-sdk';
2	import prisma from '../config/prisma';
3	import {
4	  orderPlacedEmailHtml,
5	  paymentReceivedEmailHtml,
6	  sendEmail,
7	  vendorNewOrderEmailHtml,
8	} from './emailService';
9	
10	const expo = new Expo();
11	
12	export class NotificationService {
13	  private async getUserContact(userId: string): Promise<{ pushToken: string | null; email: string | null }> {
14	    const user = await prisma.user.findUnique({
15	      where: { id: userId },
16	      select: { push_token: true, email: true },
17	    });
18	    return { pushToken: user?.push_token ?? null, email: user?.email ?? null };
19	  }
20	
21	  private async sendEmailIfConfigured(
22	    email: string | null,
23	    subject: string,
24	    html: string,
25	  ): Promise<void> {
26	    if (!email) return;
27	    await sendEmail(email, subject, html);
28	  }
29	
30	  private async sendPush(token: string, title: string, body: string, data?: Record<string, unknown>): Promise<void> {
31	    if (!Expo.isExpoPushToken(token)) {
32	      console.warn(`[Push] Invalid token for user: ${(token as string).substring(0, 20)}...`);
33	      return;
34	    }
35	
36	    const message: ExpoPushMessage = {
37	      to: token,
38	      sound: 'default',
39	      title,
40	      body,
41	      data: (data ?? {}) as Record<string, unknown>,
42	    };
43	
44	    try {
45	      const chunks = expo.chunkPushNotifications([message]);
46	      for (const chunk of chunks) {
47	        const tickets: ExpoPushTicket[] = await expo.sendPushNotificationsAsync(chunk);
48	        for (const ticket of tickets) {
49	          if (ticket.status === 'error') {
50	            console.error('[Push] Ticket error:', ticket.message);
51	            if (ticket.details?.error === 'DeviceNotRegistered') {
52	              await prisma.user.updateMany({
53	                where: { push_token: token },
54	                data: { push_token: null }
55	              });
56	            }
57	          }
58	        }
59	      }
60	    } catch (err: any) {
61	      console.error('[Push] Send error:', err.message);
62	    }
63	  }
64	
65	  async notifyOrderPlaced(customerId: string, orderId: string, total: number): Promise<void> {
66	    const { pushToken, email } = await this.getUserContact(customerId);
67	    if (pushToken) {
68	      await this.sendPush(
69	        pushToken,
70	        'Order Placed ✅',
71	        `Your order KES ${total.toFixed(2)} is confirmed. Pay via M-PESA to proceed.`,
72	        { type: 'order_placed', orderId },
73	      );
74	    }
75	    await this.sendEmailIfConfigured(
76	      email,
77	      'ADDPlus+ — Order placed',
78	      orderPlacedEmailHtml(orderId, total),
79	    );
80	  }
81	
82	  async notifyPaymentReceived(customerId: string, orderId: string, amount: number): Promise<void> {
83	    const { pushToken, email } = await this.getUserContact(customerId);
84	    if (pushToken) {
85	      await this.sendPush(
86	        pushToken,
87	        'Payment Received 💚',
88	        `KES ${amount.toFixed(2)} received. Your order is now being processed.`,
89	        { type: 'payment_received', orderId },
90	      );
91	    }
92	    await this.sendEmailIfConfigured(
93	      email,
94	      'ADDPlus+ — Payment received',
95	      paymentReceivedEmailHtml(orderId, amount),
96	    );
97	  }
98	
