import { Expo, ExpoPushMessage, ExpoPushTicket } from 'expo-server-sdk';
import prisma from '../config/prisma';
import {
  orderPlacedEmailHtml,
  paymentReceivedEmailHtml,
  sendEmail,
  vendorNewOrderEmailHtml,
} from './emailService';

const expo = new Expo();

export class NotificationService {
  private async getUserContact(userId: string): Promise<{ pushToken: string | null; email: string | null }> {
    const user = await prisma.user.findUnique({
      where: { id: userId },
      select: { push_token: true, email: true },
    });
    return { pushToken: user?.push_token ?? null, email: user?.email ?? null };
  }

  private async sendEmailIfConfigured(
    email: string | null,
    subject: string,
    html: string,
  ): Promise<void> {
    if (!email) return;
    await sendEmail(email, subject, html);
  }

  private async sendPush(token: string, title: string, body: string, data?: Record<string, unknown>): Promise<void> {
    if (!Expo.isExpoPushToken(token)) {
      console.warn(`[Push] Invalid token for user: ${(token as string).substring(0, 20)}...`);
      return;
    }

    const message: ExpoPushMessage = {
      to: token,
      sound: 'default',
      title,
      body,
      data: (data ?? {}) as Record<string, unknown>,
    };

    try {
      const chunks = expo.chunkPushNotifications([message]);
      for (const chunk of chunks) {
        const tickets: ExpoPushTicket[] = await expo.sendPushNotificationsAsync(chunk);
        for (const ticket of tickets) {
          if (ticket.status === 'error') {
            console.error('[Push] Ticket error:', ticket.message);
            if (ticket.details?.error === 'DeviceNotRegistered') {
              await prisma.user.updateMany({
                where: { push_token: token },
                data: { push_token: null }
              });
            }
          }
        }
      }
    } catch (err: any) {
      console.error('[Push] Send error:', err.message);
    }
  }

  async notifyOrderPlaced(customerId: string, orderId: string, total: number): Promise<void> {
    const { pushToken, email } = await this.getUserContact(customerId);
    if (pushToken) {
      await this.sendPush(
        pushToken,
        'Order Placed ✅',
        `Your order KES ${total.toFixed(2)} is confirmed. Pay via M-PESA to proceed.`,
        { type: 'order_placed', orderId },
      );
    }
    await this.sendEmailIfConfigured(
      email,
      'ADDPlus+ — Order placed',
      orderPlacedEmailHtml(orderId, total),
    );
  }

  async notifyPaymentReceived(customerId: string, orderId: string, amount: number): Promise<void> {
    const { pushToken, email } = await this.getUserContact(customerId);
    if (pushToken) {
      await this.sendPush(
        pushToken,
        'Payment Received 💚',
        `KES ${amount.toFixed(2)} received. Your order is now being processed.`,
        { type: 'payment_received', orderId },
      );
    }
    await this.sendEmailIfConfigured(
      email,
      'ADDPlus+ — Payment received',
      paymentReceivedEmailHtml(orderId, amount),
    );
  }

  async notifyOrderDispatched(customerId: string, orderId: string): Promise<void> {
    const { pushToken } = await this.getUserContact(customerId);
    if (!pushToken) return;
    await this.sendPush(
      pushToken,
      'Order On the Way 🚚',
      'Your order has been dispatched and is on its way to you.',
      { type: 'order_dispatched', orderId }
    );
  }

  async notifyVendorNewOrder(vendorUserId: string, orderItemId: string, productTitle: string): Promise<void> {
    const { pushToken, email } = await this.getUserContact(vendorUserId);
    if (pushToken) {
      await this.sendPush(
        pushToken,
        'New Order Received 🛒',
        `New order for "${productTitle}" — accept and prepare for dispatch.`,
        { type: 'new_order', orderItemId },
      );
    }
    await this.sendEmailIfConfigured(
      email,
      'ADDPlus+ — New order',
      vendorNewOrderEmailHtml(productTitle),
    );
  }

  async notifyVendorEscrowReleased(vendorUserId: string, amount: number): Promise<void> {
    const { pushToken } = await this.getUserContact(vendorUserId);
    if (!pushToken) return;
    await this.sendPush(
      pushToken,
      'Payout Initiated 💰',
      `KES ${amount.toFixed(2)} payout has been sent to your M-PESA.`,
      { type: 'escrow_released', amount }
    );
  }

  async notifyDisputeOpened(vendorUserId: string, orderItemId: string): Promise<void> {
    const { pushToken } = await this.getUserContact(vendorUserId);
    if (!pushToken) return;
    await this.sendPush(
      pushToken,
      'Dispute Opened ⚠️',
      'A customer has opened a dispute on one of your orders. Check the app.',
      { type: 'dispute_opened', orderItemId }
    );
  }

  async notifyComplianceFine(vendorUserId: string, amount: number, reason: string): Promise<void> {
    const { pushToken } = await this.getUserContact(vendorUserId);
    if (!pushToken) return;
    await this.sendPush(
      pushToken,
      'Compliance Fine Issued ⚠️',
      `KES ${amount} fine: ${reason}`,
      { type: 'compliance_fine', amount, reason }
    );
  }

  async registerToken(userId: string, token: string): Promise<void> {
    if (!Expo.isExpoPushToken(token)) {
      throw new Error('Invalid Expo push token');
    }
    await prisma.user.update({
      where: { id: userId },
      data: { push_token: token }
    });
  }
}

export const notificationService = new NotificationService();

