#!/usr/bin/env bash
# Purge all user accounts and dependent auth data from ADDPlus+ Turso DB.
# Keeps categories, settings, and non-user marketplace seed data.
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
API_DIR="$ROOT/apps/api"
DB_NAME="${TURSO_DB_NAME:-addplus-db}"

export PATH="${HOME}/.local/bin:${HOME}/.turso:${PATH}"

if ! turso auth whoami >/dev/null 2>&1; then
  echo "Run: turso auth login"
  exit 1
fi

echo "Purging user accounts from $DB_NAME..."

turso db shell "$DB_NAME" <<'SQL'
PRAGMA foreign_keys = OFF;

DELETE FROM refresh_tokens;
DELETE FROM otp_codes;
DELETE FROM disputes;
DELETE FROM escrow_ledger;
DELETE FROM collective_fund;
DELETE FROM order_items;
DELETE FROM orders;
DELETE FROM inventory_movements;
DELETE FROM reviews;
DELETE FROM products;
DELETE FROM vendor_posts;
DELETE FROM referral_shares;
DELETE FROM compliance_logs;
DELETE FROM fine_ledger;
DELETE FROM grant_applications;
DELETE FROM importation_requests;
DELETE FROM market_insights;
DELETE FROM activity_logs;
DELETE FROM vendor_profiles;
DELETE FROM users;

PRAGMA foreign_keys = ON;
SQL

echo "User purge complete. Re-seed admin with: npm run db:seed-turso"

