import { Request, Response, NextFunction } from 'express';
import crypto from 'crypto';

// Security: Sanitize sensitive data from logs
const sanitizeForLog = (data: any): any => {
  if (!data) return data;

  const sensitiveFields = ['password', 'token', 'secret', 'key', 'credential', 'mpesa_pin', 'otp'];

  if (typeof data === 'string') {
    return data;
  }

  if (Array.isArray(data)) {
    return data.map(sanitizeForLog);
  }

  if (typeof data === 'object') {
    const sanitized: any = {};
    for (const [key, value] of Object.entries(data)) {
      if (sensitiveFields.includes(key.toLowerCase())) {
        sanitized[key] = '[REDACTED]';
      } else if (typeof value === 'object') {
        sanitized[key] = sanitizeForLog(value);
      } else {
        sanitized[key] = value;
      }
    }
    return sanitized;
  }

  return data;
};

// Security: Generate request ID for tracing
const generateRequestId = (): string => {
  return `${Date.now()}-${crypto.randomBytes(4).toString('hex')}`;
};

/**
 * Security: Structured request logging middleware
 * Logs in AUDIT format per SECURITY.md requirements
 */
export const requestLogger = (req: Request, res: Response, next: NextFunction) => {
  const requestId = generateRequestId();
  (req as any).requestId = requestId;

  const startTime = Date.now();
  const timestamp = new Date().toISOString();
  const ip = req.ip || req.socket.remoteAddress || 'unknown';
  const method = req.method;
  const path = req.url;
  const userAgent = req.get('user-agent') || 'unknown';
  const userId = (req as any).user?.id || null;

  // Initial request log
  console.log(JSON.stringify({
    type: 'AUDIT',
    timestamp,
    action: 'request_start',
    requestId,
    ip,
    userId,
    path,
    method,
    userAgent
  }));

  res.on('finish', () => {
    const duration = Date.now() - startTime;
    const statusCode = res.statusCode;

    // Determine action type based on status/behavior
    let action = 'request_complete';
    if (statusCode >= 400 && statusCode < 500) {
      action = 'client_error';
    } else if (statusCode >= 500) {
      action = 'server_error';
    }

    const logEntry: any = {
      type: 'AUDIT',
      timestamp: new Date().toISOString(),
      action,
      requestId,
      ip,
      userId,
      path,
      method,
      statusCode,
      duration,
      userAgent,
      details: {
        responseTime: `${duration}ms`
      }
    };

    // Include sanitized body for specific security-relevant paths
    const securityPaths = ['/auth', '/login', '/register', '/payments'];
    if (securityPaths.some(sp => path.includes(sp)) && req.body && Object.keys(req.body).length > 0) {
      logEntry.details.body = sanitizeForLog(req.body);
    }

    console.log(JSON.stringify(logEntry));
  });

  next();
};

/**
 * Security: Security event logging helper
 * For logging security-relevant events like auth failures, rate limits, etc.
 */
export const securityLog = (
  action: string,
  req: Request,
  details?: any,
  userId?: string | null
) => {
  console.log(JSON.stringify({
    type: 'SECURITY',
    timestamp: new Date().toISOString(),
    action,
    ip: req.ip || req.socket.remoteAddress || 'unknown',
    userId: userId || (req as any).user?.id || null,
    path: req.url,
    method: req.method,
    requestId: (req as any).requestId,
    userAgent: req.get('user-agent'),
    details: sanitizeForLog(details)
  }));
};
import { createClient, RedisClientType } from 'redis';

// Client is created lazily inside connectRedis() after dotenv has loaded
let redisClient: RedisClientType | null = null;

export const connectRedis = async (): Promise<void> => {
  const url = process.env.REDIS_URL || 'redis://localhost:6379';

  try {
    redisClient = createClient({
      url,
      socket: {
        reconnectStrategy: (retries) => {
          if (retries > 5) {
            console.error('Redis: max reconnect attempts reached — running without Redis');
            return false;
          }
          return Math.min(retries * 200, 2000);
        }
      }
    }) as RedisClientType;

    redisClient.on('error', (err) => {
      if (process.env.NODE_ENV !== 'test') {
        console.error('Redis client error:', err.message);
      }
    });
    redisClient.on('connect', () => console.log('Redis connected'));
    redisClient.on('reconnecting', () => console.log('Redis reconnecting...'));

    await redisClient.connect();
  } catch (err: any) {
    console.warn('Redis unavailable — token blacklist and caching will be skipped:', err.message);
    redisClient = null;
  }
};

export const isRedisReady = (): boolean => !!(redisClient?.isReady);

// Typed accessor — callers must guard with isRedisReady()
const getClient = (): RedisClientType => {
  if (!redisClient) throw new Error('Redis client not initialized');
  return redisClient;
};

export default {
  get: (...args: Parameters<RedisClientType['get']>) => getClient().get(...args),
  set: (...args: Parameters<RedisClientType['set']>) => getClient().set(...args),
  setEx: (...args: Parameters<RedisClientType['setEx']>) => getClient().setEx(...args),
  del: (...args: Parameters<RedisClientType['del']>) => getClient().del(...args),
  incr: (...args: Parameters<RedisClientType['incr']>) => getClient().incr(...args),
  expire: (...args: Parameters<RedisClientType['expire']>) => getClient().expire(...args),
  ttl: (...args: Parameters<RedisClientType['ttl']>) => getClient().ttl(...args),
};
export const toCents = (kes: number): number => Math.round(kes * 100)

export const fromCents = (cents: number): number => cents / 100

export const formatKES = (cents: number): string =>
  `KES ${fromCents(cents).toLocaleString('en-KE', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`

export const withMoneyDisplay = <T extends Record<string, unknown>>(
  obj: T,
  centFields: string[]
): T & Record<string, number> => {
  const out = { ...obj } as T & Record<string, number>
  for (const field of centFields) {
    const cents = obj[field] as number | undefined
    if (typeof cents === 'number') {
      const displayKey = field.replace(/_cents$/, '')
      ;(out as Record<string, number>)[displayKey] = fromCents(cents)
    }
  }
  return out
}
export const parseJsonArray = (value: string | null | undefined): string[] => {
  if (!value) return []
  try {
    const parsed = JSON.parse(value)
    return Array.isArray(parsed) ? parsed : []
  } catch {
    return []
  }
}

export const stringifyJsonArray = (value: string[] | undefined | null): string =>
  JSON.stringify(value ?? [])

export const parseJsonObject = <T extends Record<string, unknown>>(value: string | null | undefined): T => {
  if (!value) return {} as T
  try {
    return JSON.parse(value) as T
  } catch {
    return {} as T
  }
}

export const stringifyJsonObject = (value: unknown): string | null => {
  if (value === undefined || value === null) return null
  return JSON.stringify(value)
}

