import axios from 'axios';

export class SMSService {
  private apiKey: string;
  private username: string;
  private senderId: string;

  constructor() {
    this.apiKey = process.env.AT_API_KEY || '';
    this.username = process.env.AT_USERNAME || '';
    this.senderId = process.env.AT_SENDER_ID || 'ADDPlus';
  }

  async sendOTP(phone: string, code: string): Promise<void> {
    const message = `Your ADDPlus+ verification code is: ${code}. Valid for 10 minutes.`;

    try {
      await this.sendSMS(phone, message);
    } catch (error) {
      console.error('Failed to send OTP:', error);
      // In development, just log the code
      if (process.env.NODE_ENV === 'development') {
        console.log(`[DEV OTP] ${phone}: ${code}`);
      }
    }
  }

  async sendOrderNotification(phone: string, orderId: string, status: string): Promise<void> {
    const messages: Record<string, string> = {
      confirmed: `Your ADDPlus+ order ${orderId} has been confirmed. Thank you for shopping with us!`,
      dispatched: `Your ADDPlus+ order ${orderId} has been dispatched. Get ready to receive your items!`,
      delivered: `Your ADDPlus+ order ${orderId} has been delivered. Please confirm receipt in the app.`,
      payout: `Your ADDPlus+ payout has been sent to your M-Pesa. Check your messages for confirmation.`
    };

    const message = messages[status] || `Your ADDPlus+ order ${orderId} status: ${status}`;
    await this.sendSMS(phone, message);
  }

  async sendVendorNotification(phone: string, type: string, data: any): Promise<void> {
    const messages: Record<string, (d: any) => string> = {
      new_order: (d) => `New order received on ADDPlus+! Order #${d.orderId}. Amount: KES ${d.amount}. Check your dashboard.`,
      compliance_warning: (d) => `ADDPlus+ Compliance Alert: ${d.message}. Maintain your score to earn profit share!`,
      fine_issued: (d) => `ADDPlus+ Notice: A fine of KES ${d.amount} has been issued for ${d.reason}.`,
      posting_ban: (d) => `ADDPlus+ Alert: Your posting privileges are suspended until ${d.date}. Contact admin.`,
      grant_selected: (d) => `Congratulations! Your ADDPlus+ grant application for KES ${d.amount} has been approved!`
    };

    const messageFn = messages[type];
    if (messageFn) {
      await this.sendSMS(phone, messageFn(data));
    }
  }

  private async sendSMS(to: string, message: string): Promise<void> {
    if (!this.apiKey || !this.username) {
      console.log(`[SMS MOCK] To: ${to}, Message: ${message}`);
      return;
    }

    try {
      const response = await axios.post(
        'https://api.africastalking.com/version1/messaging',
        {
          username: this.username,
          to,
          message,
          from: this.senderId
        },
        {
          headers: {
            'Content-Type': 'application/x-www-form-urlencoded',
            'Accept': 'application/json',
            'apiKey': this.apiKey
          }
        }
      );

      if (response.data.SMSMessageData?.Recipients?.[0]?.status !== 'Success') {
        throw new Error(`SMS failed: ${response.data}`);
      }
    } catch (error) {
      console.error('SMS sending failed:', error);
      throw error;
    }
  }
}
