import { NextRequest, NextResponse } from 'next/server';

function apiBase(): string {
  return (
    process.env.API_URL?.replace(/\/$/, '') ||
    process.env.NEXT_PUBLIC_API_URL?.replace(/\/v1$/, '') ||
    'http://localhost:3001'
  );
}

/** PayHero webhook — proxied to Express API where order confirmation runs. */
export async function POST(req: NextRequest) {
  const target = `${apiBase()}/v1/payments/payhero/callback${req.nextUrl.search}`;
  const body = await req.text();

  const res = await fetch(target, {
    method: 'POST',
    headers: {
      'Content-Type': req.headers.get('content-type') || 'application/json',
      ...(req.headers.get('authorization') ? { Authorization: req.headers.get('authorization')! } : {}),
      ...(req.headers.get('x-payhero-signature')
        ? { 'x-payhero-signature': req.headers.get('x-payhero-signature')! }
        : {}),
      ...(req.headers.get('x-callback-secret')
        ? { 'x-callback-secret': req.headers.get('x-callback-secret')! }
        : {}),
    },
    body,
  });

  const text = await res.text();
  return new NextResponse(text, {
    status: res.status,
    headers: { 'Content-Type': res.headers.get('content-type') || 'application/json' },
  });
}

