import { AppError } from '../middleware/errorHandler'
import prisma from '../config/prisma'
import { fromCents } from '../lib/money'
import { parseJsonArray, stringifyJsonArray, stringifyJsonObject, parseJsonObject } from '../lib/jsonFields'
import { serializeProduct, serializeVendor } from '../lib/serialize'

export class VendorService {
  async getVendorById(vendorId: string) {
    const vendor = await prisma.vendorProfile.findUnique({
      where: { id: vendorId },
      include: {
        user: { select: { id: true, phone: true, full_name: true, created_at: true } },
        products: {
          where: { status: 'APPROVED', deleted_at: null },
          orderBy: { created_at: 'desc' },
          take: 20,
        },
      },
    })
    if (!vendor) throw new AppError('Vendor not found', 404)
    return serializeVendor({ ...vendor, products: vendor.products.map(serializeProduct) })
  }

  async getVendorStorefront(vendorId: string) {
    const vendor = await prisma.vendorProfile.findUnique({
      where: { id: vendorId, kyc_status: 'approved', is_suspended: false },
      select: {
        id: true,
        business_name: true,
        description: true,
        location_lat: true,
        location_lng: true,
        location_address: true,
        business_photos: true,
        referral_code: true,
        created_at: true,
        user: { select: { full_name: true, phone: true } },
        products: {
          where: { status: 'APPROVED', deleted_at: null },
          orderBy: { is_featured: 'desc' },
          include: { category: { select: { id: true, name: true, slug: true } } },
        },
        _count: { select: { products: true } },
      },
    })
    if (!vendor) throw new AppError('Vendor not found or not approved', 404)
    return serializeVendor({ ...vendor, products: vendor.products.map(serializeProduct) })
  }

  async updateVendorProfile(vendorId: string, userId: string, data: any) {
    const vendor = await prisma.vendorProfile.findFirst({ where: { id: vendorId, user_id: userId } })
    if (!vendor) throw new AppError('Vendor not found or unauthorized', 404)

    const updated = await prisma.vendorProfile.update({
      where: { id: vendorId },
      data: {
        business_name: data.business_name,
        description: data.description,
        location_lat: data.location_lat,
        location_lng: data.location_lng,
        location_address: data.location_address,
        mpesa_number: data.mpesa_number,
        business_photos: data.business_photos ? stringifyJsonArray(data.business_photos) : undefined,
        category_ids: data.category_ids ? stringifyJsonArray(data.category_ids) : undefined,
      },
    })
    return serializeVendor(updated)
  }

  async getVendorDashboard(vendorId: string, userId: string) {
    const vendor = await prisma.vendorProfile.findFirst({
      where: { id: vendorId, user_id: userId },
      include: { products: { where: { deleted_at: null }, select: { id: true, status: true } } },
    })
    if (!vendor) throw new AppError('Vendor not found or unauthorized', 404)

    const earnings = await this.getVendorEarnings(vendorId)
    const compliance = await this.getVendorCompliance(vendorId)

    const recentOrders = await prisma.orderItem.findMany({
      where: { vendor_id: vendorId },
      orderBy: { created_at: 'desc' },
      take: 10,
      include: {
        order: { select: { id: true, status: true, created_at: true, customer_id: true } },
        product: { select: { id: true, title: true, images: true } },
      },
    })

    const escrowBalance = await prisma.escrowLedger.aggregate({
      where: { vendor_id: vendorId, status: 'held' },
      _sum: { net_amount_cents: true },
    })

    const orderQueue = await prisma.orderItem.groupBy({
      by: ['item_status'],
      where: { vendor_id: vendorId },
      _count: true,
    })

    return {
      vendor: serializeVendor(vendor),
      stats: {
        total_products: vendor.products.length,
        active_products: vendor.products.filter((p) => p.status === 'APPROVED').length,
        escrow_held_cents: escrowBalance._sum.net_amount_cents || 0,
        escrow_held: fromCents(escrowBalance._sum.net_amount_cents || 0),
      },
      earnings,
      compliance,
      order_queue: orderQueue,
      recent_orders: recentOrders,
    }
  }

  async getMeDashboard(userId: string) {
    const vendor = await prisma.vendorProfile.findUnique({ where: { user_id: userId } })
    if (!vendor) throw new AppError('Vendor profile not found', 404)
    return this.getVendorDashboard(vendor.id, userId)
  }

