        mpesa_number: data.mpesa_number,
        business_photos: data.business_photos ? stringifyJsonArray(data.business_photos) : undefined,
        category_ids: data.category_ids ? stringifyJsonArray(data.category_ids) : undefined,
      },
    })
    return serializeVendor(updated)
  }

  async getVendorDashboard(vendorId: string, userId: string) {
    const vendor = await prisma.vendorProfile.findFirst({
      where: { id: vendorId, user_id: userId },
      include: { products: { where: { deleted_at: null }, select: { id: true, status: true } } },
    })
    if (!vendor) throw new AppError('Vendor not found or unauthorized', 404)

    const earnings = await this.getVendorEarnings(vendorId)
    const compliance = await this.getVendorCompliance(vendorId)

    const recentOrders = await prisma.orderItem.findMany({
      where: { vendor_id: vendorId },
      orderBy: { created_at: 'desc' },
      take: 10,
      include: {
        order: { select: { id: true, status: true, created_at: true, customer_id: true } },
        product: { select: { id: true, title: true, images: true } },
      },
    })

    const escrowBalance = await prisma.escrowLedger.aggregate({
      where: { vendor_id: vendorId, status: 'held' },
      _sum: { net_amount_cents: true },
    })

    const orderQueue = await prisma.orderItem.groupBy({
      by: ['item_status'],
      where: { vendor_id: vendorId },
      _count: true,
    })

    return {
      vendor: serializeVendor(vendor),
      stats: {
        total_products: vendor.products.length,
        active_products: vendor.products.filter((p) => p.status === 'APPROVED').length,
        escrow_held_cents: escrowBalance._sum.net_amount_cents || 0,
        escrow_held: fromCents(escrowBalance._sum.net_amount_cents || 0),
      },
      earnings,
      compliance,
      order_queue: orderQueue,
      recent_orders: recentOrders,
    }
  }

  async getMeDashboard(userId: string) {
    const vendor = await prisma.vendorProfile.findUnique({ where: { user_id: userId } })
    if (!vendor) throw new AppError('Vendor profile not found', 404)
    return this.getVendorDashboard(vendor.id, userId)
  }

