import Link from "next/link";
import { auth } from "@/lib/auth";
import { getMetadataDb } from "@/db/client";
import { tenants, tenantMemberships } from "@/db/schema/metadata";
import { eq, and } from "drizzle-orm";
import { Ban } from "lucide-react";
import { AuthStateShell, StateStatusCard } from "@/components/layout/auth-state-shell";
import { SwitchAccountButton } from "@/components/auth/switch-account-button";
import { Button } from "@/components/ui/button";

export default async function SuspendedPage() {
  const session = await auth();
  let tenantName: string | null = null;

  if (session?.user?.tenantId && session.user.id) {
    const db = getMetadataDb();
    const [row] = await db
      .select({ name: tenants.name })
      .from(tenants)
      .innerJoin(tenantMemberships, eq(tenantMemberships.tenantId, tenants.id))
      .where(
        and(
          eq(tenants.id, session.user.tenantId),
          eq(tenantMemberships.userId, session.user.id),
        ),
      )
      .limit(1);
    tenantName = row?.name ?? null;
  }

  const description = tenantName
    ? `${tenantName} is currently suspended. Contact support to restore access or resolve billing.`
    : "Your workspace is currently suspended. Contact support for assistance.";

  return (
    <AuthStateShell>
      <StateStatusCard title="Account suspended" description={description} icon={Ban} variant="danger">
        <Link href="/contact">
          <Button variant="cta">Contact support</Button>
        </Link>
        <SwitchAccountButton />
      </StateStatusCard>
    </AuthStateShell>
  );
}

