import { cookies } from "next/headers";

export type AppShellSession = {
  role?: string;
  userName?: string | null;
  userId?: string;
};

/** Marketplace session from the httpOnly API cookie bridge (see /api/auth/session). */
export async function getAppShellSession(): Promise<AppShellSession | null> {
  const jar = await cookies();
  const token = jar.get("access_token")?.value;
  const role = jar.get("user_role")?.value;
  if (!token || token.startsWith("demo-") || !role) return null;

  return {
    role,
    userName: jar.get("user_email")?.value ?? null,
  };
}

