"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { Search, Settings, Calendar } from "lucide-react";
import { ThemeToggle } from "@/components/layout/theme-toggle";
import { NotificationBell } from "@/components/layout/notification-bell";
import { cn } from "@/lib/utils";

type TopBarProps = {
  canSearchMarketplace?: boolean;
  canAccessSettings?: boolean;
  className?: string;
};

export function TopBar({
  canSearchMarketplace = true,
  canAccessSettings = false,
  className,
}: TopBarProps) {
  const router = useRouter();
  const today = new Date().toLocaleDateString("en-KE", {
    timeZone: "Africa/Nairobi",
    month: "short",
    day: "numeric",
    year: "numeric",
  });

  return (
    <header
      className={cn(
        "flex flex-col gap-2 border-b border-[var(--border)] bg-[var(--surface)] px-2 py-2 sm:h-12 sm:flex-row sm:flex-wrap sm:items-center sm:gap-2 sm:px-3 sm:py-1.5 lg:px-5",
        className,
      )}
    >
      {canSearchMarketplace && (
        <form
          className="relative flex w-full min-w-0 flex-1 sm:max-w-md"
          onSubmit={(e) => {
            e.preventDefault();
            const fd = new FormData(e.currentTarget);
            const q = String(fd.get("q") ?? "").trim();
            if (!q) return;
            router.push(`/marketplace?q=${encodeURIComponent(q)}`);
          }}
        >
          <div className="relative min-w-0 flex-1">
            <Search className="absolute left-2.5 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-[var(--text-secondary)]" />
            <input
              name="q"
              placeholder="Search marketplace…"
              className="h-9 w-full rounded-lg border border-[var(--border)] bg-[var(--surface-alt)] pl-8 pr-2 text-sm text-[var(--text-primary)] placeholder:text-[var(--muted)] focus:outline-none focus:ring-2 focus:ring-primary/30"
            />
          </div>
        </form>
      )}

      <div className="flex w-full items-center justify-between gap-1.5 sm:w-auto sm:justify-end">
        <ThemeToggle />
        <NotificationBell />
        {canAccessSettings && (
          <Link
            href="/settings"
            className="flex h-9 w-9 items-center justify-center rounded-lg border border-[var(--border)] bg-[var(--surface-alt)] text-[var(--text-primary)] hover:bg-[var(--brand-primary-light)] hover:text-primary"
            aria-label="Settings"
          >
            <Settings className="h-4 w-4" />
          </Link>
        )}
        <div className="hidden items-center gap-1.5 rounded-lg border border-[var(--border)] bg-[var(--surface-alt)] px-2 py-1 text-xs text-[var(--text-primary)] sm:flex">
          <Calendar className="h-3.5 w-3.5 text-primary" />
          {today}
        </div>
      </div>
    </header>
  );
}

