import { auth } from "@/lib/auth";
import { Suspense } from "react";
import { Sidebar } from "@/components/layout/sidebar";
import { AppHeader } from "@/components/layout/app-header";
import { MobileNav } from "@/components/layout/mobile-nav";
import { OfflineBanner } from "@/components/app/offline-banner";
import { AccessBanner } from "@/components/app/access-banner";
import { OfflineProvider } from "@/components/providers/offline-provider";
import { ActionFeedback } from "@/components/app/action-feedback";
import { isCurrentUserPlatformAdmin } from "@/lib/actions/platform";
import { getProfileForUser } from "@/lib/actions/profile";
import { getTenantAccessForUser } from "@/lib/tenant";
import { getAppShellSession } from "@/lib/app-shell-session";

export default async function AppLayout({ children }: { children: React.ReactNode }) {
  const shell = await getAppShellSession();
  const session = await auth();
  const isPlatformAdmin = shell?.isApiUser
    ? shell.role === "admin"
    : await isCurrentUserPlatformAdmin();
  const profile =
    !shell?.isApiUser && session?.user?.id
      ? await getProfileForUser(session.user.id)
      : null;
  const access =
    !shell?.isApiUser && session?.user?.id && session.user.tenantId
      ? await getTenantAccessForUser(session.user.id, session.user.tenantId)
      : null;

  return (
    <OfflineProvider>
      <Suspense fallback={null}>
        <ActionFeedback />
      </Suspense>
      <div className="min-h-screen bg-[var(--surface-page)] p-1 sm:p-2 md:p-3">
        <div className="mx-auto flex min-h-[calc(100vh-0.5rem)] max-w-[1600px] overflow-hidden rounded-xl border border-[var(--border)] bg-[var(--surface)] shadow-shell sm:min-h-[calc(100vh-1rem)] sm:rounded-[16px]">
          <Sidebar
            role={shell?.role ?? session?.user?.role}
            userName={profile?.name ?? session?.user?.name}
            avatarUrl={profile?.avatarUrl}
            isPlatformAdmin={isPlatformAdmin}
          />
          <div className="flex min-w-0 flex-1 flex-col">
            {access && <AccessBanner mode={access.mode} trialEndsAt={access.trialEndsAt} />}
            <OfflineBanner />
            <AppHeader />
            <main className="flex-1 overflow-auto p-2 pb-16 sm:p-3 md:pb-3 lg:p-4">{children}</main>
          </div>
        </div>
        <MobileNav role={shell?.role ?? session?.user?.role} />
      </div>
    </OfflineProvider>
  );
}

