import { NextResponse } from "next/server";
import { canAccessPath, isAppPath } from "@/lib/rbac-routes";

/**
 * Marketplace-only middleware.
 *
 * Sessions come from the httpOnly cookie bridge set by POST /api/auth/session
 * (which validates the token against the Express API before setting cookies).
 */
function getMarketplaceSession(req: {
  cookies: { get: (name: string) => { value: string } | undefined };
}) {
  const token = req.cookies.get("access_token")?.value;
  const role = req.cookies.get("user_role")?.value;
  if (token && role && !token.startsWith("demo-")) {
    return { role };
  }
  return null;
}

const PUBLIC_ROUTES = [
  "/",
  "/login",
  "/signup",
  "/pricing",
  "/how-it-works",
  "/faq",
  "/privacy",
  "/terms",
  "/about",
  "/contact",
  "/status",
  "/compare",
  "/marketplace",
  "/cart",
  "/wishlist",
  "/vendors",
  "/vendor/register",
];
const PUBLIC_PREFIXES = ["/products/", "/vendors/", "/orders/", "/suspended", "/trial-expired", "/verify-email", "/forgot-password", "/reset-password"];

export default function middleware(req: { nextUrl: URL; cookies: { get: (name: string) => { value: string } | undefined } }) {
  const { pathname } = req.nextUrl;
  const session = getMarketplaceSession(req);
  const isPublic = PUBLIC_ROUTES.includes(pathname) || PUBLIC_PREFIXES.some((p) => pathname.startsWith(p));
  const isAdminRoute = pathname === "/admin" || pathname.startsWith("/admin/");

  if (isAdminRoute) {
    if (!session) return NextResponse.redirect(new URL("/login", req.url));
    if (session.role !== "admin") {
      const home = session.role === "vendor" ? "/dashboard" : "/account";
      return NextResponse.redirect(new URL(`${home}?error=forbidden`, req.url));
    }
    return NextResponse.next();
  }

  if (isAppPath(pathname) && !session) {
    return NextResponse.redirect(new URL("/login", req.url));
  }

  if (isAppPath(pathname) && session && !canAccessPath(session.role, pathname)) {
    const home =
      session.role === "admin"
        ? "/admin"
        : session.role === "vendor"
          ? "/dashboard"
          : "/account";
    return NextResponse.redirect(new URL(`${home}?error=forbidden`, req.url));
  }

  if (!isPublic && !session && !pathname.startsWith("/api")) {
    if (isAppPath(pathname)) {
      return NextResponse.redirect(new URL("/login", req.url));
    }
  }

  return NextResponse.next();
}

export const config = {
  matcher: ["/((?!api/auth|_next/static|_next/image|favicon.ico|icons|manifest|sw.js).*)"],
};

