import { auth } from "@/lib/auth";
import { NextResponse } from "next/server";
import { canAccessPath, isAppPath } from "@/lib/rbac-routes";
import { isPlatformAdmin } from "@/lib/platform-admin";
import type { TenantStatus } from "@/lib/auth-urls";

const TRIAL_EXPIRED_ALLOWED = ["/settings", "/api/payments"];

function trialExpiredMayAccess(pathname: string): boolean {
  return TRIAL_EXPIRED_ALLOWED.some(
    (prefix) => pathname === prefix || pathname.startsWith(`${prefix}/`),
  );
}

function getMarketplaceSession(req: {
  cookies: { get: (name: string) => { value: string } | undefined };
}) {
  const token = req.cookies.get("access_token")?.value;
  const role = req.cookies.get("user_role")?.value;
  if (token && role && !token.startsWith("demo-")) {
    return { role, isApiAuth: true as const };
  }
  return null;
}

export default auth((req) => {
  const { pathname } = req.nextUrl;
  const marketplace = getMarketplaceSession(req);
  const isApiUser = !!marketplace;
  const isLoggedIn = !!req.auth || isApiUser;
  const hasTenant = isApiUser ? true : !!req.auth?.user?.tenantId;
  const role = req.auth?.user?.role ?? marketplace?.role;
  const apiEmail = req.cookies.get("user_email")?.value;
  const apiEmailVerified = req.cookies.get("email_verified")?.value === "1";
  const emailVerified = isApiUser
    ? !apiEmail || apiEmailVerified
    : (req.auth?.user?.isEmailVerified ?? false);
  const email = req.auth?.user?.email;
  const tenantStatus = req.auth?.user?.tenantStatus as TenantStatus | undefined;

  const publicRoutes = [
    "/",
    "/login",
    "/signup",
    "/accept-invite",
    "/pricing",
    "/how-it-works",
    "/faq",
    "/privacy",
    "/terms",
    "/about",
    "/contact",
    "/compare",
    "/status",
    "/marketplace",
    "/cart",
    "/wishlist",
    "/vendors",
    "/vendor/register",
  ];
  const publicPrefixes = ["/products/", "/vendors/", "/orders/"];
  const isPublicPrefix = publicPrefixes.some((p) => pathname.startsWith(p));
  const emailRoutes = ["/verify-email", "/forgot-password", "/reset-password", "/accept-invite", "/suspended", "/trial-expired"];
  const isPublic = publicRoutes.includes(pathname) || isPublicPrefix;
  const isEmailRoute = emailRoutes.some((r) => pathname === r || pathname.startsWith(`${r}/`));
  const isOnboarding = pathname === "/onboarding";
  const isAppRoute = isAppPath(pathname) || pathname.startsWith("/admin");
  const isAdminRoute = pathname === "/admin" || pathname.startsWith("/admin/");

  if (!isApiUser && isLoggedIn && tenantStatus === "suspended" && isAppRoute) {
    return NextResponse.redirect(new URL("/suspended", req.url));
  }

  if (
    !isApiUser &&
    isLoggedIn &&
    tenantStatus === "trial_expired" &&
    isAppRoute &&
    !trialExpiredMayAccess(pathname)
  ) {
    return NextResponse.redirect(new URL("/trial-expired", req.url));
  }

  if (isAdminRoute) {
    if (!isLoggedIn) return NextResponse.redirect(new URL("/login", req.url));
    const isAdmin =
      role === "platform_admin" ||
      role === "admin" ||
      marketplace?.role === "admin" ||
      isPlatformAdmin(email);
    if (!isAdmin) {
      const home = role === "vendor" ? "/dashboard" : "/account";
      return NextResponse.redirect(new URL(`${home}?error=forbidden`, req.url));
    }
  }

  if (isApiUser && apiEmail && !apiEmailVerified && !isEmailRoute && isAppRoute) {
    const next = encodeURIComponent(pathname);
    return NextResponse.redirect(new URL(`/verify-email?next=${next}`, req.url));
  }

  if (req.auth && !emailVerified && !isEmailRoute && pathname.startsWith("/api") && !pathname.startsWith("/api/auth")) {
    return NextResponse.json({ error: "Email not verified" }, { status: 403 });
  }

  if (req.auth && !emailVerified && !isEmailRoute && !pathname.startsWith("/api")) {
    return NextResponse.redirect(new URL("/verify-email", req.url));
  }

  if (isAppRoute && !isLoggedIn) {
    return NextResponse.redirect(new URL("/login", req.url));
  }

  if (isAppRoute && req.auth && !hasTenant) {
    return NextResponse.redirect(new URL("/onboarding", req.url));
  }

  if (isAppRoute && isLoggedIn && !canAccessPath(role, pathname)) {
    const home =
      role === "platform_admin" || role === "admin"
        ? "/admin"
        : role === "vendor"
          ? "/dashboard"
          : "/account";
    return NextResponse.redirect(new URL(`${home}?error=forbidden`, req.url));
  }

  if (isOnboarding && isLoggedIn && hasTenant) {
    const home =
      role === "platform_admin" || role === "admin"
        ? "/admin"
        : role === "vendor"
          ? "/dashboard"
          : "/account";
    return NextResponse.redirect(new URL(home, req.url));
  }

  if (isOnboarding && !isLoggedIn) {
    return NextResponse.redirect(new URL("/login", req.url));
  }

  if (!isPublic && !isLoggedIn && !pathname.startsWith("/api") && !isEmailRoute) {
    if (isAppRoute || isOnboarding) {
      return NextResponse.redirect(new URL("/login", req.url));
    }
  }

  return NextResponse.next();
});

export const config = {
  matcher: ["/((?!api/auth|_next/static|_next/image|favicon.ico|icons|manifest|sw.js).*)"],
};

