import axios from 'axios';
import { secureStorage } from './secureStorage';

const API_URL =
  process.env.NEXT_PUBLIC_API_URL ||
  (typeof window !== 'undefined' && window.location.hostname.endsWith('.vercel.app')
    ? '/v1'
    : 'http://localhost:3001/v1');

export const apiClient = axios.create({
  baseURL: API_URL,
  headers: {
    'Content-Type': 'application/json',
  },
});

// Request interceptor to add auth token
apiClient.interceptors.request.use(
  (config) => {
    // SECURITY: Use secure storage instead of direct localStorage access
    const token = secureStorage.getAccessToken();
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// Response interceptor to handle errors
apiClient.interceptors.response.use(
  (response) => response,
  async (error) => {
    const originalRequest = error.config;

    // Handle token refresh
    if (error.response?.status === 401 && !originalRequest._retry) {
      originalRequest._retry = true;

      try {
        if (typeof window === 'undefined') return Promise.reject(error);
        const refreshToken = secureStorage.getRefreshToken();
        if (!refreshToken || refreshToken.startsWith('demo-')) {
          return Promise.reject(error);
        }

        const response = await axios.post(`${API_URL}/auth/token/refresh`, {
          refreshToken,
        });

        const { accessToken, refreshToken: newRefresh } = response.data;
        secureStorage.setAccessToken(accessToken);
        if (newRefresh) secureStorage.setRefreshToken(newRefresh);

        const user = secureStorage.getUser();
        if (user) {
          await fetch('/api/auth/session', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              token: accessToken,
              refresh: newRefresh ?? refreshToken,
              user,
            }),
          }).catch(() => undefined);
        }

        originalRequest.headers.Authorization = `Bearer ${accessToken}`;
        return apiClient(originalRequest);
      } catch (refreshError) {
        // SECURITY: Clear tokens on refresh failure
        secureStorage.clear();
        if (typeof window !== 'undefined') {
          await fetch('/api/auth/session', { method: 'DELETE' }).catch(() => undefined);
        }
        return Promise.reject(refreshError);
      }
    }

    return Promise.reject(error);
  }
);

// API functions
export const authAPI = {
  login: (identifier: string, password: string) =>
    apiClient.post('/auth/login', { identifier, password }),
  setupPassword: (phone: string, password: string) =>
    apiClient.post('/auth/password/setup', { phone, password }),
  register: (phone: string, email: string, password: string, full_name?: string) =>
    apiClient.post('/auth/register', {
      phone,
      email,
      password,
      ...(full_name ? { full_name } : {}),
    }),
  verifyEmail: (payload: { token?: string; code?: string; email?: string }) =>
    apiClient.post('/auth/verify-email', payload),
  resendVerificationEmail: () => apiClient.post('/auth/verify-email/resend'),
  forgotPassword: (email: string) => apiClient.post('/auth/forgot-password', { email }),
  resetPassword: (token: string, password: string) =>
    apiClient.post('/auth/reset-password', { token, password }),
  requestOTP: (phone: string) => apiClient.post('/auth/otp/request', { phone }),
  verifyOTP: (phone: string, code: string, full_name?: string) =>
    apiClient.post('/auth/otp/verify', { phone, code, ...(full_name ? { full_name } : {}) }),
  registerVendor: (data: any) => apiClient.post('/auth/register/vendor', data),
  logout: () => apiClient.post('/auth/logout'),
  registerPushToken: (token: string) => apiClient.post('/auth/push-token', { token }),
};

export const productsAPI = {
  getAll: (params?: any) => apiClient.get('/products', { params }),
  getMyProducts: (params?: any) => apiClient.get('/products/vendor/me', { params }),
  getById: (id: string) => apiClient.get(`/products/${id}`),
  getRelated: (id: string, limit = 6) => apiClient.get(`/products/${id}/related`, { params: { limit } }),
  search: (q: string, params?: any) => apiClient.get('/products/search', { params: { q, ...params } }),
  getFeatured: (limit = 10) => apiClient.get('/products/featured', { params: { limit } }),
  getTrending: (limit = 10) => apiClient.get('/products/trending', { params: { limit } }),
  getCategories: () => apiClient.get('/products/categories'),
  create: (data: any) => apiClient.post('/products', data),
  update: (id: string, data: any) => apiClient.put(`/products/${id}`, data),
  delete: (id: string) => apiClient.delete(`/products/${id}`),
};

export const vendorsAPI = {
  getAll: (params?: any) => apiClient.get('/vendors', { params }),
  getById: (id: string) => apiClient.get(`/vendors/${id}`),
  getMe: () => apiClient.get('/vendors/me'),
  getMyDashboard: () => apiClient.get('/vendors/me/dashboard'),
  getMyEarnings: () => apiClient.get('/vendors/me/earnings'),
  getDashboard: (id: string) => apiClient.get(`/vendors/${id}/dashboard`),
  update: (id: string, data: any) => apiClient.put(`/vendors/${id}`, data),
};

export const ordersAPI = {
  create: (data: any) => apiClient.post('/orders', data),
  initiatePayment: (orderId: string, phone: string) => apiClient.post(`/orders/${orderId}/pay`, { phone }),
  getById: (id: string) => apiClient.get(`/orders/${id}`),
  getCustomerOrders: (customerId: string, params?: any) => 
    apiClient.get(`/orders/customer/${customerId}`, { params }),
  getMyVendorOrders: (params?: any) => apiClient.get('/orders/vendor/me', { params }),
  getVendorOrders: (vendorId: string, params?: any) =>
    apiClient.get(`/orders/vendor/${vendorId}`, { params }),
  confirmDelivery: (orderItemId: string) => apiClient.put(`/orders/${orderItemId}/confirm-delivery`),
  openDispute: (orderItemId: string, data: any) => apiClient.post(`/orders/${orderItemId}/dispute`, data),
  updateItemStatus: (itemId: string, status: string) => apiClient.put(`/orders/${itemId}/status`, { status }),
};

export const fundAPI = {
  getBalance: () => apiClient.get('/fund/balance'),
  getLedger: (params?: any) => apiClient.get('/fund/ledger', { params }),
  getGrants: (params?: any) => apiClient.get('/fund/grants', { params }),
  getContributions: (vendorId: string) => apiClient.get(`/fund/contributions/${vendorId}`),
  applyForGrant: (data: any) => apiClient.post('/fund/grants/apply', data),
  approveGrant: (id: string, data: any) => apiClient.post(`/fund/grants/${id}/approve`, data),
  rejectGrant: (id: string, reason: string) => apiClient.post(`/fund/grants/${id}/reject`, { reason }),
};

export const uploadsAPI = {
  uploadProductImages: (formData: FormData) =>
    apiClient.post('/uploads/products', formData, { headers: { 'Content-Type': 'multipart/form-data' } }),
  uploadVendorPhoto: (formData: FormData) =>
    apiClient.post('/uploads/vendor-profile', formData, { headers: { 'Content-Type': 'multipart/form-data' } }),
  uploadComplianceImages: (formData: FormData) =>
    apiClient.post('/uploads/compliance', formData, { headers: { 'Content-Type': 'multipart/form-data' } }),
};

export const complianceAPI = {
  createPost: (data: any) => apiClient.post('/compliance/posts', data),
  logReferral: (data: any) => apiClient.post('/compliance/referrals', data),
  getMyScore: () => apiClient.get('/compliance/me/score'),
  getMyCalendar: (days?: number) => apiClient.get('/compliance/me/calendar', { params: { days } }),
  getScore: (vendorId: string) => apiClient.get(`/compliance/${vendorId}/score`),
  getCalendar: (vendorId: string, days?: number) => 
    apiClient.get(`/compliance/${vendorId}/calendar`, { params: { days } }),
};

export const adminAPI = {
  getDashboard: () => apiClient.get('/admin/dashboard'),
  getHealth: () => apiClient.get('/admin/health'),
  getOrders: (params?: any) => apiClient.get('/admin/orders', { params }),
  getPendingVendors: () => apiClient.get('/admin/vendors/pending'),
  approveVendor: (id: string) => apiClient.post(`/admin/vendors/${id}/approve`),
  rejectVendor: (id: string, reason: string) => apiClient.post(`/admin/vendors/${id}/reject`, { reason }),
  suspendVendor: (id: string, reason?: string) =>
    apiClient.post(`/admin/vendors/${id}/suspend`, { reason }),
  getPendingProducts: () => apiClient.get('/admin/products/pending'),
  moderateProduct: (id: string, action: 'approve' | 'reject', reason?: string) =>
    apiClient.put(`/admin/products/${id}/moderate`, { action, reason }),
  getDisputes: (params?: any) => apiClient.get('/admin/disputes', { params }),
  resolveDispute: (id: string, data: any) => apiClient.put(`/admin/disputes/${id}/resolve`, data),
  getInsights: (params?: any) => apiClient.get('/admin/insights', { params }),
  createInsight: (data: any) => apiClient.post('/admin/insights', data),
  issueFine: (data: any) => apiClient.post('/compliance/fines', data),
};

